UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Posée sur l''assemblage dominicain que la famille Fuente affine depuis quatre générations, cette cape brésilienne crée un profil de contraste saisissant. L''assemblage Fuente est connu pour son élégance — cèdre, crème de café, épice discrète — et la cape maduro y ajoute une couche de douceur sombre qui approfondit sans écraser. Il en résulte des notes d''expresso chocolaté, de figue sèche, et une longue finale de cacao noir qui se prolonge bien après la dernière bouffée.

' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Posée sur l''assemblage dominicain que la famille Fuente affine depuis quatre générations, cette cape brésilienne crée un profil de contraste saisissant. L''assemblage Fuente est connu pour son élégance — cèdre, crème de café, épice discrète — et la cape maduro y ajoute une couche de douceur sombre qui approfondit sans écraser. Il en résulte des notes d''expresso chocolaté, de figue sèche, et une longue finale de cacao noir qui se prolonge bien après la dernière bouffée.

', ''), `history`),
