UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('

La gamme existe en tension féconde avec l''Opus X, au sommet du catalogue Fuente. Là où l''Opus X est la maison à son intensité maximale — pleine puissance dominicaine, cape dominicaine, exigeant et hors norme —, le Maduro propose un raisonnement parallèle : le tabac brésilien, sur la même base dominicaine, peut produire une complexité d''une tout autre nature, bâtie sur la douceur et la profondeur plutôt que sur la puissance et l''épice.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, '

