-- ── CAO Cameroon ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''histoire du tabac camerounais dans le cigare premium est d''abord celle d''une découverte retardée par la géographie. La province du Centre — sols équatoriaux, humidité constante, températures qui varient à peine d''un mois à l''autre — produit une cape que rien de ce qui pousse aux Amériques ne reproduit. Elle est plus sombre que le Connecticut Shade, plus complexe de structure, et porte une teneur naturelle en huiles qui la rend reconnaissable à l''œil et puissante au nez dès la coupe.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''histoire du tabac camerounais dans le cigare premium est d''abord celle d''une découverte retardée par la géographie. La province du Centre — sols équatoriaux, humidité constante, températures qui varient à peine d''un mois à l''autre — produit une cape que rien de ce qui pousse aux Amériques ne reproduit. Elle est plus sombre que le Connecticut Shade, plus complexe de structure, et porte une teneur naturelle en huiles qui la rend reconnaissable à l''œil et puissante au nez dès la coupe.', 'CAO Cameroon, que la maison et les détaillants appellent aussi Cameroon L''Anniversaire, est une ligne de la marque CAO lancée en 1998 pour les 30 ans de la maison, que ce détaillant (cigarsdirect.com) date de 1968. Les détaillants la décrivent avec une cape camerounaise, un liant et une tripe nicaraguayens, et une force moyenne.'), `history`),
  `history_en` = IF(LOCATE(CAST('The story of Cameroonian tobacco in premium cigars is largely a story of discovery delayed by geography. The Centre province of Cameroon — a region of equatorial soils, consistent humidity, and temperatures that barely vary month to month — produces a wrapper leaf unlike anything grown in the Americas. It is darker in color than Connecticut shade, more complex in structure, and carries a natural oil content that makes it visually distinctive and aromatically potent from the moment the cigar is cut.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The story of Cameroonian tobacco in premium cigars is largely a story of discovery delayed by geography. The Centre province of Cameroon — a region of equatorial soils, consistent humidity, and temperatures that barely vary month to month — produces a wrapper leaf unlike anything grown in the Americas. It is darker in color than Connecticut shade, more complex in structure, and carries a natural oil content that makes it visually distinctive and aromatically potent from the moment the cigar is cut.', 'CAO Cameroon, which the house and retailers also call Cameroon L''Anniversaire, is a line from the CAO brand launched in 1998 for the house''s 30th anniversary, which this retailer (cigarsdirect.com) dates to 1968. Retailers describe it with a Cameroonian wrapper, a Nicaraguan binder and filler, and medium strength.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La historia del tabaco camerunés en el puro premium es ante todo la de un descubrimiento retrasado por la geografía. La provincia del Centro —suelos ecuatoriales, humedad constante, temperaturas que apenas varían de un mes a otro— produce una capa que nada de cuanto crece en América reproduce. Es más oscura que el Connecticut Shade, de estructura más compleja, y lleva un contenido natural en aceites que la hace reconocible a la vista y potente en nariz desde el corte.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La historia del tabaco camerunés en el puro premium es ante todo la de un descubrimiento retrasado por la geografía. La provincia del Centro —suelos ecuatoriales, humedad constante, temperaturas que apenas varían de un mes a otro— produce una capa que nada de cuanto crece en América reproduce. Es más oscura que el Connecticut Shade, de estructura más compleja, y lleva un contenido natural en aceites que la hace reconocible a la vista y potente en nariz desde el corte.', 'CAO Cameroon, que la casa y los comerciantes llaman también Cameroon L''Anniversaire, es una línea de la marca CAO lanzada en 1998 para los 30 años de la casa, que este comerciante (cigarsdirect.com) fecha en 1968. Los comerciantes la describen con una capa camerunesa, un capote y una tripa nicaragüenses, y una fuerza media.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Geschichte des kamerunischen Tabaks in der Premiumzigarre ist zuerst die einer Entdeckung, die von der Geografie aufgehalten wurde. Die Zentralprovinz — äquatoriale Böden, gleichbleibende Feuchte, Temperaturen, die von Monat zu Monat kaum schwanken — bringt ein Deckblatt hervor, das nichts von dem, was in Amerika wächst, nachbildet. Es ist dunkler als das Connecticut Shade, im Bau vielschichtiger, und trägt einen natürlichen Ölgehalt, der es mit dem Auge erkennbar und ab dem Schnitt in der Nase kräftig macht.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Geschichte des kamerunischen Tabaks in der Premiumzigarre ist zuerst die einer Entdeckung, die von der Geografie aufgehalten wurde. Die Zentralprovinz — äquatoriale Böden, gleichbleibende Feuchte, Temperaturen, die von Monat zu Monat kaum schwanken — bringt ein Deckblatt hervor, das nichts von dem, was in Amerika wächst, nachbildet. Es ist dunkler als das Connecticut Shade, im Bau vielschichtiger, und trägt einen natürlichen Ölgehalt, der es mit dem Auge erkennbar und ab dem Schnitt in der Nase kräftig macht.', 'CAO Cameroon, das das Haus und Händler auch Cameroon L''Anniversaire nennen, ist eine Linie der Marke CAO, die 1998 zum 30-jährigen Bestehen des Hauses eingeführt wurde, dessen Gründung dieser Händler (cigarsdirect.com) auf 1968 datiert. Händler beschreiben sie mit einem kamerunischen Deckblatt, einem nicaraguanischen Umblatt und einer nicaraguanischen Einlage und mittlerer Stärke.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('喀麦隆烟叶在高端雪茄中的故事，首先是一段被地理耽误的发现。中部省——赤道土壤、恒定湿度、月与月之间几乎不变的气温——出产的茄衣，是美洲任何产地都复制不出来的。它比康涅狄格阴植叶更深，结构更复杂，天然含油量让它一眼可辨，切开即在鼻端显出力量。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '喀麦隆烟叶在高端雪茄中的故事，首先是一段被地理耽误的发现。中部省——赤道土壤、恒定湿度、月与月之间几乎不变的气温——出产的茄衣，是美洲任何产地都复制不出来的。它比康涅狄格阴植叶更深，结构更复杂，天然含油量让它一眼可辨，切开即在鼻端显出力量。', 'CAO Cameroon，字号与零售商也称其为 Cameroon L''Anniversaire，是 CAO 品牌的一条产品线，于1998年为字号成立30周年而推出，该零售商（cigarsdirect.com）将这一时间定在1968年。零售商描述其为喀麦隆茄衣，配尼加拉瓜茄套与茄芯，浓度中等。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تاريخ التبغ الكاميروني في السيجار الفاخر هو أوّلًا تاريخ اكتشاف أخّرته الجغرافيا. فالمقاطعة الوسطى — تربة استوائية، ورطوبة ثابتة، وحرارة لا تكاد تتغيّر من شهر إلى آخر — تنتج غلافًا لا يعيد إنتاجه شيء مما ينبت في الأمريكتين. إنه أدكن من كونيتيكت شيد، وأعقد بنيةً، ويحمل نسبة زيوت طبيعية تجعله معروفًا بالعين وقويًّا في الأنف منذ القطع.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تاريخ التبغ الكاميروني في السيجار الفاخر هو أوّلًا تاريخ اكتشاف أخّرته الجغرافيا. فالمقاطعة الوسطى — تربة استوائية، ورطوبة ثابتة، وحرارة لا تكاد تتغيّر من شهر إلى آخر — تنتج غلافًا لا يعيد إنتاجه شيء مما ينبت في الأمريكتين. إنه أدكن من كونيتيكت شيد، وأعقد بنيةً، ويحمل نسبة زيوت طبيعية تجعله معروفًا بالعين وقويًّا في الأنف منذ القطع.', 'CAO Cameroon، التي تسمّيها الدار والتجّار أيضًا Cameroon L''Anniversaire، خطّ من علامة CAO أُطلق عام 1998 بمناسبة مرور 30 عامًا على الدار، وهو ما يؤرّخه هذا التاجر (cigarsdirect.com) بعام 1968. يصفها التجّار بغلاف كاميروني وغلاف داخلي وحشوة نيكاراغويّين، وبقوة متوسطة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Cameroon';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('CAO fut l''une des premières maisons américaines à bâtir une gamme entière sur ce terroir. La gamme Cameroon emploie la cape AVO XO — une sélection précise de la province du Centre, qui représente le haut du panier de la feuille camerounaise arrivant sur le marché américain. Sa complexité s''impose d''emblée : un caractère cacaoté prononcé, entre chocolat au lait et chocolat noir, doublé d''une douceur naturelle qui contredit l''épice de l''assemblage au lieu de l''amplifier.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'CAO fut l''une des premières maisons américaines à bâtir une gamme entière sur ce terroir. La gamme Cameroon emploie la cape AVO XO — une sélection précise de la province du Centre, qui représente le haut du panier de la feuille camerounaise arrivant sur le marché américain. Sa complexité s''impose d''emblée : un caractère cacaoté prononcé, entre chocolat au lait et chocolat noir, doublé d''une douceur naturelle qui contredit l''épice de l''assemblage au lieu de l''amplifier.', 'Elle est roulée au Nicaragua : la fiche d''une revue à l''aveugle de Blind Man''s Puff (28 février 2024, vitola Robusto) donne la fabrique STG Estelí et le Nicaragua pour origine ; d''autres détaillants donnent aussi le Nicaragua, sans nommer la fabrique. Aucune page lue ne place cette ligne au Honduras. Quant à l''appellation de cape « AVO XO », aucune page lue ne la porte.'), `history`),
  `history_en` = IF(LOCATE(CAST('CAO was among the first American manufacturers to build an entire range around this terroir. The CAO Cameroon line uses the AVO XO wrapper — a specific selection from the Centre province that represents the top tier of Cameroonian leaf reaching the American market. The wrapper''s complexity is immediately evident: a pronounced cocoa character that sits between milk chocolate and dark, combined with a natural sweetness that counters rather than amplifies the blend''s spice. The effect is a profile of unusual sophistication for a mid-priced range.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'CAO was among the first American manufacturers to build an entire range around this terroir. The CAO Cameroon line uses the AVO XO wrapper — a specific selection from the Centre province that represents the top tier of Cameroonian leaf reaching the American market. The wrapper''s complexity is immediately evident: a pronounced cocoa character that sits between milk chocolate and dark, combined with a natural sweetness that counters rather than amplifies the blend''s spice. The effect is a profile of unusual sophistication for a mid-priced range.', 'It is rolled in Nicaragua: the listing for a Blind Man''s Puff blind review (28 February 2024, Robusto vitola) gives the STG Estelí factory and Nicaragua as the origin; other retailers also give Nicaragua, without naming the factory. No page read places this line in Honduras. As for the "AVO XO" wrapper designation, no page read carries it.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('CAO fue una de las primeras casas estadounidenses en levantar una gama entera sobre este terruño. La gama Cameroon emplea la capa AVO XO —una selección precisa de la provincia del Centro, que representa lo más alto de la hoja camerunesa que llega al mercado estadounidense. Su complejidad se impone de entrada: un carácter cacaotado pronunciado, entre chocolate con leche y chocolate negro, doblado de una dulzura natural que contradice la especia de la ligada en lugar de amplificarla.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'CAO fue una de las primeras casas estadounidenses en levantar una gama entera sobre este terruño. La gama Cameroon emplea la capa AVO XO —una selección precisa de la provincia del Centro, que representa lo más alto de la hoja camerunesa que llega al mercado estadounidense. Su complejidad se impone de entrada: un carácter cacaotado pronunciado, entre chocolate con leche y chocolate negro, doblado de una dulzura natural que contradice la especia de la ligada en lugar de amplificarla.', 'Se tuerce en Nicaragua: la ficha de una cata a ciegas de Blind Man''s Puff (28 de febrero de 2024, vitola Robusto) da la fábrica STG Estelí y Nicaragua como origen; otros comerciantes dan también Nicaragua, sin nombrar la fábrica. Ninguna página leída sitúa esta línea en Honduras. En cuanto a la denominación de capa «AVO XO», ninguna página leída la lleva.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('CAO war eines der ersten amerikanischen Häuser, das eine ganze Linie auf diesen Boden stellte. Die Linie Cameroon verwendet das AVO-XO-Deckblatt — eine genaue Auslese aus der Zentralprovinz, die das Beste des kamerunischen Blattes darstellt, das auf den amerikanischen Markt gelangt. Ihre Vielschichtigkeit setzt sich sofort durch: ein ausgeprägter Kakaocharakter, zwischen Milchschokolade und Zartbitterschokolade, verdoppelt von einer natürlichen Süße, die der Würze der Mischung widerspricht, statt sie zu verstärken.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'CAO war eines der ersten amerikanischen Häuser, das eine ganze Linie auf diesen Boden stellte. Die Linie Cameroon verwendet das AVO-XO-Deckblatt — eine genaue Auslese aus der Zentralprovinz, die das Beste des kamerunischen Blattes darstellt, das auf den amerikanischen Markt gelangt. Ihre Vielschichtigkeit setzt sich sofort durch: ein ausgeprägter Kakaocharakter, zwischen Milchschokolade und Zartbitterschokolade, verdoppelt von einer natürlichen Süße, die der Würze der Mischung widerspricht, statt sie zu verstärken.', 'Sie wird in Nicaragua gerollt: Der Eintrag zu einer Blindverkostung von Blind Man''s Puff (28. Februar 2024, Vitola Robusto) nennt die Fabrik STG Estelí und Nicaragua als Herkunft; andere Händler nennen ebenfalls Nicaragua, ohne die Fabrik zu nennen. Keine gelesene Seite verortet diese Linie in Honduras. Die Deckblattbezeichnung „AVO XO“ trägt keine gelesene Seite.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CAO 是最早把整条产品线建立在这片风土上的美国字号之一。喀麦隆系列用的是 AVO XO 茄衣——来自中部省的精确选料，代表进入美国市场的喀麦隆叶中最好的一档。它的复杂度一上来就压得住：可可感鲜明，介于牛奶巧克力与黑巧克力之间，又叠着一层天然的甜，与配方里的香料相抵而非相加。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CAO 是最早把整条产品线建立在这片风土上的美国字号之一。喀麦隆系列用的是 AVO XO 茄衣——来自中部省的精确选料，代表进入美国市场的喀麦隆叶中最好的一档。它的复杂度一上来就压得住：可可感鲜明，介于牛奶巧克力与黑巧克力之间，又叠着一层天然的甜，与配方里的香料相抵而非相加。', '它在尼加拉瓜手工卷制：Blind Man''s Puff 一次盲测的资料页（2024年2月28日，Robusto 规格）给出的工厂是 STG Estelí，产地为尼加拉瓜；其他零售商也给出尼加拉瓜，但未点出工厂。所读页面均未把这条产品线置于洪都拉斯。至于“AVO XO”这一茄衣名称，所读页面均未出现。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('كانت CAO من أوائل الدور الأمريكية التي بنت تشكيلة كاملة على هذه الأرض. تستعمل تشكيلة الكاميرون غلاف AVO XO — انتقاء دقيق من المقاطعة الوسطى، يمثّل أعلى ما يصل من الورقة الكاميرونية إلى السوق الأمريكية. يفرض تركيبها نفسه من البداية: طابع كاكاوي واضح، بين الشوكولاتة بالحليب والشوكولاتة الداكنة، تضاعفه حلاوة طبيعية تناقض توابل الخلطة بدل أن تضخّمها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'كانت CAO من أوائل الدور الأمريكية التي بنت تشكيلة كاملة على هذه الأرض. تستعمل تشكيلة الكاميرون غلاف AVO XO — انتقاء دقيق من المقاطعة الوسطى، يمثّل أعلى ما يصل من الورقة الكاميرونية إلى السوق الأمريكية. يفرض تركيبها نفسه من البداية: طابع كاكاوي واضح، بين الشوكولاتة بالحليب والشوكولاتة الداكنة، تضاعفه حلاوة طبيعية تناقض توابل الخلطة بدل أن تضخّمها.', 'تُلفّ في نيكاراغوا: صفحة تذوّق أعمى لدى Blind Man''s Puff (28 فبراير 2024، قياس Robusto) تذكر مصنع STG Estelí ونيكاراغوا منشأً؛ ويذكر تجّار آخرون نيكاراغوا أيضًا دون تسمية المصنع. ولا تضع أيّ صفحة مقروءة هذا الخطّ في هندوراس. أما تسمية الغلاف «AVO XO» فلا تحملها أيّ صفحة مقروءة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Cameroon';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Sous cette cape, la tripe associe des tabacs dominicains et brésiliens choisis pour accompagner la feuille plutôt que lui disputer la place. Il en résulte un cigare qui ouvre sur le chocolat et un poivre doux, évolue vers le café et la cerise séchée, et s''achève sur une longue note de cèdre légèrement sucrée — une démonstration de ce qu''une cape bien choisie peut faire d''un assemblage par ailleurs classique.

' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Sous cette cape, la tripe associe des tabacs dominicains et brésiliens choisis pour accompagner la feuille plutôt que lui disputer la place. Il en résulte un cigare qui ouvre sur le chocolat et un poivre doux, évolue vers le café et la cerise séchée, et s''achève sur une longue note de cèdre légèrement sucrée — une démonstration de ce qu''une cape bien choisie peut faire d''un assemblage par ailleurs classique.

', ''), `history`),
  `history_en` = IF(LOCATE(CAST(CONCAT('The blend beneath the Cameroonian wrapper uses Dominican and Brazilian fillers chosen to complement rather than compete with the wrapper''s character. The result is a cigar that leads with chocolate and soft pepper on the first third, develops toward coffee and dried cherry in the middle, and finishes with a long, slightly sweet cedar note that demonstrates how well-selected wrapper tobacco can transform an otherwise conventional Nicaraguan-Dominican blend into something memorable.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, CONCAT('The blend beneath the Cameroonian wrapper uses Dominican and Brazilian fillers chosen to complement rather than compete with the wrapper''s character. The result is a cigar that leads with chocolate and soft pepper on the first third, develops toward coffee and dried cherry in the middle, and finishes with a long, slightly sweet cedar note that demonstrates how well-selected wrapper tobacco can transform an otherwise conventional Nicaraguan-Dominican blend into something memorable.', CHAR(13), '
', CHAR(13), '
'), ''), `history_en`),
  `history_es` = IF(LOCATE(CAST('Bajo esa capa, la tripa asocia tabacos dominicanos y brasileños escogidos para acompañar a la hoja más que para disputarle el sitio. El resultado es un puro que abre con chocolate y una pimienta suave, evoluciona hacia el café y la cereza seca, y acaba en una larga nota de cedro ligeramente dulce —una demostración de lo que una capa bien elegida puede hacer con una ligada por lo demás clásica.

' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Bajo esa capa, la tripa asocia tabacos dominicanos y brasileños escogidos para acompañar a la hoja más que para disputarle el sitio. El resultado es un puro que abre con chocolate y una pimienta suave, evoluciona hacia el café y la cereza seca, y acaba en una larga nota de cedro ligeramente dulce —una demostración de lo que una capa bien elegida puede hacer con una ligada por lo demás clásica.

', ''), `history_es`),
  `history_de` = IF(LOCATE(CAST('Unter diesem Deckblatt verbindet die Einlage dominikanische und brasilianische Tabake, die gewählt wurden, um das Blatt zu begleiten, statt ihm den Platz streitig zu machen. Daraus entsteht eine Zigarre, die mit Schokolade und milder Pfefferschärfe öffnet, sich zu Kaffee und getrockneter Kirsche entwickelt und in einer langen, leicht süßen Zedernote endet — eine Vorführung dessen, was ein gut gewähltes Deckblatt aus einer sonst klassischen Mischung machen kann.

' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Unter diesem Deckblatt verbindet die Einlage dominikanische und brasilianische Tabake, die gewählt wurden, um das Blatt zu begleiten, statt ihm den Platz streitig zu machen. Daraus entsteht eine Zigarre, die mit Schokolade und milder Pfefferschärfe öffnet, sich zu Kaffee und getrockneter Kirsche entwickelt und in einer langen, leicht süßen Zedernote endet — eine Vorführung dessen, was ein gut gewähltes Deckblatt aus einer sonst klassischen Mischung machen kann.

', ''), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这张茄衣之下，茄芯把多米尼加与巴西烟草配在一起，选它们是为了陪衬叶子，而不是与之争位。做出来的雪茄以巧克力与柔和胡椒开场，转向咖啡与干樱桃，收在一段微甜的雪松长尾上——这是一次印证：一张选对的茄衣，能把一副本来经典的配方带到哪里。

' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这张茄衣之下，茄芯把多米尼加与巴西烟草配在一起，选它们是为了陪衬叶子，而不是与之争位。做出来的雪茄以巧克力与柔和胡椒开场，转向咖啡与干樱桃，收在一段微甜的雪松长尾上——这是一次印证：一张选对的茄衣，能把一副本来经典的配方带到哪里。

', ''), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وتحت هذا الغلاف، تجمع الحشوة تبغًا دومينيكيًّا وبرازيليًّا اختير ليرافق الورقة لا لينازعها مكانها. والنتيجة سيجار يفتتح بالشوكولاتة وفلفل لطيف، ثم ينتقل إلى القهوة والكرز المجفّف، وينتهي بنَفَس طويل من خشب الأرز المحلّى قليلًا — برهان على ما يمكن لغلاف حسن الاختيار أن يفعله بخلطة كلاسيكية في ما عدا ذلك.

' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وتحت هذا الغلاف، تجمع الحشوة تبغًا دومينيكيًّا وبرازيليًّا اختير ليرافق الورقة لا لينازعها مكانها. والنتيجة سيجار يفتتح بالشوكولاتة وفلفل لطيف، ثم ينتقل إلى القهوة والكرز المجفّف، وينتهي بنَفَس طويل من خشب الأرز المحلّى قليلًا — برهان على ما يمكن لغلاف حسن الاختيار أن يفعله بخلطة كلاسيكية في ما عدا ذلك.

', ''), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Cameroon';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le tabac camerounais a gagné l''attention du marché premium en partie grâce à CAO, en partie par son emploi dans la série Millennium de Davidoff. Quand les grandes manufactures se sont mises à en acheter massivement, l''offre disponible s''est resserrée. La position de pionnier de CAO lui vaut, auprès des producteurs d''Afrique centrale, une relation d''approvisionnement que les entrants plus récents peinent à établir.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le tabac camerounais a gagné l''attention du marché premium en partie grâce à CAO, en partie par son emploi dans la série Millennium de Davidoff. Quand les grandes manufactures se sont mises à en acheter massivement, l''offre disponible s''est resserrée. La position de pionnier de CAO lui vaut, auprès des producteurs d''Afrique centrale, une relation d''approvisionnement que les entrants plus récents peinent à établir.', 'Des détaillants décrivent des notes de noix, de toast, de cèdre, d''épices douces et de café (JR Cigars, cité en résultat de recherche) ; ces descriptions varient d''un site à l''autre. La marque CAO appartient aujourd''hui à General Cigar, groupe STG : des articles la disent vendue à Scandinavian Tobacco Group en 2007 puis rangée sous General Cigar après la fusion de 2010 (résultats de recherche, non ouverts : à confirmer avant publication).'), `history`),
  `history_en` = IF(LOCATE(CAST('Cameroonian tobacco reached serious attention in the premium market partly through CAO''s advocacy and partly through its use in Davidoff''s prized Millennium series. Once major manufacturers began sourcing it aggressively, the available supply tightened considerably. CAO Cameroon''s position as an early adopter gives it a sourcing relationship with Central African growers that newer entrants to the category have struggled to match.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Cameroonian tobacco reached serious attention in the premium market partly through CAO''s advocacy and partly through its use in Davidoff''s prized Millennium series. Once major manufacturers began sourcing it aggressively, the available supply tightened considerably. CAO Cameroon''s position as an early adopter gives it a sourcing relationship with Central African growers that newer entrants to the category have struggled to match.', 'Retailers describe notes of nuts, toast, cedar, mild spices and coffee (JR Cigars, cited as a search result); these descriptions vary from one site to another. The CAO brand now belongs to General Cigar, part of the STG group: articles say it was sold to Scandinavian Tobacco Group in 2007 and then placed under General Cigar after the 2010 merger (search results, not opened: to be confirmed before publication).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El tabaco camerunés ganó la atención del mercado premium en parte gracias a CAO, en parte por su empleo en la serie Millennium de Davidoff. Cuando las grandes manufacturas empezaron a comprarlo masivamente, la oferta disponible se estrechó. La posición de pionera de CAO le vale, ante los productores de África central, una relación de abastecimiento que los entrantes más recientes tienen dificultad en establecer.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El tabaco camerunés ganó la atención del mercado premium en parte gracias a CAO, en parte por su empleo en la serie Millennium de Davidoff. Cuando las grandes manufacturas empezaron a comprarlo masivamente, la oferta disponible se estrechó. La posición de pionera de CAO le vale, ante los productores de África central, una relación de abastecimiento que los entrantes más recientes tienen dificultad en establecer.', 'Algunos comerciantes describen notas de nuez, tostado, cedro, especias suaves y café (JR Cigars, citado como resultado de búsqueda); estas descripciones varían de un sitio a otro. La marca CAO pertenece hoy a General Cigar, del grupo STG: varios artículos dicen que fue vendida a Scandinavian Tobacco Group en 2007 y luego integrada en General Cigar tras la fusión de 2010 (resultados de búsqueda, no abiertos: por confirmar antes de publicar).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Der kamerunische Tabak gewann die Aufmerksamkeit des Premiummarktes teils dank CAO, teils durch seinen Einsatz in Davidoffs Millennium-Serie. Als die großen Manufakturen ihn in Mengen zu kaufen begannen, wurde das verfügbare Angebot knapp. Ihre Pionierstellung verschafft CAO bei den Erzeugern Zentralafrikas eine Lieferbeziehung, die spätere Anbieter nur mühsam aufbauen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Der kamerunische Tabak gewann die Aufmerksamkeit des Premiummarktes teils dank CAO, teils durch seinen Einsatz in Davidoffs Millennium-Serie. Als die großen Manufakturen ihn in Mengen zu kaufen begannen, wurde das verfügbare Angebot knapp. Ihre Pionierstellung verschafft CAO bei den Erzeugern Zentralafrikas eine Lieferbeziehung, die spätere Anbieter nur mühsam aufbauen.', 'Händler beschreiben Noten von Nuss, Toast, Zedernholz, milden Gewürzen und Kaffee (JR Cigars, als Suchergebnis zitiert); diese Beschreibungen schwanken von Seite zu Seite. Die Marke CAO gehört heute zu General Cigar, Teil der STG-Gruppe: Artikel besagen, sie sei 2007 an Scandinavian Tobacco Group verkauft und nach der Fusion von 2010 unter General Cigar eingeordnet worden (Suchergebnisse, nicht geöffnet: vor der Veröffentlichung zu bestätigen).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('喀麦隆烟叶得到高端市场的注意，一半靠 CAO，一半靠它在大卫杜夫千禧系列中的使用。当大厂开始大量买入，可得的货源便收紧了。作为先行者，CAO 在中非产区拥有一层供货关系，后来者很难建立。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '喀麦隆烟叶得到高端市场的注意，一半靠 CAO，一半靠它在大卫杜夫千禧系列中的使用。当大厂开始大量买入，可得的货源便收紧了。作为先行者，CAO 在中非产区拥有一层供货关系，后来者很难建立。', '零售商描述的风味有坚果、烤面包、雪松、柔和香料与咖啡（JR Cigars，作为搜索结果引用）；这些描述因网站而异。CAO 品牌如今隶属 General Cigar，属 STG 集团：有文章称其于2007年售予 Scandinavian Tobacco Group，2010年合并后归入 General Cigar（搜索结果，未打开：发布前须核实）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('نال التبغ الكاميروني انتباه السوق الفاخرة بفضل CAO من جهة، وبفضل استعماله في سلسلة ميلينيوم لدى دافيدوف من جهة أخرى. وحين بدأت المصانع الكبرى تشتريه بكثافة، ضاق المعروض المتاح. ويمنح موقعُ الريادة شركةَ CAO لدى منتجي وسط أفريقيا علاقةَ تزويد يصعب على الوافدين الجدد بناؤها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'نال التبغ الكاميروني انتباه السوق الفاخرة بفضل CAO من جهة، وبفضل استعماله في سلسلة ميلينيوم لدى دافيدوف من جهة أخرى. وحين بدأت المصانع الكبرى تشتريه بكثافة، ضاق المعروض المتاح. ويمنح موقعُ الريادة شركةَ CAO لدى منتجي وسط أفريقيا علاقةَ تزويد يصعب على الوافدين الجدد بناؤها.', 'يصف بعض التجّار نكهات الجوز والخبز المحمّص والأرز والتوابل اللطيفة والقهوة (JR Cigars، مذكور بوصفه نتيجة بحث)؛ وتتفاوت هذه الأوصاف من موقع إلى آخر. تعود علامة CAO اليوم إلى General Cigar، من مجموعة STG: تقول مقالات إنها بيعت إلى Scandinavian Tobacco Group عام 2007 ثم أُدرجت تحت General Cigar بعد اندماج 2010 (نتائج بحث لم تُفتح: يلزم التأكد قبل النشر).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Cameroon';

UPDATE `brands` SET
  `country_id` = 'nicaragua',
  `founded` = '1998 (L''Anniversaire, selon des détaillants)',
  `factory` = 'STG Estelí, Nicaragua (dit Blind Man''s Puff, 2024) ; cape du Cameroun, liant et tripe nicaraguayens',
  `gamme` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"Cape camerounaise sur liant et tripe nicaraguayens, roulée au Nicaragua (STG Estelí, selon Blind Man''s Puff, 2024). Force moyenne selon cette revue ; certains détaillants la classent de moyenne à corsée. Formats donnés par des détaillants : Perfecto 4 x 48, Robusto 5 x 50, Toro 5 1/2 x 55, Belicoso 6 x 54, Churchill 6 7/8 x 48.","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"Cameroun"}]',
  `gamme_en` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"Cameroonian wrapper over a Nicaraguan binder and filler, rolled in Nicaragua (STG Estelí, according to Blind Man''s Puff, 2024). Medium strength according to that review; some retailers rate it from medium to full. Sizes given by retailers: Perfecto 4 x 48, Robusto 5 x 50, Toro 5 1/2 x 55, Belicoso 6 x 54, Churchill 6 7/8 x 48.","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"Cameroon"}]',
  `gamme_es` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"Capa camerunesa sobre capote y tripa nicaragüenses, torcida en Nicaragua (STG Estelí, según Blind Man''s Puff, 2024). Fuerza media según esa revista; algunos comerciantes la clasifican de media a fuerte. Formatos dados por comerciantes: Perfecto 4 x 48, Robusto 5 x 50, Toro 5 1/2 x 55, Belicoso 6 x 54, Churchill 6 7/8 x 48.","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"Camerún"}]',
  `gamme_de` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"Kamerun-Deckblatt über nicaraguanischem Umblatt und nicaraguanischer Einlage, in Nicaragua gerollt (STG Estelí, laut Blind Man''s Puff, 2024). Mittlere Stärke laut dieser Zeitschrift; manche Händler stufen sie von mittel bis kräftig ein. Von Händlern genannte Formate: Perfecto 4 x 48, Robusto 5 x 50, Toro 5 1/2 x 55, Belicoso 6 x 54, Churchill 6 7/8 x 48.","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"Kamerun"}]',
  `gamme_zh` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"喀麦隆茄衣，配尼加拉瓜茄套与茄芯，在尼加拉瓜卷制（STG Estelí，据 Blind Man''s Puff，2024年）。据该刊浓度中等；一些零售商将其归为中等至浓郁。零售商给出的规格：Perfecto 4 x 48，Robusto 5 x 50，Toro 5 1/2 x 55，Belicoso 6 x 54，Churchill 6 7/8 x 48。","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"喀麦隆"}]',
  `gamme_ar` = '[{"name":"CAO Cameroon","color":"#8B6914","force":"Medium","story":"غلاف كاميروني على غلاف داخلي وحشوة نيكاراغويّين، يُلفّ في نيكاراغوا (STG Estelí، بحسب Blind Man''s Puff، 2024). قوة متوسطة بحسب تلك المجلة؛ ويصنّفها بعض التجّار من متوسطة إلى قوية. القياسات التي أوردها التجّار: Perfecto 4 x 48، Robusto 5 x 50، Toro 5 1/2 x 55، Belicoso 6 x 54، Churchill 6 7/8 x 48.","vitolas":["Toro","Churchill","Robusto","Figurado"],"wrapper":"الكاميرون"}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('caocigars.com et cigaraficionado.com — FICHE DE CAPE : cape du Cameroun sur un cigare roulé chez General Cigar, à Danlí' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'caocigars.com et cigaraficionado.com — FICHE DE CAPE : cape du Cameroun sur un cigare roulé chez General Cigar, à Danlí', 'blindmanspuff.com « CAO Cameroon L''Anniversaire Robusto » (28 février 2024 : STG Estelí, Nicaragua, cape Cameroon, liant et tripe Nicaragua, 1998, Medium) ; cigarsdirect.com « CAO L''Anniversaire Cameroon » (lancée en 1998 pour les 30 ans de CAO, fondée en 1968) ; cigarplace.biz « CAO Cameroon » (octobre 2026 : fabriquée au Nicaragua, tripe et liant nicaraguayens) ; coronacigar.com « CAO Cameroon L''Anniversaire Toro » (octobre 2026 : origine Nicaragua)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Cameroon';

-- ── CAO Black ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La vallée mexicaine de San Andrés s''étend dans l''État de Veracruz, entre la côte du golfe du Mexique et les volcans de l''Orizaba, à des altitudes de 800 à 1 200 mètres. Sols volcaniques, humidité constante apportée par les masses d''air du golfe, températures tempérées par l''altitude : ces conditions donnent un tabac qui ne ressemble à aucun autre sur le continent américain. La feuille de San Andrés est sombre — naturellement, sans la fermentation prolongée qui produit les maduros du Connecticut ou du Brésil — et porte une amertume particulière, que les assembleurs recherchent pour sa capacité à tenir un assemblage face à la douceur des tripes plus légères.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La vallée mexicaine de San Andrés s''étend dans l''État de Veracruz, entre la côte du golfe du Mexique et les volcans de l''Orizaba, à des altitudes de 800 à 1 200 mètres. Sols volcaniques, humidité constante apportée par les masses d''air du golfe, températures tempérées par l''altitude : ces conditions donnent un tabac qui ne ressemble à aucun autre sur le continent américain. La feuille de San Andrés est sombre — naturellement, sans la fermentation prolongée qui produit les maduros du Connecticut ou du Brésil — et porte une amertume particulière, que les assembleurs recherchent pour sa capacité à tenir un assemblage face à la douceur des tripes plus légères.', 'CAO Black est une ligne de la maison CAO, présentée par un détaillant (cigarworld.com, octobre 2026) comme la première ligne régulière de CAO, sans date. Elle porte une cape Connecticut d''Équateur et un liant nicaraguayen, sur une tripe longfiller de Nicaragua, du Honduras et du Mexique (cigarplace.biz, cigarworld.com, octobre 2026).'), `history`),
  `history_en` = IF(LOCATE(CAST('The Mexican San Andrés valley sits in the state of Veracruz, between the Gulf of Mexico coast and the Orizaba volcanic range, at elevations between 800 and 1,200 meters. The combination of volcanic soil, consistent humidity from Gulf air masses, and altitude-modulated temperatures creates conditions that produce tobacco unlike any other in the Americas. San Andrés leaf is dark — naturally, without the extended fermentation that produces Connecticut or Brazilian Maduro — and carries a specific bitterness that blenders prize for its ability to anchor a blend against the sweetness of lighter fillers.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Mexican San Andrés valley sits in the state of Veracruz, between the Gulf of Mexico coast and the Orizaba volcanic range, at elevations between 800 and 1,200 meters. The combination of volcanic soil, consistent humidity from Gulf air masses, and altitude-modulated temperatures creates conditions that produce tobacco unlike any other in the Americas. San Andrés leaf is dark — naturally, without the extended fermentation that produces Connecticut or Brazilian Maduro — and carries a specific bitterness that blenders prize for its ability to anchor a blend against the sweetness of lighter fillers.', 'CAO Black is a line from the house of CAO, presented by a retailer (cigarworld.com, October 2026) as CAO''s first regular line, without a date. It has an Ecuadorian Connecticut wrapper and a Nicaraguan binder, over a longfiller of Nicaragua, Honduras and Mexico (cigarplace.biz, cigarworld.com, October 2026).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El valle mexicano de San Andrés se extiende en el estado de Veracruz, entre la costa del golfo de México y los volcanes del Orizaba, a altitudes de 800 a 1.200 metros. Suelos volcánicos, humedad constante traída por las masas de aire del golfo, temperaturas templadas por la altitud: esas condiciones dan un tabaco que no se parece a ningún otro del continente americano. La hoja de San Andrés es oscura —de forma natural, sin la fermentación prolongada que produce los maduros del Connecticut o de Brasil— y lleva un amargor particular, que los ligadores buscan por su capacidad de sostener una ligada frente a la suavidad de las tripas más ligeras.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El valle mexicano de San Andrés se extiende en el estado de Veracruz, entre la costa del golfo de México y los volcanes del Orizaba, a altitudes de 800 a 1.200 metros. Suelos volcánicos, humedad constante traída por las masas de aire del golfo, temperaturas templadas por la altitud: esas condiciones dan un tabaco que no se parece a ningún otro del continente americano. La hoja de San Andrés es oscura —de forma natural, sin la fermentación prolongada que produce los maduros del Connecticut o de Brasil— y lleva un amargor particular, que los ligadores buscan por su capacidad de sostener una ligada frente a la suavidad de las tripas más ligeras.', 'CAO Black es una línea de la casa CAO, presentada por un comerciante (cigarworld.com, octubre de 2026) como la primera línea regular de CAO, sin fecha. Lleva una capa Connecticut de Ecuador y un capote nicaragüense, sobre una tripa de hoja larga de Nicaragua, Honduras y México (cigarplace.biz, cigarworld.com, octubre de 2026).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das mexikanische Tal von San Andrés liegt im Bundesstaat Veracruz, zwischen der Golfküste und den Vulkanen des Orizaba, in Höhen von 800 bis 1.200 Metern. Vulkanische Böden, gleichbleibende Feuchte, die die Luftmassen des Golfs heranführen, von der Höhe gemäßigte Temperaturen: Diese Bedingungen ergeben einen Tabak, der keinem anderen auf dem amerikanischen Kontinent gleicht. Das Blatt aus San Andrés ist dunkel — von Natur aus, ohne die verlängerte Fermentation, die die Maduros aus Connecticut oder Brasilien hervorbringt — und trägt eine eigentümliche Bitterkeit, die Mischer suchen, weil sie eine Mischung gegen die Milde leichterer Einlagen zu tragen vermag.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das mexikanische Tal von San Andrés liegt im Bundesstaat Veracruz, zwischen der Golfküste und den Vulkanen des Orizaba, in Höhen von 800 bis 1.200 Metern. Vulkanische Böden, gleichbleibende Feuchte, die die Luftmassen des Golfs heranführen, von der Höhe gemäßigte Temperaturen: Diese Bedingungen ergeben einen Tabak, der keinem anderen auf dem amerikanischen Kontinent gleicht. Das Blatt aus San Andrés ist dunkel — von Natur aus, ohne die verlängerte Fermentation, die die Maduros aus Connecticut oder Brasilien hervorbringt — und trägt eine eigentümliche Bitterkeit, die Mischer suchen, weil sie eine Mischung gegen die Milde leichterer Einlagen zu tragen vermag.', 'CAO Black ist eine Linie des Hauses CAO, von einem Händler (cigarworld.com, Oktober 2026) als erste reguläre Linie von CAO vorgestellt, ohne Datum. Sie trägt ein Connecticut-Deckblatt aus Ecuador und ein nicaraguanisches Umblatt, über einer Longfiller-Einlage aus Nicaragua, Honduras und Mexiko (cigarplace.biz, cigarworld.com, Oktober 2026).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('墨西哥的圣安德烈斯河谷位于韦拉克鲁斯州，夹在墨西哥湾海岸与奥里萨巴的火山之间，海拔在800到1200米。火山土壤、由海湾气团带来的恒定湿度、被海拔调低的气温：这些条件长出的烟草，在美洲大陆上没有第二处相似。圣安德烈斯的叶子天生就深——不需要康涅狄格或巴西马杜罗所依赖的长时间发酵——并带着一种特别的苦，调配师看重的正是它在更轻茄芯的柔顺面前撑住整副配方的能力。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '墨西哥的圣安德烈斯河谷位于韦拉克鲁斯州，夹在墨西哥湾海岸与奥里萨巴的火山之间，海拔在800到1200米。火山土壤、由海湾气团带来的恒定湿度、被海拔调低的气温：这些条件长出的烟草，在美洲大陆上没有第二处相似。圣安德烈斯的叶子天生就深——不需要康涅狄格或巴西马杜罗所依赖的长时间发酵——并带着一种特别的苦，调配师看重的正是它在更轻茄芯的柔顺面前撑住整副配方的能力。', 'CAO Black 是 CAO 字号的一条产品线，一家零售商（cigarworld.com，2026年10月）称其为 CAO 的首条常规产品线，未给日期。它用厄瓜多尔康涅狄格茄衣与尼加拉瓜茄套，茄芯为长叶烟丝，产自尼加拉瓜、洪都拉斯与墨西哥（cigarplace.biz，cigarworld.com，2026年10月）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يمتدّ وادي سان أندريس المكسيكي في ولاية فيراكروس، بين ساحل خليج المكسيك وبراكين أوريسابا، على ارتفاعات تتراوح بين 800 و1200 متر. تربة بركانية، ورطوبة ثابتة تحملها كتل هواء الخليج، وحرارة يلطّفها الارتفاع: هذه الشروط تعطي تبغًا لا يشبه سواه في القارة الأمريكية. فورقة سان أندريس داكنة — بطبيعتها، دون التخمير المطوَّل الذي ينتج مادورو كونيتيكت أو البرازيل — وتحمل مرارة خاصة يقصدها الخلّاطون لقدرتها على حمل الخلطة في مواجهة لطف الحشوات الأخفّ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يمتدّ وادي سان أندريس المكسيكي في ولاية فيراكروس، بين ساحل خليج المكسيك وبراكين أوريسابا، على ارتفاعات تتراوح بين 800 و1200 متر. تربة بركانية، ورطوبة ثابتة تحملها كتل هواء الخليج، وحرارة يلطّفها الارتفاع: هذه الشروط تعطي تبغًا لا يشبه سواه في القارة الأمريكية. فورقة سان أندريس داكنة — بطبيعتها، دون التخمير المطوَّل الذي ينتج مادورو كونيتيكت أو البرازيل — وتحمل مرارة خاصة يقصدها الخلّاطون لقدرتها على حمل الخلطة في مواجهة لطف الحشوات الأخفّ.', 'CAO Black خطّ من دار CAO، قدّمه أحد التجّار (cigarworld.com، أكتوبر 2026) بوصفه أول خطّ منتظم لدى CAO، دون تاريخ. غلافه كونيتيكت من الإكوادور وغلافه الداخلي نيكاراغوي، على حشوة طويلة الأوراق من نيكاراغوا وهندوراس والمكسيك (cigarplace.biz، cigarworld.com، أكتوبر 2026).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Black';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La cape San Andrés Maduro de la gamme Black pousse ce terroir à son terme. La feuille, déjà sombre à l''état naturel, subit une fermentation prolongée qui la mène jusqu''au presque noir et transforme son amertume en un caractère épicé complexe. Le résultat n''est pas une couleur ajoutée mais une feuille qui a fermenté à l''intensité maximale sans céder structurellement.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La cape San Andrés Maduro de la gamme Black pousse ce terroir à son terme. La feuille, déjà sombre à l''état naturel, subit une fermentation prolongée qui la mène jusqu''au presque noir et transforme son amertume en un caractère épicé complexe. Le résultat n''est pas une couleur ajoutée mais une feuille qui a fermenté à l''intensité maximale sans céder structurellement.', 'Un détaillant (cigarplace.biz, octobre 2026) la dit d''abord fabriquée au Honduras ; aucune page lue ne nomme la fabrique actuelle. À ne pas confondre avec CAO Black VR, ligne distincte à cape brésilienne (Stogie Review, 5 mars 2008).'), `history`),
  `history_en` = IF(LOCATE(CAST('The San Andrés Maduro wrapper used in CAO Black is this terroir taken to its logical extreme. The already-dark natural San Andrés leaf is subjected to extended fermentation that pushes its color toward near-black and transforms its natural bitterness into a complex spice character. The result is the darkest commercially available Honduran-blend wrapper in the major American catalog — not in the artificial sense of added color, but in the genuine agricultural sense of leaf that has fermented at maximum intensity without structural failure.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The San Andrés Maduro wrapper used in CAO Black is this terroir taken to its logical extreme. The already-dark natural San Andrés leaf is subjected to extended fermentation that pushes its color toward near-black and transforms its natural bitterness into a complex spice character. The result is the darkest commercially available Honduran-blend wrapper in the major American catalog — not in the artificial sense of added color, but in the genuine agricultural sense of leaf that has fermented at maximum intensity without structural failure.', 'A retailer (cigarplace.biz, October 2026) says it was first made in Honduras; no page read names the current factory. Not to be confused with CAO Black VR, a separate line with a Brazilian wrapper (Stogie Review, 5 March 2008).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La capa San Andrés Maduro de la gama Black lleva ese terruño hasta el final. La hoja, ya oscura en estado natural, pasa por una fermentación prolongada que la conduce hasta el casi negro y transforma su amargor en un carácter especiado complejo. El resultado no es un color añadido sino una hoja que ha fermentado a la intensidad máxima sin ceder estructuralmente.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La capa San Andrés Maduro de la gama Black lleva ese terruño hasta el final. La hoja, ya oscura en estado natural, pasa por una fermentación prolongada que la conduce hasta el casi negro y transforma su amargor en un carácter especiado complejo. El resultado no es un color añadido sino una hoja que ha fermentado a la intensidad máxima sin ceder estructuralmente.', 'Un comerciante (cigarplace.biz, octubre de 2026) dice que se fabricó primero en Honduras; ninguna página leída nombra la fábrica actual. No debe confundirse con CAO Black VR, línea distinta de capa brasileña (Stogie Review, 5 de marzo de 2008).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das San-Andrés-Maduro-Deckblatt der Linie Black führt diesen Boden zu Ende. Das schon im Naturzustand dunkle Blatt durchläuft eine verlängerte Fermentation, die es bis fast ins Schwarze führt und seine Bitterkeit in einen vielschichtigen würzigen Charakter verwandelt. Das Ergebnis ist keine aufgesetzte Farbe, sondern ein Blatt, das mit äußerster Intensität fermentiert hat, ohne im Aufbau nachzugeben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das San-Andrés-Maduro-Deckblatt der Linie Black führt diesen Boden zu Ende. Das schon im Naturzustand dunkle Blatt durchläuft eine verlängerte Fermentation, die es bis fast ins Schwarze führt und seine Bitterkeit in einen vielschichtigen würzigen Charakter verwandelt. Das Ergebnis ist keine aufgesetzte Farbe, sondern ein Blatt, das mit äußerster Intensität fermentiert hat, ohne im Aufbau nachzugeben.', 'Ein Händler (cigarplace.biz, Oktober 2026) sagt, sie sei zuerst in Honduras gefertigt worden; keine gelesene Seite nennt die heutige Fabrik. Nicht zu verwechseln mit CAO Black VR, einer eigenen Linie mit brasilianischem Deckblatt (Stogie Review, 5. März 2008).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Black 系列的圣安德烈斯马杜罗茄衣把这片风土推到了尽头。本就深色的叶子经过延长发酵，被带到近乎全黑，苦味也转成了复杂的香料感。结果不是外加的颜色，而是一片在最大强度下完成发酵、结构却没有垮掉的叶子。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Black 系列的圣安德烈斯马杜罗茄衣把这片风土推到了尽头。本就深色的叶子经过延长发酵，被带到近乎全黑，苦味也转成了复杂的香料感。结果不是外加的颜色，而是一片在最大强度下完成发酵、结构却没有垮掉的叶子。', '一家零售商（cigarplace.biz，2026年10月）称其起初在洪都拉斯制造；所读页面均未点出现今的工厂。切勿与 CAO Black VR 混淆，那是另一条产品线，用巴西茄衣（Stogie Review，2008年3月5日）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ويأخذ غلاف «سان أندريس مادورو» في تشكيلة «بلاك» هذه الأرض إلى منتهاها. فالورقة، الداكنة أصلًا في حالتها الطبيعية، تمرّ بتخمير مطوَّل يبلغ بها حدّ السواد تقريبًا ويحوّل مرارتها إلى طابع توابلي مركّب. والنتيجة ليست لونًا مضافًا بل ورقة خمّرت عند أقصى شدّة دون أن تتراجع بنيتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ويأخذ غلاف «سان أندريس مادورو» في تشكيلة «بلاك» هذه الأرض إلى منتهاها. فالورقة، الداكنة أصلًا في حالتها الطبيعية، تمرّ بتخمير مطوَّل يبلغ بها حدّ السواد تقريبًا ويحوّل مرارتها إلى طابع توابلي مركّب. والنتيجة ليست لونًا مضافًا بل ورقة خمّرت عند أقصى شدّة دون أن تتراجع بنيتها.', 'يقول أحد التجّار (cigarplace.biz، أكتوبر 2026) إنه صُنع أولًا في هندوراس؛ ولا تسمّي أيّ صفحة مقروءة المصنع الحالي. لا يُخلط بينه وبين CAO Black VR، وهو خطّ مستقلّ بغلاف برازيلي (Stogie Review، 5 مارس 2008).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Black';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Sur la tripe nicaraguayenne et hondurienne que CAO emploie dans tout son catalogue premium, cette cape crée un profil sans équivalent dans la gamme. Le premier tiers donne du cacao pur — ni sucré ni dilué, l''amertume franche du chocolat de couverture. Le deuxième introduit réglisse et poivre de Cayenne, dans une combinaison qui rappelle le mole mexicain — ce n''est pas un hasard : la tradition des piments de San Andrés cohabite avec celle du tabac. Le dernier tiers s''achève sur une finale longue et chaude d''épices sombres et d''expresso.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Sur la tripe nicaraguayenne et hondurienne que CAO emploie dans tout son catalogue premium, cette cape crée un profil sans équivalent dans la gamme. Le premier tiers donne du cacao pur — ni sucré ni dilué, l''amertume franche du chocolat de couverture. Le deuxième introduit réglisse et poivre de Cayenne, dans une combinaison qui rappelle le mole mexicain — ce n''est pas un hasard : la tradition des piments de San Andrés cohabite avec celle du tabac. Le dernier tiers s''achève sur une finale longue et chaude d''épices sombres et d''expresso.', 'Les détaillants la décrivent de force moyenne à medium-full, avec des notes de crème, de cèdre et de poivre ; les avis divergent d''un détaillant à l''autre. Les tailles listées par cigarworld.com portent des noms propres : Frontier, Gothic, Bengal, Mosaic, Storm.'), `history`),
  `history_en` = IF(LOCATE(CAST('Over the Nicaraguan-Honduran filler blend that CAO uses throughout its premium catalog, this wrapper creates a profile of exceptional distinctiveness. The first third delivers pure cocoa — not sweetened, not diluted, but the aggressive bitterness of unsweetened baking chocolate. The middle third introduces licorice and Cayenne pepper in a combination that recalls the flavor profile of Mexican mole sauce, which is not coincidental: the same San Andrés pepper-growing tradition that produces the region''s famous chiles exists alongside its tobacco cultivation. The final third resolves toward a long, warming finish of dark spice and espresso.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Over the Nicaraguan-Honduran filler blend that CAO uses throughout its premium catalog, this wrapper creates a profile of exceptional distinctiveness. The first third delivers pure cocoa — not sweetened, not diluted, but the aggressive bitterness of unsweetened baking chocolate. The middle third introduces licorice and Cayenne pepper in a combination that recalls the flavor profile of Mexican mole sauce, which is not coincidental: the same San Andrés pepper-growing tradition that produces the region''s famous chiles exists alongside its tobacco cultivation. The final third resolves toward a long, warming finish of dark spice and espresso.', 'Retailers describe it as medium to medium-full in strength, with notes of cream, cedar and pepper; opinions differ from one retailer to another. The sizes listed by cigarworld.com have proper names: Frontier, Gothic, Bengal, Mosaic, Storm.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Sobre la tripa nicaragüense y hondureña que CAO emplea en todo su catálogo premium, esa capa crea un perfil sin equivalente en la gama. El primer tercio da cacao puro —ni azucarado ni diluido, el amargor franco del chocolate de cobertura. El segundo introduce regaliz y pimienta de Cayena, en una combinación que recuerda el mole mexicano —y no es casualidad: la tradición de los chiles de San Andrés convive con la del tabaco. El último tercio acaba en un final largo y cálido de especias oscuras y de espresso.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Sobre la tripa nicaragüense y hondureña que CAO emplea en todo su catálogo premium, esa capa crea un perfil sin equivalente en la gama. El primer tercio da cacao puro —ni azucarado ni diluido, el amargor franco del chocolate de cobertura. El segundo introduce regaliz y pimienta de Cayena, en una combinación que recuerda el mole mexicano —y no es casualidad: la tradición de los chiles de San Andrés convive con la del tabaco. El último tercio acaba en un final largo y cálido de especias oscuras y de espresso.', 'Los comerciantes la describen de fuerza media a media-alta, con notas de crema, cedro y pimienta; las opiniones divergen de un comerciante a otro. Los tamaños que lista cigarworld.com llevan nombres propios: Frontier, Gothic, Bengal, Mosaic, Storm.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Auf der nicaraguanischen und honduranischen Einlage, die CAO in ihrem gesamten Premiumkatalog verwendet, schafft dieses Deckblatt ein Profil ohne Entsprechung in der Linie. Das erste Drittel gibt reinen Kakao — weder gezuckert noch verdünnt, die klare Bitterkeit der Kuvertüre. Das zweite bringt Lakritz und Cayennepfeffer, in einer Verbindung, die an das mexikanische Mole erinnert — kein Zufall: Die Chili-Überlieferung von San Andrés lebt neben der des Tabaks. Das letzte Drittel endet in einem langen, warmen Abgang aus dunklen Gewürzen und Espresso.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Auf der nicaraguanischen und honduranischen Einlage, die CAO in ihrem gesamten Premiumkatalog verwendet, schafft dieses Deckblatt ein Profil ohne Entsprechung in der Linie. Das erste Drittel gibt reinen Kakao — weder gezuckert noch verdünnt, die klare Bitterkeit der Kuvertüre. Das zweite bringt Lakritz und Cayennepfeffer, in einer Verbindung, die an das mexikanische Mole erinnert — kein Zufall: Die Chili-Überlieferung von San Andrés lebt neben der des Tabaks. Das letzte Drittel endet in einem langen, warmen Abgang aus dunklen Gewürzen und Espresso.', 'Händler beschreiben sie als mittelkräftig bis kräftig, mit Noten von Sahne, Zedernholz und Pfeffer; die Urteile gehen von Händler zu Händler auseinander. Die von cigarworld.com aufgeführten Formate tragen Eigennamen: Frontier, Gothic, Bengal, Mosaic, Storm.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('铺在 CAO 整个高端目录通用的尼加拉瓜与洪都拉斯茄芯之上，这张茄衣造出了该系列中独一份的风格。第一段是纯可可——不加糖，也不稀释，是调温巧克力那种坦率的苦。第二段引入甘草与卡宴辣椒，这组合让人想起墨西哥的莫雷酱——而这并非偶然：圣安德烈斯的辣椒传统与烟草传统本就比邻而居。最后一段收在深色香料与意式浓缩的长而温热的余味上。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '铺在 CAO 整个高端目录通用的尼加拉瓜与洪都拉斯茄芯之上，这张茄衣造出了该系列中独一份的风格。第一段是纯可可——不加糖，也不稀释，是调温巧克力那种坦率的苦。第二段引入甘草与卡宴辣椒，这组合让人想起墨西哥的莫雷酱——而这并非偶然：圣安德烈斯的辣椒传统与烟草传统本就比邻而居。最后一段收在深色香料与意式浓缩的长而温热的余味上。', '零售商描述其浓度为中等至中偏浓，带奶油、雪松与胡椒的风味；各零售商的看法并不一致。cigarworld.com 列出的规格都有专名：Frontier，Gothic，Bengal，Mosaic，Storm。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وفوق الحشوة النيكاراغوية والهندوراسية التي تستعملها CAO في كتالوغها الفاخر كلّه، يصنع هذا الغلاف طابعًا لا نظير له في التشكيلة. يعطي الثلث الأول كاكاو خالصًا — لا مُحلّى ولا مخفّفًا، مرارة شوكولاتة الكوفرتور الصريحة. ويُدخل الثاني عرق السوس وفلفل كايين، في تركيب يذكّر بالمولي المكسيكي — وليس ذلك مصادفة: فتقليد فلفل سان أندريس يجاور تقليد التبغ. أما الثلث الأخير فينتهي بنهاية طويلة دافئة من التوابل الداكنة والإسبريسو.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وفوق الحشوة النيكاراغوية والهندوراسية التي تستعملها CAO في كتالوغها الفاخر كلّه، يصنع هذا الغلاف طابعًا لا نظير له في التشكيلة. يعطي الثلث الأول كاكاو خالصًا — لا مُحلّى ولا مخفّفًا، مرارة شوكولاتة الكوفرتور الصريحة. ويُدخل الثاني عرق السوس وفلفل كايين، في تركيب يذكّر بالمولي المكسيكي — وليس ذلك مصادفة: فتقليد فلفل سان أندريس يجاور تقليد التبغ. أما الثلث الأخير فينتهي بنهاية طويلة دافئة من التوابل الداكنة والإسبريسو.', 'يصفه التجّار بقوة بين المتوسطة وفوق المتوسطة، بنكهات القشدة والأرز والفلفل؛ وتتباين الآراء من تاجر إلى آخر. والقياسات التي تسردها cigarworld.com لها أسماء علم: Frontier وGothic وBengal وMosaic وStorm.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Black';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('CAO présente la Black comme la proposition la plus exigeante de son catalogue — un cigare pour les fumeurs qui ont dépassé le goût de la douceur et de la crème dominant les gammes Connecticut et Cameroon, et qui cherchent délibérément l''intensité. Elle a trouvé son public chez les amateurs qui trouvent les nicaraguayens corsés trop linéaires et cherchent la dimension aromatique particulière qu''apporte une cape mexicaine sombre.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'CAO présente la Black comme la proposition la plus exigeante de son catalogue — un cigare pour les fumeurs qui ont dépassé le goût de la douceur et de la crème dominant les gammes Connecticut et Cameroon, et qui cherchent délibérément l''intensité. Elle a trouvé son public chez les amateurs qui trouvent les nicaraguayens corsés trop linéaires et cherchent la dimension aromatique particulière qu''apporte une cape mexicaine sombre.', 'La maison CAO et son rattachement à General Cigar puis à STG sont traités sur la fiche CAO ; cette fiche ne détaille pas la fabrique actuelle de la Black, faute de page.'), `history`),
  `history_en` = IF(LOCATE(CAST('CAO Black positions itself as the most challenging proposition in the CAO catalog — a cigar for smokers who have moved past the preference for sweetness and cream that dominates the Connecticut and Cameroon ranges and are deliberately seeking intensity and complexity. It has found a dedicated audience among enthusiasts who find full-body Nicaraguan cigars too linear and are looking for the specific aromatic dimension that only dark Mexican wrapper can provide.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'CAO Black positions itself as the most challenging proposition in the CAO catalog — a cigar for smokers who have moved past the preference for sweetness and cream that dominates the Connecticut and Cameroon ranges and are deliberately seeking intensity and complexity. It has found a dedicated audience among enthusiasts who find full-body Nicaraguan cigars too linear and are looking for the specific aromatic dimension that only dark Mexican wrapper can provide.', 'The CAO house and its attachment to General Cigar and then to STG are covered on the CAO page; this page does not detail the Black''s current factory, for lack of a page.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('CAO presenta la Black como la propuesta más exigente de su catálogo —un puro para los fumadores que han dejado atrás el gusto por la suavidad y la crema que dominan las gamas Connecticut y Cameroon, y que buscan deliberadamente la intensidad. Ha encontrado su público entre los aficionados que hallan demasiado lineales a los nicaragüenses recios y buscan la dimensión aromática particular que aporta una capa mexicana oscura.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'CAO presenta la Black como la propuesta más exigente de su catálogo —un puro para los fumadores que han dejado atrás el gusto por la suavidad y la crema que dominan las gamas Connecticut y Cameroon, y que buscan deliberadamente la intensidad. Ha encontrado su público entre los aficionados que hallan demasiado lineales a los nicaragüenses recios y buscan la dimensión aromática particular que aporta una capa mexicana oscura.', 'La casa CAO y su vínculo con General Cigar y luego con STG se tratan en la ficha CAO; esta ficha no detalla la fábrica actual de la Black, por falta de página.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('CAO stellt die Black als das anspruchsvollste Angebot ihres Katalogs vor — eine Zigarre für Raucher, die den Geschmack an der Milde und der Sahne hinter sich gelassen haben, die die Linien Connecticut und Cameroon bestimmen, und die die Intensität mit Absicht suchen. Sie hat ihr Publikum bei jenen Liebhabern gefunden, denen kräftige Nicaraguaner zu geradlinig sind und die die besondere aromatische Dimension eines dunklen mexikanischen Deckblatts suchen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'CAO stellt die Black als das anspruchsvollste Angebot ihres Katalogs vor — eine Zigarre für Raucher, die den Geschmack an der Milde und der Sahne hinter sich gelassen haben, die die Linien Connecticut und Cameroon bestimmen, und die die Intensität mit Absicht suchen. Sie hat ihr Publikum bei jenen Liebhabern gefunden, denen kräftige Nicaraguaner zu geradlinig sind und die die besondere aromatische Dimension eines dunklen mexikanischen Deckblatts suchen.', 'Das Haus CAO und seine Zugehörigkeit zu General Cigar und dann zu STG werden auf der Seite zu CAO behandelt; diese Seite führt die heutige Fabrik der Black mangels einer Seite nicht aus.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CAO 把 Black 摆在目录中最考验人的位置——给那些已经越过康涅狄格与喀麦隆系列所主导的柔顺与奶油口味、并且刻意去找强度的烟客。它找到的知音，是那些觉得浓味尼加拉瓜作品太过单线，转而追求一张深色墨西哥茄衣所带来的那种特别香气维度的人。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CAO 把 Black 摆在目录中最考验人的位置——给那些已经越过康涅狄格与喀麦隆系列所主导的柔顺与奶油口味、并且刻意去找强度的烟客。它找到的知音，是那些觉得浓味尼加拉瓜作品太过单线，转而追求一张深色墨西哥茄衣所带来的那种特别香气维度的人。', 'CAO 字号及其先后隶属 General Cigar 与 STG 一事，见 CAO 条目；本条目不详述 Black 现今的工厂，因为没有相关页面。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تقدّم CAO تشكيلة «بلاك» بوصفها أكثر عروض كتالوغها تطلّبًا — سيجارًا لمن تجاوزوا ذوق اللطف والقشدة الذي يسود تشكيلتي كونيتيكت والكاميرون، ويقصدون الشدّة قصدًا. وقد وجدت جمهورها بين الهواة الذين يرون السيجار النيكاراغوي القوي أحاديّ الخطّ، ويبحثون عن البعد العطري الخاص الذي يمنحه غلاف مكسيكي داكن.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تقدّم CAO تشكيلة «بلاك» بوصفها أكثر عروض كتالوغها تطلّبًا — سيجارًا لمن تجاوزوا ذوق اللطف والقشدة الذي يسود تشكيلتي كونيتيكت والكاميرون، ويقصدون الشدّة قصدًا. وقد وجدت جمهورها بين الهواة الذين يرون السيجار النيكاراغوي القوي أحاديّ الخطّ، ويبحثون عن البعد العطري الخاص الذي يمنحه غلاف مكسيكي داكن.', 'تُعالَج دار CAO وانتماؤها إلى General Cigar ثم إلى STG في صفحة CAO؛ ولا تفصّل هذه الصفحة المصنع الحالي لـ Black لغياب صفحة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Black';

UPDATE `brands` SET
  `country_id` = 'honduras',
  `factory` = 'Honduras à l''origine selon cigarplace.biz (octobre 2026) ; fabrique actuelle non établie par une page',
  `gamme` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"Cape Connecticut d''Équateur, liant nicaraguayen, tripe longfiller de Nicaragua, du Honduras et du Mexique (cigarworld.com, cigarplace.biz, octobre 2026). Tailles nommées Frontier, Gothic, Bengal, Mosaic, Storm. À ne pas confondre avec Black VR.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut d''Équateur"}]',
  `gamme_en` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"Ecuadorian Connecticut wrapper, Nicaraguan binder, longfiller of Nicaragua, Honduras and Mexico (cigarworld.com, cigarplace.biz, October 2026). Sizes named Frontier, Gothic, Bengal, Mosaic, Storm. Not to be confused with Black VR.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Ecuadorian Connecticut"}]',
  `gamme_es` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"Capa Connecticut de Ecuador, capote nicaragüense, tripa de hoja larga de Nicaragua, Honduras y México (cigarworld.com, cigarplace.biz, octubre de 2026). Tamaños llamados Frontier, Gothic, Bengal, Mosaic, Storm. No debe confundirse con Black VR.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut de Ecuador"}]',
  `gamme_de` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"Connecticut-Deckblatt aus Ecuador, nicaraguanisches Umblatt, Longfiller-Einlage aus Nicaragua, Honduras und Mexiko (cigarworld.com, cigarplace.biz, Oktober 2026). Formate mit den Namen Frontier, Gothic, Bengal, Mosaic, Storm. Nicht zu verwechseln mit Black VR.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut aus Ecuador"}]',
  `gamme_zh` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"厄瓜多尔康涅狄格茄衣，尼加拉瓜茄套，茄芯为长叶烟丝，产自尼加拉瓜、洪都拉斯与墨西哥（cigarworld.com，cigarplace.biz，2026年10月）。规格名为 Frontier，Gothic，Bengal，Mosaic，Storm。切勿与 Black VR 混淆。","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"厄瓜多尔康涅狄格"}]',
  `gamme_ar` = '[{"name":"CAO Black","color":"#1C0A00","force":null,"story":"غلاف كونيتيكت من الإكوادور، وغلاف داخلي نيكاراغوي، وحشوة طويلة الأوراق من نيكاراغوا وهندوراس والمكسيك (cigarworld.com، cigarplace.biz، أكتوبر 2026). قياسات تحمل الأسماء Frontier وGothic وBengal وMosaic وStorm. لا يُخلط بينه وبين Black VR.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"كونيتيكت من الإكوادور"}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('caocigars.com et cigaraficionado.com — FICHE DE CAPE : cape de San Andrés sur un cigare roulé chez General Cigar, à Danlí' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'caocigars.com et cigaraficionado.com — FICHE DE CAPE : cape de San Andrés sur un cigare roulé chez General Cigar, à Danlí', 'cigarworld.com « CAO Black Cigar » (octobre 2026 : cape Connecticut d''Équateur, liant nicaraguayen, tripe Honduras/Mexique/Nicaragua) ; cigarplace.biz « CAO Black Cigars » (octobre 2026 : « Made in Honduras originally ») ; stogiereview.com « CAO Black VR Totem » (5 mars 2008 : ligne VR distincte, cape du Brésil)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO Black';

-- ── CAO America ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('CAO America est une déclaration d''indépendance — non pas politique, mais agricole. Lancée en 2004, elle arrive à un moment où le cigare premium ne parlait plus que de puissance nicaraguayenne et de terre hondurienne. La conversation portait sur l''Amérique centrale. CAO répondit en regardant vers le nord, vers les champs qui avaient approvisionné les fumeurs américains pendant trois siècles, avant que la révolution cubaine et l''essor nicaraguayen ne redessinent le marché.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'CAO America est une déclaration d''indépendance — non pas politique, mais agricole. Lancée en 2004, elle arrive à un moment où le cigare premium ne parlait plus que de puissance nicaraguayenne et de terre hondurienne. La conversation portait sur l''Amérique centrale. CAO répondit en regardant vers le nord, vers les champs qui avaient approvisionné les fumeurs américains pendant trois siècles, avant que la révolution cubaine et l''essor nicaraguayen ne redessinent le marché.', 'CAO America est une ligne de la maison CAO, présentée en 2007 au salon des détaillants (RTDA) de Houston. Selon la presse du métier (septembre 2007), elle était roulée à la fabrique C.A.O. du Honduras, avec deux capes cultivées aux États-Unis : un Connecticut Shade brun doré et un broadleaf brun chocolat.'), `history`),
  `history_en` = IF(LOCATE(CAST('CAO America is a declaration of independence — not political, but agricultural. Launched in 2004, it arrived at a moment when the premium cigar world had become entirely preoccupied with Nicaraguan power and Honduran earthiness. The conversation was always about Central American terroir. CAO''s response was to look north, to the tobacco fields that had supplied American smokers for three centuries before the Cuban revolution and the Nicaraguan boom reshaped the market.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'CAO America is a declaration of independence — not political, but agricultural. Launched in 2004, it arrived at a moment when the premium cigar world had become entirely preoccupied with Nicaraguan power and Honduran earthiness. The conversation was always about Central American terroir. CAO''s response was to look north, to the tobacco fields that had supplied American smokers for three centuries before the Cuban revolution and the Nicaraguan boom reshaped the market.', 'CAO America is a line from the house of CAO, presented in 2007 at the retailers’ trade show (RTDA) in Houston. According to the trade press (September 2007), it was rolled at the C.A.O. factory in Honduras, with two wrappers grown in the United States: a golden-brown Connecticut Shade and a chocolate-brown broadleaf.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('CAO America es una declaración de independencia —no política, sino agrícola. Lanzada en 2004, llega en un momento en que el puro premium solo hablaba de potencia nicaragüense y de tierra hondureña. La conversación giraba en torno a Centroamérica. CAO respondió mirando al norte, hacia los campos que habían abastecido a los fumadores estadounidenses durante tres siglos, antes de que la revolución cubana y el auge nicaragüense redibujaran el mercado.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'CAO America es una declaración de independencia —no política, sino agrícola. Lanzada en 2004, llega en un momento en que el puro premium solo hablaba de potencia nicaragüense y de tierra hondureña. La conversación giraba en torno a Centroamérica. CAO respondió mirando al norte, hacia los campos que habían abastecido a los fumadores estadounidenses durante tres siglos, antes de que la revolución cubana y el auge nicaragüense redibujaran el mercado.', 'CAO America es una línea de la casa CAO, presentada en 2007 en el salón de los detallistas (RTDA) de Houston. Según la prensa del sector (septiembre de 2007), se torcía en la fábrica C.A.O. de Honduras, con dos capas cultivadas en Estados Unidos: un Connecticut Shade marrón dorado y un broadleaf marrón chocolate.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('CAO America ist eine Unabhängigkeitserklärung — keine politische, eine landwirtschaftliche. 2004 herausgebracht, kommt sie in einem Augenblick, in dem die Premiumzigarre nur noch von nicaraguanischer Kraft und honduranischer Erde sprach. Das Gespräch drehte sich um Mittelamerika. CAO antwortete mit einem Blick nach Norden, auf die Felder, die amerikanische Raucher drei Jahrhunderte lang beliefert hatten, bevor die kubanische Revolution und der Aufstieg Nicaraguas den Markt neu zeichneten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'CAO America ist eine Unabhängigkeitserklärung — keine politische, eine landwirtschaftliche. 2004 herausgebracht, kommt sie in einem Augenblick, in dem die Premiumzigarre nur noch von nicaraguanischer Kraft und honduranischer Erde sprach. Das Gespräch drehte sich um Mittelamerika. CAO antwortete mit einem Blick nach Norden, auf die Felder, die amerikanische Raucher drei Jahrhunderte lang beliefert hatten, bevor die kubanische Revolution und der Aufstieg Nicaraguas den Markt neu zeichneten.', 'CAO America ist eine Linie des Hauses CAO, 2007 auf der Händlermesse (RTDA) in Houston vorgestellt. Laut der Fachpresse (September 2007) wurde sie in der Fabrik C.A.O. in Honduras gerollt, mit zwei in den Vereinigten Staaten angebauten Deckblättern: einem goldbraunen Connecticut Shade und einem schokoladenbraunen Broadleaf.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CAO America 是一份独立宣言——不是政治上的，而是农业上的。它于2004年推出，正赶上高端雪茄言必称尼加拉瓜的力量与洪都拉斯的土地的时候。话题都围着中美洲转。CAO 的回应是往北看，看向那些在古巴革命与尼加拉瓜崛起重画市场之前，为美国烟客供货三百年的田地。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CAO America 是一份独立宣言——不是政治上的，而是农业上的。它于2004年推出，正赶上高端雪茄言必称尼加拉瓜的力量与洪都拉斯的土地的时候。话题都围着中美洲转。CAO 的回应是往北看，看向那些在古巴革命与尼加拉瓜崛起重画市场之前，为美国烟客供货三百年的田地。', 'CAO America 是 CAO 公司旗下的一个系列，2007年在休斯敦举行的零售商展会（RTDA）上推出。据行业媒体（2007年9月）报道，它在洪都拉斯的 C.A.O. 工厂卷制，使用两种美国种植的茄衣：金褐色的 Connecticut Shade 和巧克力褐色的 broadleaf。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«كاو أمريكا» إعلان استقلال — لا سياسي بل زراعي. صدرت عام 2004، في لحظة لم يكن السيجار الفاخر يتحدّث فيها إلا عن القوة النيكاراغوية والأرض الهندوراسية. كان الحديث كله عن أمريكا الوسطى. فردّت CAO بأن نظرت شمالًا، إلى الحقول التي زوّدت المدخّنين الأمريكيين ثلاثة قرون، قبل أن تعيد الثورة الكوبية وصعود نيكاراغوا رسم السوق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«كاو أمريكا» إعلان استقلال — لا سياسي بل زراعي. صدرت عام 2004، في لحظة لم يكن السيجار الفاخر يتحدّث فيها إلا عن القوة النيكاراغوية والأرض الهندوراسية. كان الحديث كله عن أمريكا الوسطى. فردّت CAO بأن نظرت شمالًا، إلى الحقول التي زوّدت المدخّنين الأمريكيين ثلاثة قرون، قبل أن تعيد الثورة الكوبية وصعود نيكاراغوا رسم السوق.', 'CAO America خط من دار CAO، قُدِّم عام 2007 في معرض تجّار التجزئة (RTDA) في هيوستن. وبحسب الصحافة المتخصصة في القطاع (سبتمبر 2007)، كان يُلَفّ في مصنع C.A.O. في هندوراس، بغلافين مزروعين في الولايات المتحدة: Connecticut Shade بني ذهبي وbroadleaf بني شوكولاتي.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO America';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le principe est simple, et presque provocant de précision : du tabac américain à 100 %, dans chaque composant. Les capes viennent de la vallée du Connecticut, dont le sol sablo-limoneux donne la feuille d''ombre qui a fait la réputation du style. Les sous-capes viennent du comté de Lancaster, en Pennsylvanie, où l''on cultive le broadleaf depuis le XVIIe siècle. Les tripes mêlent des feuilles de Virginie — où la culture du tabac est antérieure aux États-Unis eux-mêmes — et à nouveau du Connecticut.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le principe est simple, et presque provocant de précision : du tabac américain à 100 %, dans chaque composant. Les capes viennent de la vallée du Connecticut, dont le sol sablo-limoneux donne la feuille d''ombre qui a fait la réputation du style. Les sous-capes viennent du comté de Lancaster, en Pennsylvanie, où l''on cultive le broadleaf depuis le XVIIe siècle. Les tripes mêlent des feuilles de Virginie — où la culture du tabac est antérieure aux États-Unis eux-mêmes — et à nouveau du Connecticut.', 'Le mélange n''est pas entièrement américain : le liant est brésilien et la tripe associe du tabac américain à des feuilles du Nicaragua, d''Italie et de République dominicaine (même source, 2007). Une fiche de notation de 2021-2022 donne la même construction, avec le Nicaragua comme pays d''origine ; la fiche garde les deux versions. L''effet pinstripe vient de la cape Shade laissée apparente sous les feuilles broadleaf (détaillant cigarsdirect.com, octobre 2026).'), `history`),
  `history_en` = IF(LOCATE(CAST('The concept is straightforward and almost defiantly specific: 100% American tobacco in every component. The wrappers come from Connecticut''s river valley, where the famously sandy loam soil produces the shade-grown leaf that made the style''s reputation. The binders draw from Pennsylvania''s Lancaster County, where broadleaf tobacco has been grown since the 17th century. The fillers blend leaf from Virginia, where tobacco cultivation predates the United States itself, and from Connecticut once more.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The concept is straightforward and almost defiantly specific: 100% American tobacco in every component. The wrappers come from Connecticut''s river valley, where the famously sandy loam soil produces the shade-grown leaf that made the style''s reputation. The binders draw from Pennsylvania''s Lancaster County, where broadleaf tobacco has been grown since the 17th century. The fillers blend leaf from Virginia, where tobacco cultivation predates the United States itself, and from Connecticut once more.', 'The blend is not entirely American: the binder is Brazilian and the filler combines American tobacco with leaves from Nicaragua, Italy and the Dominican Republic (same source, 2007). A tasting sheet from 2021-2022 gives the same construction, with Nicaragua as the country of origin; the entry keeps both versions. The pinstripe effect comes from the Shade wrapper left visible beneath the broadleaf leaves (retailer cigarsdirect.com, October 2026).'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El principio es simple, y casi provocador de tan preciso: tabaco estadounidense al 100 %, en cada componente. Las capas vienen del valle del Connecticut, cuyo suelo areno-limoso da la hoja de sombra que hizo la reputación del estilo. Los capotes vienen del condado de Lancaster, en Pensilvania, donde se cultiva broadleaf desde el siglo XVII. Las tripas mezclan hojas de Virginia —donde el cultivo del tabaco es anterior a los propios Estados Unidos— y de nuevo del Connecticut.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El principio es simple, y casi provocador de tan preciso: tabaco estadounidense al 100 %, en cada componente. Las capas vienen del valle del Connecticut, cuyo suelo areno-limoso da la hoja de sombra que hizo la reputación del estilo. Los capotes vienen del condado de Lancaster, en Pensilvania, donde se cultiva broadleaf desde el siglo XVII. Las tripas mezclan hojas de Virginia —donde el cultivo del tabaco es anterior a los propios Estados Unidos— y de nuevo del Connecticut.', 'La mezcla no es enteramente estadounidense: el capote es brasileño y la tripa combina tabaco estadounidense con hojas de Nicaragua, Italia y República Dominicana (misma fuente, 2007). Una ficha de cata de 2021-2022 da la misma construcción, con Nicaragua como país de origen; esta ficha conserva las dos versiones. El efecto pinstripe viene de la capa Shade dejada a la vista bajo las hojas broadleaf (detallista cigarsdirect.com, octubre de 2026).'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Prinzip ist einfach und in seiner Genauigkeit fast herausfordernd: amerikanischer Tabak zu 100 %, in jedem Bestandteil. Die Deckblätter kommen aus dem Connecticut-Tal, dessen sandig-lehmiger Boden das Schattenblatt hervorbringt, das den Ruf des Stils begründet hat. Die Umblätter stammen aus Lancaster County in Pennsylvania, wo seit dem 17. Jahrhundert Broadleaf angebaut wird. Die Einlagen mischen Blätter aus Virginia — wo der Tabakanbau älter ist als die Vereinigten Staaten selbst — und wiederum aus Connecticut.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Prinzip ist einfach und in seiner Genauigkeit fast herausfordernd: amerikanischer Tabak zu 100 %, in jedem Bestandteil. Die Deckblätter kommen aus dem Connecticut-Tal, dessen sandig-lehmiger Boden das Schattenblatt hervorbringt, das den Ruf des Stils begründet hat. Die Umblätter stammen aus Lancaster County in Pennsylvania, wo seit dem 17. Jahrhundert Broadleaf angebaut wird. Die Einlagen mischen Blätter aus Virginia — wo der Tabakanbau älter ist als die Vereinigten Staaten selbst — und wiederum aus Connecticut.', 'Die Mischung ist nicht ganz amerikanisch: Das Umblatt ist brasilianisch, und die Einlage verbindet amerikanischen Tabak mit Blättern aus Nicaragua, Italien und der Dominikanischen Republik (gleiche Quelle, 2007). Ein Verkostungsbogen von 2021-2022 nennt denselben Aufbau, mit Nicaragua als Herkunftsland; der Eintrag führt beide Versionen. Der Pinstripe-Effekt entsteht, weil das Shade-Deckblatt unter den Broadleaf-Blättern sichtbar bleibt (Händler cigarsdirect.com, Oktober 2026).'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('原则简单，精确到近乎挑衅：每一个部分都用百分之百的美国烟草。茄衣来自康涅狄格河谷，那里的砂壤土长出成就了这一风格声誉的阴植叶。茄套来自宾夕法尼亚的兰开斯特县，17世纪起就在那里种植宽叶烟。茄芯则把弗吉尼亚的叶子——那里的烟草种植比美国本身还要早——与康涅狄格的叶子混在一起。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '原则简单，精确到近乎挑衅：每一个部分都用百分之百的美国烟草。茄衣来自康涅狄格河谷，那里的砂壤土长出成就了这一风格声誉的阴植叶。茄套来自宾夕法尼亚的兰开斯特县，17世纪起就在那里种植宽叶烟。茄芯则把弗吉尼亚的叶子——那里的烟草种植比美国本身还要早——与康涅狄格的叶子混在一起。', '这款混合并非全部来自美国：茄套为巴西产，茄芯把美国烟草与来自尼加拉瓜、意大利和多米尼加共和国的叶片结合起来（同一来源，2007年）。一份2021-2022年的品鉴表给出相同的构成，原产国写作尼加拉瓜；本条目保留两个版本。pinstripe 效果来自露在 broadleaf 叶片之下的 Shade 茄衣（零售商 cigarsdirect.com，2026年10月）。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('المبدأ بسيط، ودقيق إلى حدّ يكاد يكون استفزازًا: تبغ أمريكي مئة في المئة، في كل مكوّن. تأتي الأغلفة من وادي كونيتيكت، حيث تعطي التربة الرملية الطميية ورقة الظل التي صنعت سمعة هذا الأسلوب. وتأتي الأغلفة الداخلية من مقاطعة لانكستر في بنسلفانيا، حيث يُزرع التبغ العريض منذ القرن السابع عشر. أما الحشوات فتمزج أوراقًا من فرجينيا — حيث زراعة التبغ أقدم من الولايات المتحدة نفسها — وأوراقًا أخرى من كونيتيكت.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'المبدأ بسيط، ودقيق إلى حدّ يكاد يكون استفزازًا: تبغ أمريكي مئة في المئة، في كل مكوّن. تأتي الأغلفة من وادي كونيتيكت، حيث تعطي التربة الرملية الطميية ورقة الظل التي صنعت سمعة هذا الأسلوب. وتأتي الأغلفة الداخلية من مقاطعة لانكستر في بنسلفانيا، حيث يُزرع التبغ العريض منذ القرن السابع عشر. أما الحشوات فتمزج أوراقًا من فرجينيا — حيث زراعة التبغ أقدم من الولايات المتحدة نفسها — وأوراقًا أخرى من كونيتيكت.', 'التركيبة ليست أمريكية بالكامل: الغلاف الداخلي برازيلي، والحشوة تجمع تبغًا أمريكيًا مع أوراق من نيكاراغوا وإيطاليا والجمهورية الدومينيكية (المصدر نفسه، 2007). وتعطي بطاقة تذوّق من 2021-2022 البنية نفسها، مع نيكاراغوا بلدًا للمنشأ؛ وتحتفظ هذه الصفحة بالنسختين. ويأتي أثر pinstripe من غلاف Shade المتروك ظاهرًا تحت أوراق broadleaf (التاجر cigarsdirect.com، أكتوبر 2026).'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO America';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Techniquement, cela produit un cigare entièrement hors du profil centraméricain qui domine le secteur. Les America sont plus ronds, plus doux, plus herbacés que les nicaraguayens. Ils ont l''onctuosité que donne naturellement un bon Connecticut Shade, avec des notes de foin sec, de cèdre chaud et la légère note de noisette d''une feuille de Pennsylvanie bien séchée. La force moyenne laisse le tabac s''exprimer sans le poivre et la terre qui marquent le style nicaraguayen.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Techniquement, cela produit un cigare entièrement hors du profil centraméricain qui domine le secteur. Les America sont plus ronds, plus doux, plus herbacés que les nicaraguayens. Ils ont l''onctuosité que donne naturellement un bon Connecticut Shade, avec des notes de foin sec, de cèdre chaud et la légère note de noisette d''une feuille de Pennsylvanie bien séchée. La force moyenne laisse le tabac s''exprimer sans le poivre et la terre qui marquent le style nicaraguayen.', 'Les détaillants la disent de force moyenne à corsée (cigarsdirect.com, octobre 2026). Les vitolas d''origine sont le Potomac (5 × 56), le Landmark (6 × 60) et le Monument, un torpedo de 6 ¼ pouces.'), `history`),
  `history_en` = IF(LOCATE(CAST('What this creates, technically, is a cigar entirely outside the Central American flavor profile that dominates the premium sector. CAO America profiles are rounder, gentler, and more herbaceous than Nicaraguan cigars. They share the creamy texture that good Connecticut shade naturally produces, with underlying notes of dried grass, warm cedar, and the mild nuttiness of well-cured Pennsylvania leaf. The medium-body strength allows the tobacco''s character to express itself without the aggressive pepper and earth notes that mark the Nicaraguan style.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'What this creates, technically, is a cigar entirely outside the Central American flavor profile that dominates the premium sector. CAO America profiles are rounder, gentler, and more herbaceous than Nicaraguan cigars. They share the creamy texture that good Connecticut shade naturally produces, with underlying notes of dried grass, warm cedar, and the mild nuttiness of well-cured Pennsylvania leaf. The medium-body strength allows the tobacco''s character to express itself without the aggressive pepper and earth notes that mark the Nicaraguan style.', 'Retailers describe it as medium to full in strength (cigarsdirect.com, October 2026). The original vitolas are the Potomac (5 × 56), the Landmark (6 × 60) and the Monument, a torpedo of 6 ¼ inches.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Técnicamente, eso produce un puro enteramente fuera del perfil centroamericano que domina el sector. Los America son más redondos, más suaves, más herbáceos que los nicaragüenses. Tienen la untuosidad que da naturalmente un buen Connecticut Shade, con notas de heno seco, de cedro cálido y la ligera nota de avellana de una hoja de Pensilvania bien secada. La fuerza media deja al tabaco expresarse sin la pimienta y la tierra que marcan el estilo nicaragüense.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Técnicamente, eso produce un puro enteramente fuera del perfil centroamericano que domina el sector. Los America son más redondos, más suaves, más herbáceos que los nicaragüenses. Tienen la untuosidad que da naturalmente un buen Connecticut Shade, con notas de heno seco, de cedro cálido y la ligera nota de avellana de una hoja de Pensilvania bien secada. La fuerza media deja al tabaco expresarse sin la pimienta y la tierra que marcan el estilo nicaragüense.', 'Los detallistas la describen de fuerza media a fuerte (cigarsdirect.com, octubre de 2026). Las vitolas originales son el Potomac (5 × 56), el Landmark (6 × 60) y el Monument, un torpedo de 6 ¼ pulgadas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Technisch ergibt das eine Zigarre, die ganz außerhalb des mittelamerikanischen Profils steht, das die Branche beherrscht. Die America sind runder, milder, krautiger als die Nicaraguaner. Sie haben die Cremigkeit, die ein gutes Connecticut Shade von selbst gibt, mit Noten von trockenem Heu, warmer Zeder und der leichten Haselnussnote eines gut getrockneten Pennsylvania-Blattes. Die mittlere Stärke lässt den Tabak sprechen, ohne die Pfefferschärfe und die Erde, die den nicaraguanischen Stil prägen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Technisch ergibt das eine Zigarre, die ganz außerhalb des mittelamerikanischen Profils steht, das die Branche beherrscht. Die America sind runder, milder, krautiger als die Nicaraguaner. Sie haben die Cremigkeit, die ein gutes Connecticut Shade von selbst gibt, mit Noten von trockenem Heu, warmer Zeder und der leichten Haselnussnote eines gut getrockneten Pennsylvania-Blattes. Die mittlere Stärke lässt den Tabak sprechen, ohne die Pfefferschärfe und die Erde, die den nicaraguanischen Stil prägen.', 'Händler beschreiben sie als mittelkräftig bis kräftig (cigarsdirect.com, Oktober 2026). Die ursprünglichen Vitolas sind der Potomac (5 × 56), der Landmark (6 × 60) und der Monument, ein Torpedo von 6 ¼ Zoll.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('在工艺上，这做出了一支完全跳出行业主流中美洲调性的雪茄。America 比尼加拉瓜作品更圆润、更柔和、更带草本气。它有好的康涅狄格阴植叶天然给出的顺滑，佐以干草、温热雪松，以及一片干燥得当的宾夕法尼亚叶子所带的淡淡榛子气。中等力度让烟草自己说话，没有尼加拉瓜风格里那股胡椒与泥土。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '在工艺上，这做出了一支完全跳出行业主流中美洲调性的雪茄。America 比尼加拉瓜作品更圆润、更柔和、更带草本气。它有好的康涅狄格阴植叶天然给出的顺滑，佐以干草、温热雪松，以及一片干燥得当的宾夕法尼亚叶子所带的淡淡榛子气。中等力度让烟草自己说话，没有尼加拉瓜风格里那股胡椒与泥土。', '零售商称其力度为中等至浓郁（cigarsdirect.com，2026年10月）。原始规格有 Potomac（5 × 56）、Landmark（6 × 60）和 Monument，后者是一款 6 ¼ 英寸的 torpedo。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تقنيًّا، ينتج ذلك سيجارًا خارجًا تمامًا عن الطابع الأمريكي الوسطي الذي يسيطر على القطاع. «أمريكا» أكثر استدارة ولطفًا وعشبيةً من السيجار النيكاراغوي. فيه النعومة الدسمة التي يمنحها كونيتيكت شيد الجيد من تلقاء نفسه، مع نفحات من القشّ الجاف وخشب الأرز الدافئ ولمسة بندق خفيفة من ورقة بنسلفانية جُفِّفت كما ينبغي. والقوة المتوسطة تدع التبغ يعبّر عن نفسه بلا الفلفل والتراب اللذين يطبعان الأسلوب النيكاراغوي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تقنيًّا، ينتج ذلك سيجارًا خارجًا تمامًا عن الطابع الأمريكي الوسطي الذي يسيطر على القطاع. «أمريكا» أكثر استدارة ولطفًا وعشبيةً من السيجار النيكاراغوي. فيه النعومة الدسمة التي يمنحها كونيتيكت شيد الجيد من تلقاء نفسه، مع نفحات من القشّ الجاف وخشب الأرز الدافئ ولمسة بندق خفيفة من ورقة بنسلفانية جُفِّفت كما ينبغي. والقوة المتوسطة تدع التبغ يعبّر عن نفسه بلا الفلفل والتراب اللذين يطبعان الأسلوب النيكاراغوي.', 'يصفها تجّار التجزئة بأنها متوسطة القوة إلى قوية (cigarsdirect.com، أكتوبر 2026). والطرازات الأصلية هي Potomac (5 × 56) وLandmark (6 × 60) وMonument، وهو torpedo بطول 6 ¼ بوصة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO America';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme se heurta d''abord au scepticisme de détaillants habitués à vendre de l''intensité. Le tabac américain était associé, un peu injustement, au marché de masse mécanisé plutôt qu''au premium artisanal. CAO America prit ce préjugé de front, en se présentant comme le produit d''un choix de terroir délibéré et non d''un calcul commercial. Le succès qui suivit — surtout sur les marchés où l''élégance prime sur la puissance — a validé le pari.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme se heurta d''abord au scepticisme de détaillants habitués à vendre de l''intensité. Le tabac américain était associé, un peu injustement, au marché de masse mécanisé plutôt qu''au premium artisanal. CAO America prit ce préjugé de front, en se présentant comme le produit d''un choix de terroir délibéré et non d''un calcul commercial. Le succès qui suivit — surtout sur les marchés où l''élégance prime sur la puissance — a validé le pari.', 'CAO appartient depuis 2007 au groupe Scandinavian Tobacco (Henri Wintermans), puis a été intégrée à General Cigar, installée à Richmond (Virginie), vers 2010-2011.'), `history`),
  `history_en` = IF(LOCATE(CAST('The range initially faced skepticism from retailers accustomed to selling intensity. American tobacco had been associated, somewhat unfairly, with the machine-made mass market rather than the artisanal premium sector. CAO America challenged that prejudice directly, positioning itself as the product of a deliberate terroir choice rather than a concession to commercial calculation. The subsequent success of the range — particularly in markets where smokers preferred elegance to power — validated the bet.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The range initially faced skepticism from retailers accustomed to selling intensity. American tobacco had been associated, somewhat unfairly, with the machine-made mass market rather than the artisanal premium sector. CAO America challenged that prejudice directly, positioning itself as the product of a deliberate terroir choice rather than a concession to commercial calculation. The subsequent success of the range — particularly in markets where smokers preferred elegance to power — validated the bet.', 'CAO has belonged since 2007 to the Scandinavian Tobacco group (Henri Wintermans), then was integrated into General Cigar, based in Richmond (Virginia), around 2010-2011.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La gama chocó primero con el escepticismo de detallistas acostumbrados a vender intensidad. El tabaco estadounidense se asociaba, algo injustamente, al mercado de masas mecanizado más que al premium artesanal. CAO America tomó ese prejuicio de frente, presentándose como el producto de una elección de terruño deliberada y no de un cálculo comercial. El éxito que siguió —sobre todo en los mercados donde la elegancia prima sobre la potencia— validó la apuesta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La gama chocó primero con el escepticismo de detallistas acostumbrados a vender intensidad. El tabaco estadounidense se asociaba, algo injustamente, al mercado de masas mecanizado más que al premium artesanal. CAO America tomó ese prejuicio de frente, presentándose como el producto de una elección de terruño deliberada y no de un cálculo comercial. El éxito que siguió —sobre todo en los mercados donde la elegancia prima sobre la potencia— validó la apuesta.', 'CAO pertenece desde 2007 al grupo Scandinavian Tobacco (Henri Wintermans) y después fue integrada en General Cigar, con sede en Richmond (Virginia), hacia 2010-2011.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Linie stieß zuerst auf die Skepsis von Händlern, die daran gewöhnt waren, Intensität zu verkaufen. Amerikanischer Tabak galt, etwas ungerecht, eher als Sache des maschinellen Massenmarkts denn des handwerklichen Premiums. CAO America ging diesem Vorurteil frontal entgegen und trat als Ergebnis einer bewussten Terroir-Entscheidung auf, nicht eines kaufmännischen Kalküls. Der Erfolg, der folgte — vor allem in Märkten, in denen Eleganz vor Kraft geht —, hat die Wette bestätigt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Linie stieß zuerst auf die Skepsis von Händlern, die daran gewöhnt waren, Intensität zu verkaufen. Amerikanischer Tabak galt, etwas ungerecht, eher als Sache des maschinellen Massenmarkts denn des handwerklichen Premiums. CAO America ging diesem Vorurteil frontal entgegen und trat als Ergebnis einer bewussten Terroir-Entscheidung auf, nicht eines kaufmännischen Kalküls. Der Erfolg, der folgte — vor allem in Märkten, in denen Eleganz vor Kraft geht —, hat die Wette bestätigt.', 'CAO gehört seit 2007 zur Gruppe Scandinavian Tobacco (Henri Wintermans) und wurde dann um 2010-2011 in General Cigar mit Sitz in Richmond (Virginia) eingegliedert.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('这条线最初撞上了零售商的怀疑——他们习惯卖的是浓烈。美国烟草被有些不公平地与机制的大众市场联系在一起，而不是手工高端。CAO America 正面接下了这个成见，把自己呈现为一次刻意的风土选择，而非一次商业算计。随后的成功——尤其在优雅比力量更受看重的市场上——印证了这个赌注。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '这条线最初撞上了零售商的怀疑——他们习惯卖的是浓烈。美国烟草被有些不公平地与机制的大众市场联系在一起，而不是手工高端。CAO America 正面接下了这个成见，把自己呈现为一次刻意的风土选择，而非一次商业算计。随后的成功——尤其在优雅比力量更受看重的市场上——印证了这个赌注。', 'CAO 自2007年起隶属于 Scandinavian Tobacco 集团（Henri Wintermans），后于2010-2011年前后并入总部位于里士满（弗吉尼亚州）的 General Cigar。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('اصطدمت التشكيلة أولًا بتشكّك تجّار التجزئة المعتادين على بيع الشدّة. فقد كان التبغ الأمريكي يُربط، بشيء من الإجحاف، بسوق الإنتاج الآلي الواسع لا بالفخامة الحرفية. واجهت «كاو أمريكا» هذا الحكم المسبق وجهًا لوجه، وقدّمت نفسها ثمرةَ اختيار متعمَّد للأرض لا حسبةً تجارية. والنجاح الذي تلا — خصوصًا في الأسواق التي تُقدَّم فيها الأناقة على القوة — أثبت صواب الرهان.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'اصطدمت التشكيلة أولًا بتشكّك تجّار التجزئة المعتادين على بيع الشدّة. فقد كان التبغ الأمريكي يُربط، بشيء من الإجحاف، بسوق الإنتاج الآلي الواسع لا بالفخامة الحرفية. واجهت «كاو أمريكا» هذا الحكم المسبق وجهًا لوجه، وقدّمت نفسها ثمرةَ اختيار متعمَّد للأرض لا حسبةً تجارية. والنجاح الذي تلا — خصوصًا في الأسواق التي تُقدَّم فيها الأناقة على القوة — أثبت صواب الرهان.', 'تعود ملكية CAO منذ عام 2007 إلى مجموعة Scandinavian Tobacco (Henri Wintermans)، ثم أُدمجت في General Cigar التي مقرها ريتشموند (فرجينيا) نحو 2010-2011.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO America';

UPDATE `brands` SET
  `country_id` = 'nicaragua',
  `founded` = '2007 (lancement de la ligne)',
  `factory` = 'Honduras (C.A.O. Fabrica de Tabacos, selon la presse du métier en 2007) ; Nicaragua selon une fiche de notation de 2021-2022 : divergence',
  `gamme` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"Ligne unique à deux capes cultivées aux États-Unis, Connecticut Shade et broadleaf (effet pinstripe), liant brésilien. Vitolas : Potomac, Landmark, Monument (torpedo) ; le détaillant cigarsdirect.com ajoute Constitution et 250th Anniversary (octobre 2026).","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `gamme_en` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"A single line with two wrappers grown in the United States, Connecticut Shade and broadleaf (pinstripe effect), with a Brazilian binder. Vitolas: Potomac, Landmark, Monument (torpedo); the retailer cigarsdirect.com adds Constitution and 250th Anniversary (October 2026).","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `gamme_es` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"Línea única con dos capas cultivadas en Estados Unidos, Connecticut Shade y broadleaf (efecto pinstripe), capote brasileño. Vitolas: Potomac, Landmark, Monument (torpedo); el detallista cigarsdirect.com añade Constitution y 250th Anniversary (octubre de 2026).","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `gamme_de` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"Einzige Linie mit zwei in den Vereinigten Staaten angebauten Deckblättern, Connecticut Shade und Broadleaf (Pinstripe-Effekt), brasilianisches Umblatt. Vitolas: Potomac, Landmark, Monument (Torpedo); der Händler cigarsdirect.com ergänzt Constitution und 250th Anniversary (Oktober 2026).","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `gamme_zh` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"只有一个系列，使用两种美国种植的茄衣：Connecticut Shade 与 broadleaf（pinstripe 效果），茄套为巴西产。规格：Potomac、Landmark、Monument（torpedo）；零售商 cigarsdirect.com 另列 Constitution 与 250th Anniversary（2026年10月）。","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `gamme_ar` = '[{"name":"CAO America","color":"#B22222","force":"Medium","story":"خط وحيد بغلافين مزروعين في الولايات المتحدة، Connecticut Shade وbroadleaf (أثر pinstripe)، وغلاف داخلي برازيلي. الطرازات: Potomac وLandmark وMonument (torpedo)؛ ويضيف التاجر cigarsdirect.com طرازي Constitution و250th Anniversary (أكتوبر 2026).","vitolas":["Potomac","Gettysburg","Monument"],"wrapper":"Connecticut Shade + Broadleaf"}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('caocigars.com et cigaraficionado.com (2004 ; un assemblage bâti sur des tabacs américains, Connecticut et Virginie)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'caocigars.com et cigaraficionado.com (2004 ; un assemblage bâti sur des tabacs américains, Connecticut et Virginie)', 'cigaraficionado.com « C.A.O. America » (10 septembre 2007 : fabrique C.A.O. au Honduras, deux capes américaines, liant brésilien, tripe américaine/Nicaragua/Italie/Rép. dominicaine) ; cigaraficionado.com « CAO America Monument » (fiche de notation, 2021-2022 : origine Nicaragua) ; cigarsdirect.com « CAO America » (octobre 2026 : pinstripe, vitolas) ; cigaraficionado.com « The new look of CAO » (30 mai 2011 : fabriques de Danlí et d''Estelí)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'CAO America';

-- ── Oliva Serie G ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La Serie G occupe une position précise dans le catalogue Oliva : c''est la gamme qui répond à la question de ce qu''une cape camerounaise fait au tabac nicaraguayen, quand l''une et l''autre sont choisies avec la précision que la maison réserve à ses lignes hautes.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La Serie G occupe une position précise dans le catalogue Oliva : c''est la gamme qui répond à la question de ce qu''une cape camerounaise fait au tabac nicaraguayen, quand l''une et l''autre sont choisies avec la précision que la maison réserve à ses lignes hautes.', 'La Serie G est une ligne d''Oliva Cigar Co., maison nicaraguayenne dont les cigares sont roulés à Estelí. Sa cape vient du Cameroun ; le liant et le filler viennent du Nicaragua. Selon la page de la maison, c''est un mélange de corps moyen.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Serie G occupies a specific and important position in the Oliva catalog: it is the range that answers the question of what a Cameroon wrapper does to Nicaraguan tobacco when both are selected with the precision the company brings to its premium lines.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Serie G occupies a specific and important position in the Oliva catalog: it is the range that answers the question of what a Cameroon wrapper does to Nicaraguan tobacco when both are selected with the precision the company brings to its premium lines.', 'The Serie G is a line from Oliva Cigar Co., a Nicaraguan house whose cigars are rolled in Estelí. Its wrapper comes from Cameroon; the binder and filler come from Nicaragua. According to the house’s page, it is a medium-bodied blend.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La Serie G ocupa un lugar preciso en el catálogo de Oliva: es la gama que responde a la pregunta de qué le hace una capa camerunesa al tabaco nicaragüense, cuando una y otro se eligen con la precisión que la casa reserva a sus líneas altas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La Serie G ocupa un lugar preciso en el catálogo de Oliva: es la gama que responde a la pregunta de qué le hace una capa camerunesa al tabaco nicaragüense, cuando una y otro se eligen con la precisión que la casa reserva a sus líneas altas.', 'La Serie G es una línea de Oliva Cigar Co., casa nicaragüense cuyos puros se tuercen en Estelí. Su capa viene de Camerún; el capote y la tripa vienen de Nicaragua. Según la página de la casa, es una mezcla de cuerpo medio.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Serie G nimmt im Katalog von Oliva eine genaue Stelle ein: Sie ist die Linie, die beantwortet, was ein Kameruner Deckblatt mit nicaraguanischem Tabak macht, wenn beide mit der Genauigkeit gewählt werden, die das Haus seinen hohen Linien vorbehält.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Serie G nimmt im Katalog von Oliva eine genaue Stelle ein: Sie ist die Linie, die beantwortet, was ein Kameruner Deckblatt mit nicaraguanischem Tabak macht, wenn beide mit der Genauigkeit gewählt werden, die das Haus seinen hohen Linien vorbehält.', 'Die Serie G ist eine Linie von Oliva Cigar Co., einem nicaraguanischen Haus, dessen Zigarren in Estelí gerollt werden. Ihr Deckblatt stammt aus Kamerun; Umblatt und Einlage stammen aus Nicaragua. Laut der Seite des Hauses ist sie eine Mischung von mittlerem Körper.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('G系列在奥利瓦的产品目录里位置很明确：它回答的是，当喀麦隆茄衣与尼加拉瓜烟叶都以本厂高端线的精度来挑选时，前者会给后者带来什么。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'G系列在奥利瓦的产品目录里位置很明确：它回答的是，当喀麦隆茄衣与尼加拉瓜烟叶都以本厂高端线的精度来挑选时，前者会给后者带来什么。', 'Serie G 是 Oliva Cigar Co. 旗下的一个系列，这是一家尼加拉瓜公司，其雪茄在埃斯特利卷制。茄衣来自喀麦隆；茄套与茄芯来自尼加拉瓜。据该公司的页面介绍，这是一款中等醇厚度的混合。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تحتلّ السلسلة G موقعًا محدّدًا في كتالوغ أوليفا: فهي التشكيلة التي تجيب عن سؤال ما الذي يفعله غلاف كاميروني بالتبغ النيكاراغوي، حين يُنتقى الاثنان بالدقة التي تحفظها الدار لخطوطها العليا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تحتلّ السلسلة G موقعًا محدّدًا في كتالوغ أوليفا: فهي التشكيلة التي تجيب عن سؤال ما الذي يفعله غلاف كاميروني بالتبغ النيكاراغوي، حين يُنتقى الاثنان بالدقة التي تحفظها الدار لخطوطها العليا.', 'Serie G خط من Oliva Cigar Co.، دار نيكاراغوية يُلَفّ سيجارها في إستيلي. غلافها من الكاميرون، أما الغلاف الداخلي والحشوة فمن نيكاراغوا. وبحسب صفحة الدار، هي خلطة متوسطة الجسم.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Serie G';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Cape du Cameroun sur tripe nicaraguayenne de Jalapa n''est pas une combinaison rare — on la trouve partout sur le marché premium — mais l''exécution change tout. Les feuilles retenues par Oliva pour la Serie G viennent du milieu de gamme de la province du Centre : plus sombres et plus complexes que ce qui entre dans les camerounais courants, sans la structure de coût des sélections AVO XO réservées aux gammes plus chères. Il en résulte une cape qui donne chocolat et épice douce à un prix qui autorise le cigare quotidien.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Cape du Cameroun sur tripe nicaraguayenne de Jalapa n''est pas une combinaison rare — on la trouve partout sur le marché premium — mais l''exécution change tout. Les feuilles retenues par Oliva pour la Serie G viennent du milieu de gamme de la province du Centre : plus sombres et plus complexes que ce qui entre dans les camerounais courants, sans la structure de coût des sélections AVO XO réservées aux gammes plus chères. Il en résulte une cape qui donne chocolat et épice douce à un prix qui autorise le cigare quotidien.', 'La page de la maison (olivacigar.com, consultée en octobre 2026) parle d''une cape africaine du Cameroun et de fillers nicaraguayens « Sun Grown ». La presse du métier, en 2007, décrit le Robusto box-pressed comme un cigare à cape du Cameroun, liant et filler du Nicaragua, ce dernier de graine cubaine. Aucune page lue ne dit de quelle zone du Cameroun viennent les feuilles, ni de quelle zone du Nicaragua vient la tripe.'), `history`),
  `history_en` = IF(LOCATE(CAST('Cameroonian wrapper over Nicaraguan Jalapa filler is not an unusual combination — it appears across the premium market — but the specific execution matters enormously. The leaves sourced by Oliva for the Serie G represent the Centre province''s mid-tier production: darker and more complex than what goes into standard market Cameroon cigars, but without the cost structure of the AVO XO selections that appear in more expensive ranges. The result is a wrapper that delivers chocolate and mild spice at a price point that justifies daily smoking.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Cameroonian wrapper over Nicaraguan Jalapa filler is not an unusual combination — it appears across the premium market — but the specific execution matters enormously. The leaves sourced by Oliva for the Serie G represent the Centre province''s mid-tier production: darker and more complex than what goes into standard market Cameroon cigars, but without the cost structure of the AVO XO selections that appear in more expensive ranges. The result is a wrapper that delivers chocolate and mild spice at a price point that justifies daily smoking.', 'The house’s page (olivacigar.com, consulted in October 2026) speaks of an African wrapper from Cameroon and of Nicaraguan fillers described as ‘Sun Grown’. The trade press, in 2007, describes the box-pressed Robusto as a cigar with a Cameroon wrapper and a Nicaraguan binder and filler, the latter of Cuban seed. No page read says which area of Cameroon the leaves come from, nor which area of Nicaragua the filler comes from.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Capa de Camerún sobre tripa nicaragüense de Jalapa no es una combinación rara —se encuentra por todo el mercado premium—, pero la ejecución lo cambia todo. Las hojas que Oliva retiene para la Serie G vienen de la parte media de la provincia del Centro: más oscuras y más complejas que las que entran en los cameruneses corrientes, sin la estructura de coste de las selecciones AVO XO reservadas a gamas más caras. El resultado es una capa que da chocolate y especia suave a un precio que permite el puro de todos los días.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Capa de Camerún sobre tripa nicaragüense de Jalapa no es una combinación rara —se encuentra por todo el mercado premium—, pero la ejecución lo cambia todo. Las hojas que Oliva retiene para la Serie G vienen de la parte media de la provincia del Centro: más oscuras y más complejas que las que entran en los cameruneses corrientes, sin la estructura de coste de las selecciones AVO XO reservadas a gamas más caras. El resultado es una capa que da chocolate y especia suave a un precio que permite el puro de todos los días.', 'La página de la casa (olivacigar.com, consultada en octubre de 2026) habla de una capa africana de Camerún y de tripas nicaragüenses «Sun Grown». La prensa del sector, en 2007, describe el Robusto prensado en caja como un puro con capa de Camerún, capote y tripa de Nicaragua, esta última de semilla cubana. Ninguna página leída dice de qué zona de Camerún vienen las hojas, ni de qué zona de Nicaragua viene la tripa.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Kamerun-Deckblatt auf nicaraguanischer Einlage aus Jalapa ist keine seltene Verbindung — man findet sie überall im Premiumsegment —, doch die Ausführung macht den Unterschied. Die Blätter, die Oliva für die Serie G zurückhält, stammen aus der mittleren Lage der Zentralprovinz: dunkler und vielschichtiger als das, was in gewöhnliche Kameruner eingeht, ohne die Kostenstruktur der AVO-XO-Auslesen, die teureren Linien vorbehalten bleiben. Daraus entsteht ein Deckblatt, das Schokolade und milde Würze gibt, zu einem Preis, der die Zigarre für jeden Tag erlaubt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Kamerun-Deckblatt auf nicaraguanischer Einlage aus Jalapa ist keine seltene Verbindung — man findet sie überall im Premiumsegment —, doch die Ausführung macht den Unterschied. Die Blätter, die Oliva für die Serie G zurückhält, stammen aus der mittleren Lage der Zentralprovinz: dunkler und vielschichtiger als das, was in gewöhnliche Kameruner eingeht, ohne die Kostenstruktur der AVO-XO-Auslesen, die teureren Linien vorbehalten bleiben. Daraus entsteht ein Deckblatt, das Schokolade und milde Würze gibt, zu einem Preis, der die Zigarre für jeden Tag erlaubt.', 'Die Seite des Hauses (olivacigar.com, abgerufen im Oktober 2026) spricht von einem afrikanischen Deckblatt aus Kamerun und von nicaraguanischen Einlagen „Sun Grown“. Die Fachpresse beschreibt 2007 den Robusto in Kastenpressung als Zigarre mit Deckblatt aus Kamerun, Umblatt und Einlage aus Nicaragua, Letztere aus kubanischem Saatgut. Keine gelesene Seite sagt, aus welcher Gegend Kameruns die Blätter stammen und aus welcher Gegend Nicaraguas die Einlage kommt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('喀麦隆茄衣配哈拉帕的尼加拉瓜茄芯并不稀奇——高端市场上到处都是——但做法决定一切。奥利瓦为G系列留下的叶子来自中部省的中段：比普通喀麦隆用叶更深、更复杂，却没有留给更贵产品线的 AVO XO 选料那样的成本结构。于是就有了这样一张茄衣：给出巧克力与柔和香料，价格却容得下每天一支。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '喀麦隆茄衣配哈拉帕的尼加拉瓜茄芯并不稀奇——高端市场上到处都是——但做法决定一切。奥利瓦为G系列留下的叶子来自中部省的中段：比普通喀麦隆用叶更深、更复杂，却没有留给更贵产品线的 AVO XO 选料那样的成本结构。于是就有了这样一张茄衣：给出巧克力与柔和香料，价格却容得下每天一支。', '该公司页面（olivacigar.com，2026年10月查阅）提到来自喀麦隆的非洲茄衣，以及尼加拉瓜的“Sun Grown”茄芯。行业媒体在2007年把方形压制的 Robusto 描述为喀麦隆茄衣、尼加拉瓜茄套与茄芯的雪茄，其中茄芯为古巴种子。所查阅的页面均未说明叶片来自喀麦隆的哪个产区，也未说明茄芯来自尼加拉瓜的哪个产区。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('غلاف من الكاميرون فوق حشوة نيكاراغوية من خالابا ليس تركيبًا نادرًا — تجده في كل مكان في السوق الفاخرة — غير أنّ التنفيذ هو ما يغيّر كل شيء. الأوراق التي تحتفظ بها أوليفا للسلسلة G تأتي من الطبقة الوسطى في المقاطعة الوسطى: أدكن وأكثر تركيبًا مما يدخل في الكاميروني المعتاد، دون بنية كلفة منتقيات AVO XO المحفوظة لتشكيلات أغلى. والنتيجة غلاف يعطي الشوكولاتة والتوابل اللطيفة بسعر يسمح بسيجار كل يوم.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'غلاف من الكاميرون فوق حشوة نيكاراغوية من خالابا ليس تركيبًا نادرًا — تجده في كل مكان في السوق الفاخرة — غير أنّ التنفيذ هو ما يغيّر كل شيء. الأوراق التي تحتفظ بها أوليفا للسلسلة G تأتي من الطبقة الوسطى في المقاطعة الوسطى: أدكن وأكثر تركيبًا مما يدخل في الكاميروني المعتاد، دون بنية كلفة منتقيات AVO XO المحفوظة لتشكيلات أغلى. والنتيجة غلاف يعطي الشوكولاتة والتوابل اللطيفة بسعر يسمح بسيجار كل يوم.', 'تتحدث صفحة الدار (olivacigar.com، اطُّلع عليها في أكتوبر 2026) عن غلاف أفريقي من الكاميرون وحشوات نيكاراغوية «Sun Grown». وتصف الصحافة المتخصصة عام 2007 سيجار Robusto المضغوط في علبة بأنه سيجار بغلاف من الكاميرون وغلاف داخلي وحشوة من نيكاراغوا، والأخيرة من بذرة كوبية. ولا تذكر أي صفحة مقروءة من أي منطقة في الكاميرون جاءت الأوراق، ولا من أي منطقة في نيكاراغوا جاءت الحشوة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Serie G';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La tripe de Jalapa — récoltée sur les plantations d''Oliva — ajoute sous cette douceur la profondeur terreuse propre à la maison. L''ensemble se tient en mi-corsé à corsé, sans la puissance frontale de la Serie V : noisette et chocolat au lait d''abord, puis café et cèdre, vers une finale de poivre doux et de fruits secs. C''est un cigare qui tient sa complexité sur toute sa longueur, sans à-coups d''intensité.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La tripe de Jalapa — récoltée sur les plantations d''Oliva — ajoute sous cette douceur la profondeur terreuse propre à la maison. L''ensemble se tient en mi-corsé à corsé, sans la puissance frontale de la Serie V : noisette et chocolat au lait d''abord, puis café et cèdre, vers une finale de poivre doux et de fruits secs. C''est un cigare qui tient sa complexité sur toute sa longueur, sans à-coups d''intensité.', 'La maison annonce des notes de cèdre et de café. Elle propose en octobre 2026 neuf formats, du Special G (3,75 x 48) au Churchill (7 x 50), dont un Figurado, un Torpedo, un Belicoso et un Tubo, ainsi qu''une Serie G Maduro.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Nicaraguan filler from Jalapa — harvested from Oliva''s own farms — adds the house''s characteristic earthy depth beneath the Cameroon sweetness. The combination produces a profile that sits at Medium-Full without the aggressive power of the Serie V: hazelnut and milk chocolate lead, transitioning through coffee and cedar toward a finish of mild pepper and dried fruit. It is a cigar that holds complexity across its entire length without sudden intensity spikes.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Nicaraguan filler from Jalapa — harvested from Oliva''s own farms — adds the house''s characteristic earthy depth beneath the Cameroon sweetness. The combination produces a profile that sits at Medium-Full without the aggressive power of the Serie V: hazelnut and milk chocolate lead, transitioning through coffee and cedar toward a finish of mild pepper and dried fruit. It is a cigar that holds complexity across its entire length without sudden intensity spikes.', 'The house announces notes of cedar and coffee. In October 2026 it offers nine formats, from the Special G (3.75 x 48) to the Churchill (7 x 50), including a Figurado, a Torpedo, a Belicoso and a Tubo, as well as a Serie G Maduro.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La tripa de Jalapa —cosechada en las plantaciones de Oliva— añade bajo esa dulzura la profundidad terrosa propia de la casa. El conjunto se sostiene en medio a fuerte, sin la potencia frontal de la Serie V: avellana y chocolate con leche primero, luego café y cedro, hacia un final de pimienta suave y frutos secos. Es un puro que mantiene su complejidad de punta a punta, sin sobresaltos de intensidad.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La tripa de Jalapa —cosechada en las plantaciones de Oliva— añade bajo esa dulzura la profundidad terrosa propia de la casa. El conjunto se sostiene en medio a fuerte, sin la potencia frontal de la Serie V: avellana y chocolate con leche primero, luego café y cedro, hacia un final de pimienta suave y frutos secos. Es un puro que mantiene su complejidad de punta a punta, sin sobresaltos de intensidad.', 'La casa anuncia notas de cedro y de café. En octubre de 2026 ofrece nueve formatos, del Special G (3,75 x 48) al Churchill (7 x 50), entre ellos un Figurado, un Torpedo, un Belicoso y un Tubo, además de una Serie G Maduro.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Einlage aus Jalapa — auf Olivas eigenen Plantagen geerntet — legt unter diese Milde die erdige Tiefe des Hauses. Das Ganze hält sich im mittelkräftigen bis kräftigen Bereich, ohne die frontale Wucht der Serie V: zuerst Haselnuss und Milchschokolade, dann Kaffee und Zeder, hin zu einem Abgang aus milder Pfefferschärfe und Trockenfrüchten. Eine Zigarre, die ihre Vielschichtigkeit über die ganze Länge hält, ohne Sprünge in der Intensität.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Einlage aus Jalapa — auf Olivas eigenen Plantagen geerntet — legt unter diese Milde die erdige Tiefe des Hauses. Das Ganze hält sich im mittelkräftigen bis kräftigen Bereich, ohne die frontale Wucht der Serie V: zuerst Haselnuss und Milchschokolade, dann Kaffee und Zeder, hin zu einem Abgang aus milder Pfefferschärfe und Trockenfrüchten. Eine Zigarre, die ihre Vielschichtigkeit über die ganze Länge hält, ohne Sprünge in der Intensität.', 'Das Haus gibt Noten von Zeder und Kaffee an. Im Oktober 2026 bietet es neun Formate an, vom Special G (3,75 x 48) bis zum Churchill (7 x 50), darunter ein Figurado, ein Torpedo, ein Belicoso und ein Tubo, dazu eine Serie G Maduro.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('来自哈拉帕的茄芯——采自奥利瓦自有的种植园——在这份甜润之下垫上本厂特有的泥土般的厚度。整体停在中浓到浓之间，没有V系列那种正面的力道：先是榛子与牛奶巧克力，接着是咖啡与雪松，走向柔和胡椒与坚果干的收尾。这是一支从头到尾把复杂度端稳的雪茄，没有忽强忽弱。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '来自哈拉帕的茄芯——采自奥利瓦自有的种植园——在这份甜润之下垫上本厂特有的泥土般的厚度。整体停在中浓到浓之间，没有V系列那种正面的力道：先是榛子与牛奶巧克力，接着是咖啡与雪松，走向柔和胡椒与坚果干的收尾。这是一支从头到尾把复杂度端稳的雪茄，没有忽强忽弱。', '该公司标示有雪松与咖啡的气息。2026年10月提供九种规格，从 Special G（3.75 x 48）到 Churchill（7 x 50），其中包括一款 Figurado、一款 Torpedo、一款 Belicoso 和一款 Tubo，此外还有 Serie G Maduro。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أما حشوة خالابا — المجنيّة من مزارع أوليفا نفسها — فتضع تحت هذه الحلاوة العمق الترابي الذي تُعرف به الدار. يستقرّ المجموع بين المتوسط والقوي، دون الاندفاع الأمامي للسلسلة V: بندق وشوكولاتة بالحليب أولًا، ثم قهوة وخشب الأرز، نحو نهاية من فلفل لطيف وفواكه مجفّفة. سيجار يحمل تركيبه من أوله إلى آخره، بلا قفزات في الشدّة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أما حشوة خالابا — المجنيّة من مزارع أوليفا نفسها — فتضع تحت هذه الحلاوة العمق الترابي الذي تُعرف به الدار. يستقرّ المجموع بين المتوسط والقوي، دون الاندفاع الأمامي للسلسلة V: بندق وشوكولاتة بالحليب أولًا، ثم قهوة وخشب الأرز، نحو نهاية من فلفل لطيف وفواكه مجفّفة. سيجار يحمل تركيبه من أوله إلى آخره، بلا قفزات في الشدّة.', 'تعلن الدار عن نفحات من خشب الأرز والقهوة. وتعرض في أكتوبر 2026 تسعة أحجام، من Special G (3.75 x 48) إلى Churchill (7 x 50)، منها Figurado وTorpedo وBelicoso وTubo، إضافة إلى Serie G Maduro.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Serie G';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La Serie G a été conçue comme la porte d''entrée du catalogue — celle qui fait découvrir ce que le tabac de Jalapa sait faire, avant la Serie V et le Melanio. Dans les faits, elle est aussi devenue la gamme vers laquelle les fumeurs expérimentés reviennent quand ils veulent la qualité sans l''exigence physique d''un corsé. Ce double rôle, seuil et destination, compte autant que sa position de ligne la plus accessible du catalogue.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La Serie G a été conçue comme la porte d''entrée du catalogue — celle qui fait découvrir ce que le tabac de Jalapa sait faire, avant la Serie V et le Melanio. Dans les faits, elle est aussi devenue la gamme vers laquelle les fumeurs expérimentés reviennent quand ils veulent la qualité sans l''exigence physique d''un corsé. Ce double rôle, seuil et destination, compte autant que sa position de ligne la plus accessible du catalogue.', 'Oliva a été fondée en 1995 sous le nom de Gilberto Oliva, devenu Oliva en 1996 (Wikipédia) ; la maison est passée à J. Cortès Cigars N.V. (Belgique) en juillet 2016. L''année de lancement de la Serie G n''est donnée par aucune page de la maison. Wikipédia signale aussi une petite fabrique à Danlí (Honduras) pour des produits d''entrée de gamme de la maison, sans nommer la Serie G.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Serie G was designed as the entry point to the Oliva experience — the range that introduces new smokers to what Nicaraguan tobacco from Jalapa can do before they graduate to the fuller expressions of the Serie V and Melanio. In practice, it has also become the range that experienced smokers return to when they want premium quality without the physical demand of a full-body smoke. This dual role — gateway and destination — is what makes the Serie G commercially important beyond its position as the catalog''s most accessible line.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Serie G was designed as the entry point to the Oliva experience — the range that introduces new smokers to what Nicaraguan tobacco from Jalapa can do before they graduate to the fuller expressions of the Serie V and Melanio. In practice, it has also become the range that experienced smokers return to when they want premium quality without the physical demand of a full-body smoke. This dual role — gateway and destination — is what makes the Serie G commercially important beyond its position as the catalog''s most accessible line.', 'Oliva was founded in 1995 under the name Gilberto Oliva, which became Oliva in 1996 (Wikipedia); the house passed to J. Cortès Cigars N.V. (Belgium) in July 2016. The launch year of the Serie G is not given by any page of the house. Wikipedia also mentions a small factory in Danlí (Honduras) for entry-level products of the house, without naming the Serie G.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La Serie G se concibió como la puerta de entrada del catálogo —la que da a conocer lo que sabe hacer el tabaco de Jalapa, antes de la Serie V y el Melanio. En los hechos, se ha convertido también en la gama a la que vuelven los fumadores experimentados cuando quieren la calidad sin la exigencia física de un fuerte. Ese doble papel, umbral y destino, cuenta tanto como su posición de línea más accesible del catálogo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La Serie G se concibió como la puerta de entrada del catálogo —la que da a conocer lo que sabe hacer el tabaco de Jalapa, antes de la Serie V y el Melanio. En los hechos, se ha convertido también en la gama a la que vuelven los fumadores experimentados cuando quieren la calidad sin la exigencia física de un fuerte. Ese doble papel, umbral y destino, cuenta tanto como su posición de línea más accesible del catálogo.', 'Oliva se fundó en 1995 con el nombre de Gilberto Oliva, que pasó a ser Oliva en 1996 (Wikipedia); la casa pasó a manos de J. Cortès Cigars N.V. (Bélgica) en julio de 2016. Ninguna página de la casa da el año de lanzamiento de la Serie G. Wikipedia señala también una pequeña fábrica en Danlí (Honduras) para productos de entrada de gama de la casa, sin nombrar la Serie G.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Serie G war als Eingangstür des Katalogs gedacht — jene, die zeigt, was der Tabak aus Jalapa kann, vor der Serie V und dem Melanio. Tatsächlich ist sie auch zu der Linie geworden, zu der erfahrene Raucher zurückkehren, wenn sie die Qualität ohne die körperliche Forderung einer kräftigen Zigarre wollen. Diese Doppelrolle, Schwelle und Ziel, wiegt so schwer wie ihr Rang als zugänglichste Linie des Katalogs.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Serie G war als Eingangstür des Katalogs gedacht — jene, die zeigt, was der Tabak aus Jalapa kann, vor der Serie V und dem Melanio. Tatsächlich ist sie auch zu der Linie geworden, zu der erfahrene Raucher zurückkehren, wenn sie die Qualität ohne die körperliche Forderung einer kräftigen Zigarre wollen. Diese Doppelrolle, Schwelle und Ziel, wiegt so schwer wie ihr Rang als zugänglichste Linie des Katalogs.', 'Oliva wurde 1995 unter dem Namen Gilberto Oliva gegründet, der 1996 zu Oliva wurde (Wikipedia); das Haus ging im Juli 2016 an J. Cortès Cigars N.V. (Belgien) über. Das Einführungsjahr der Serie G nennt keine Seite des Hauses. Wikipedia erwähnt außerdem eine kleine Fabrik in Danlí (Honduras) für Einstiegsprodukte des Hauses, ohne die Serie G zu nennen.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('G系列本是作为目录的入门而设计的——在V系列与梅拉尼奥之前，先让人见识哈拉帕烟叶的本事。而实际上，它也成了老烟客回头的那条线：想要品质，又不愿承受浓味雪茄对身体的要求。这种既是门槛又是归处的双重角色，与它作为目录中最易入手一线的位置同样要紧。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'G系列本是作为目录的入门而设计的——在V系列与梅拉尼奥之前，先让人见识哈拉帕烟叶的本事。而实际上，它也成了老烟客回头的那条线：想要品质，又不愿承受浓味雪茄对身体的要求。这种既是门槛又是归处的双重角色，与它作为目录中最易入手一线的位置同样要紧。', 'Oliva 创立于1995年，当时名为 Gilberto Oliva，1996年改称 Oliva（维基百科）；该公司于2016年7月转归 J. Cortès Cigars N.V.（比利时）。该公司的页面均未给出 Serie G 的推出年份。维基百科还提到该公司在丹利（洪都拉斯）有一家小型工厂，生产入门级产品，但未点名 Serie G。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('صُمِّمت السلسلة G لتكون باب الدخول إلى الكتالوغ — تلك التي تعرّف بما يستطيعه تبغ خالابا، قبل السلسلة V وميلانيو. وقد صارت في الواقع أيضًا التشكيلة التي يعود إليها المدخّنون المتمرّسون حين يريدون الجودة دون المطلب الجسدي لسيجار قوي. هذا الدور المزدوج، عتبةً ومقصدًا، لا يقلّ أهمية عن موقعها بوصفها أيسر خطوط الكتالوغ تناولًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'صُمِّمت السلسلة G لتكون باب الدخول إلى الكتالوغ — تلك التي تعرّف بما يستطيعه تبغ خالابا، قبل السلسلة V وميلانيو. وقد صارت في الواقع أيضًا التشكيلة التي يعود إليها المدخّنون المتمرّسون حين يريدون الجودة دون المطلب الجسدي لسيجار قوي. هذا الدور المزدوج، عتبةً ومقصدًا، لا يقلّ أهمية عن موقعها بوصفها أيسر خطوط الكتالوغ تناولًا.', 'تأسست Oliva عام 1995 باسم Gilberto Oliva، ثم صار الاسم Oliva عام 1996 (ويكيبيديا)؛ وانتقلت الدار إلى J. Cortès Cigars N.V. (بلجيكا) في يوليو 2016. ولا تذكر أي صفحة من صفحات الدار سنة إطلاق Serie G. وتشير ويكيبيديا أيضًا إلى مصنع صغير في دانلي (هندوراس) لمنتجات الدار من فئة الدخول، من دون ذكر Serie G.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Serie G';

UPDATE `brands` SET
  `country_id` = 'nicaragua',
  `factory` = 'Oliva Cigar Co. (Tabacalera Oliva), Estelí, Nicaragua ; fabrique exacte de la Serie G non précisée par la maison',
  `gamme` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"Cape du Cameroun sur liant et filler du Nicaragua ; corps moyen selon la maison, notes de cèdre et de café. Neuf formats en octobre 2026, du Special G au Churchill, dont Robusto 4,5 x 50, Torpedo, Belicoso, Figurado et Tubo.","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"Cameroun"}]',
  `gamme_en` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"Cameroon wrapper over a Nicaraguan binder and filler; medium body according to the house, notes of cedar and coffee. Nine formats in October 2026, from the Special G to the Churchill, including Robusto 4.5 x 50, Torpedo, Belicoso, Figurado and Tubo.","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"Cameroon"}]',
  `gamme_es` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"Capa de Camerún sobre capote y tripa de Nicaragua; cuerpo medio según la casa, notas de cedro y de café. Nueve formatos en octubre de 2026, del Special G al Churchill, entre ellos Robusto 4,5 x 50, Torpedo, Belicoso, Figurado y Tubo.","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"Camerún"}]',
  `gamme_de` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"Deckblatt aus Kamerun auf Umblatt und Einlage aus Nicaragua; mittlerer Körper laut Haus, Noten von Zeder und Kaffee. Neun Formate im Oktober 2026, vom Special G bis zum Churchill, darunter Robusto 4,5 x 50, Torpedo, Belicoso, Figurado und Tubo.","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"Kamerun"}]',
  `gamme_zh` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"喀麦隆茄衣，配尼加拉瓜茄套与茄芯；据该公司称为中等醇厚，带雪松与咖啡的气息。2026年10月共有九种规格，从 Special G 到 Churchill，其中有 Robusto 4.5 x 50、Torpedo、Belicoso、Figurado 与 Tubo。","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"喀麦隆"}]',
  `gamme_ar` = '[{"name":"Serie G","color":"#8B6914","force":"Medium","story":"غلاف من الكاميرون فوق غلاف داخلي وحشوة من نيكاراغوا؛ جسم متوسط بحسب الدار، ونفحات من خشب الأرز والقهوة. تسعة أحجام في أكتوبر 2026، من Special G إلى Churchill، منها Robusto 4.5 x 50 وTorpedo وBelicoso وFigurado وTubo.","vitolas":["No.4","No.5","No.7","Belicoso"],"wrapper":"كاميروني"}]',
  `pairings` = '[]',
  `pairings_en` = '[]',
  `pairings_es` = '[]',
  `pairings_de` = '[]',
  `pairings_zh` = '[]',
  `pairings_ar` = '[]',
  `source` = IF(LOCATE(CAST('olivacigar.com et cigaraficionado.com — FICHE DE CAPE : cape camerounaise sur un cigare roulé par Oliva à Estelí' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'olivacigar.com et cigaraficionado.com — FICHE DE CAPE : cape camerounaise sur un cigare roulé par Oliva à Estelí', 'olivacigar.com « Serie G - Perfect Balance Of Smoke And Flavor » (octobre 2026 : cape Cameroun, liant et filler Nicaragua, corps moyen, neuf formats) ; cigaraficionado.com « Oliva Serie G Cameroon Robusto » (2007-01-01 : pays Nicaragua) ; cigaraficionado.com « Oliva Cigar Co. in major expansion mode » (2019-03-26 : Tabolisa I et II à Estelí ; rachat par J. Cortès en juillet 2016) ; en.wikipedia.org « Oliva Cigar Co. » (1995, 1996, Estelí, Danlí)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Serie G';

-- ── Oliva Connecticut Reserve ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('On tient d''ordinaire Oliva pour une maison de puissance. La Serie V, les Master Blends, le Melanio : des cigares construits sur l''intensité nicaraguayenne, ce profil terreux et poivré qui a fait la réputation de la vallée de Jalapa. En lançant une Connecticut Reserve, la maison entrait sur un terrain que beaucoup jugeaient étranger à son savoir-faire.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'On tient d''ordinaire Oliva pour une maison de puissance. La Serie V, les Master Blends, le Melanio : des cigares construits sur l''intensité nicaraguayenne, ce profil terreux et poivré qui a fait la réputation de la vallée de Jalapa. En lançant une Connecticut Reserve, la maison entrait sur un terrain que beaucoup jugeaient étranger à son savoir-faire.', 'Oliva Connecticut Reserve est une ligne de la maison Oliva, roulée à Estelí, au Nicaragua. Stogie Review la présente en février 2009 comme tout juste sortie ; un résultat de recherche (Cigar Inspector, non lu en page) parle de 2008.'), `history`),
  `history_en` = IF(LOCATE(CAST('The conventional wisdom about Oliva is that it means power. The Serie V, the Master Blends, the Melanio — these are cigars built around Nicaraguan intensity, the earthy pepper-driven profile that made the Jalapa Valley''s reputation. When Oliva decided to build a Connecticut Reserve line, it was entering territory many assumed was foreign to the house''s competence and identity.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The conventional wisdom about Oliva is that it means power. The Serie V, the Master Blends, the Melanio — these are cigars built around Nicaraguan intensity, the earthy pepper-driven profile that made the Jalapa Valley''s reputation. When Oliva decided to build a Connecticut Reserve line, it was entering territory many assumed was foreign to the house''s competence and identity.', 'Oliva Connecticut Reserve is a line from the house of Oliva, rolled in Estelí, Nicaragua. Stogie Review presents it in February 2009 as just released; a search result (Cigar Inspector, not read on the page) mentions 2008.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('A Oliva se la tiene de ordinario por una casa de potencia. La Serie V, los Master Blends, el Melanio: puros construidos sobre la intensidad nicaragüense, ese perfil terroso y apimentado que hizo la reputación del valle de Jalapa. Al lanzar una Connecticut Reserve, la casa entraba en un terreno que muchos juzgaban ajeno a su oficio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'A Oliva se la tiene de ordinario por una casa de potencia. La Serie V, los Master Blends, el Melanio: puros construidos sobre la intensidad nicaragüense, ese perfil terroso y apimentado que hizo la reputación del valle de Jalapa. Al lanzar una Connecticut Reserve, la casa entraba en un terreno que muchos juzgaban ajeno a su oficio.', 'Oliva Connecticut Reserve es una línea de la casa Oliva, torcida en Estelí, Nicaragua. Stogie Review la presenta en febrero de 2009 como recién salida; un resultado de búsqueda (Cigar Inspector, no leído en la página) habla de 2008.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Oliva gilt gemeinhin als ein Haus der Kraft. Die Serie V, die Master Blends, der Melanio: Zigarren, die auf nicaraguanischer Intensität gebaut sind, auf jenem erdigen, pfeffrigen Profil, das den Ruf des Jalapa-Tals begründet hat. Mit einer Connecticut Reserve betrat das Haus ein Feld, das viele seinem Können für fremd hielten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Oliva gilt gemeinhin als ein Haus der Kraft. Die Serie V, die Master Blends, der Melanio: Zigarren, die auf nicaraguanischer Intensität gebaut sind, auf jenem erdigen, pfeffrigen Profil, das den Ruf des Jalapa-Tals begründet hat. Mit einer Connecticut Reserve betrat das Haus ein Feld, das viele seinem Können für fremd hielten.', 'Oliva Connecticut Reserve ist eine Linie des Hauses Oliva, gerollt in Estelí, Nicaragua. Stogie Review stellt sie im Februar 2009 als gerade erschienen vor; ein Suchergebnis (Cigar Inspector, auf der Seite nicht gelesen) spricht von 2008.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('人们通常把奥利瓦看作一家做力度的字号。V系列、大师调配、梅拉尼奥：这些雪茄都建立在尼加拉瓜式的浓烈之上，那种让哈拉帕山谷成名的泥土与胡椒气息。推出康涅狄格珍藏时，这家厂踏进了许多人认为与它的手艺无关的地界。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '人们通常把奥利瓦看作一家做力度的字号。V系列、大师调配、梅拉尼奥：这些雪茄都建立在尼加拉瓜式的浓烈之上，那种让哈拉帕山谷成名的泥土与胡椒气息。推出康涅狄格珍藏时，这家厂踏进了许多人认为与它的手艺无关的地界。', 'Oliva Connecticut Reserve 是 Oliva 厂的一条产品线，在尼加拉瓜的埃斯特利卷制。Stogie Review 在2009年2月把它介绍为刚刚推出；一条搜索结果（Cigar Inspector，未在页面上读到）则提到2008年。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يُنظر إلى أوليفا عادةً بوصفها دار قوة. السلسلة V، وخلطات المعلّم، وميلانيو: سيجار مبنيّ على الشدّة النيكاراغوية، ذلك الطابع الترابي الفلفلي الذي صنع سمعة وادي خالابا. وبإطلاق «كونيتيكت ريزيرف» دخلت الدار أرضًا رآها كثيرون غريبة عن حرفتها.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يُنظر إلى أوليفا عادةً بوصفها دار قوة. السلسلة V، وخلطات المعلّم، وميلانيو: سيجار مبنيّ على الشدّة النيكاراغوية، ذلك الطابع الترابي الفلفلي الذي صنع سمعة وادي خالابا. وبإطلاق «كونيتيكت ريزيرف» دخلت الدار أرضًا رآها كثيرون غريبة عن حرفتها.', 'Oliva Connecticut Reserve خطّ إنتاج من دار Oliva، يُلفّ في إستيلي بنيكاراغوا. تقدّمه Stogie Review في فبراير 2009 على أنه صدر للتوّ؛ أما نتيجة بحث (Cigar Inspector، لم تُقرأ في صفحتها) فتذكر عام 2008.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Connecticut Reserve';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le résultat a montré que ce jugement était incomplet. La Connecticut Reserve porte une cape Connecticut Shade d''Équateur, cultivée en altitude dans les Andes — des conditions qui donnent une feuille de plus de caractère que le Connecticut américain, sans lui retirer l''onctuosité qui définit le style de l''ombrière. Cette cape, issue des mêmes plantations qui approvisionnent plusieurs gammes Davidoff, recouvre une tripe nicaraguayenne plus légère que tout ce que compte le catalogue Oliva.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le résultat a montré que ce jugement était incomplet. La Connecticut Reserve porte une cape Connecticut Shade d''Équateur, cultivée en altitude dans les Andes — des conditions qui donnent une feuille de plus de caractère que le Connecticut américain, sans lui retirer l''onctuosité qui définit le style de l''ombrière. Cette cape, issue des mêmes plantations qui approvisionnent plusieurs gammes Davidoff, recouvre une tripe nicaraguayenne plus légère que tout ce que compte le catalogue Oliva.', 'La cape est un Connecticut d''Équateur ; le liant et la tripe viennent du Nicaragua, dit la page de la maison (olivacigar.com), ce que confirme Stogie Review en 2009. La maison décrit un cigare de corps moyen, doux et suave, aux notes de bois discrètes ; Stogie Review le range de doux à moyen, au bas du moyen dans le dernier tiers.'), `history`),
  `history_en` = IF(LOCATE(CAST('The result demonstrated that the conventional wisdom was incomplete. The Connecticut Reserve uses an Ecuadorian Connecticut shade wrapper grown at high altitude in the Ecuadorian Andes — conditions that produce a leaf with more character than American Connecticut while preserving the shade-grown creaminess that defines the style. This wrapper, sourced from the same farms that supply several premium Davidoff lines, goes over a Nicaraguan filler blend lighter than anything in the core Oliva catalog.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The result demonstrated that the conventional wisdom was incomplete. The Connecticut Reserve uses an Ecuadorian Connecticut shade wrapper grown at high altitude in the Ecuadorian Andes — conditions that produce a leaf with more character than American Connecticut while preserving the shade-grown creaminess that defines the style. This wrapper, sourced from the same farms that supply several premium Davidoff lines, goes over a Nicaraguan filler blend lighter than anything in the core Oliva catalog.', 'The wrapper is an Ecuadorian Connecticut; the binder and filler come from Nicaragua, says the house''s page (olivacigar.com), which Stogie Review confirms in 2009. The house describes a medium-bodied cigar, mellow and smooth, with discreet notes of wood; Stogie Review places it from mild to medium, at the lower end of medium in the final third.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El resultado mostró que ese juicio era incompleto. La Connecticut Reserve lleva una capa Connecticut Shade de Ecuador, cultivada en altura en los Andes —condiciones que dan una hoja de más carácter que la Connecticut americana, sin quitarle la untuosidad que define el estilo de la sombra. Esa capa, procedente de las mismas plantaciones que abastecen varias gamas Davidoff, recubre una tripa nicaragüense más ligera que todo cuanto contiene el catálogo Oliva.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El resultado mostró que ese juicio era incompleto. La Connecticut Reserve lleva una capa Connecticut Shade de Ecuador, cultivada en altura en los Andes —condiciones que dan una hoja de más carácter que la Connecticut americana, sin quitarle la untuosidad que define el estilo de la sombra. Esa capa, procedente de las mismas plantaciones que abastecen varias gamas Davidoff, recubre una tripa nicaragüense más ligera que todo cuanto contiene el catálogo Oliva.', 'La capa es un Connecticut de Ecuador; el capote y la tripa vienen de Nicaragua, dice la página de la casa (olivacigar.com), lo que confirma Stogie Review en 2009. La casa describe un puro de cuerpo medio, suave y sedoso, con notas de madera discretas; Stogie Review lo sitúa de suave a medio, en la parte baja del medio en el último tercio.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Ergebnis hat gezeigt, dass dieses Urteil unvollständig war. Die Connecticut Reserve trägt ein Connecticut-Shade-Deckblatt aus Ecuador, in den Anden in Höhenlage gezogen — Bedingungen, die ein Blatt mit mehr Charakter ergeben als das amerikanische Connecticut, ohne ihm die Cremigkeit zu nehmen, die den Stil des Schattentabaks ausmacht. Dieses Deckblatt, von denselben Plantagen, die mehrere Davidoff-Linien beliefern, umschließt eine nicaraguanische Einlage, die leichter ist als alles andere im Katalog von Oliva.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Ergebnis hat gezeigt, dass dieses Urteil unvollständig war. Die Connecticut Reserve trägt ein Connecticut-Shade-Deckblatt aus Ecuador, in den Anden in Höhenlage gezogen — Bedingungen, die ein Blatt mit mehr Charakter ergeben als das amerikanische Connecticut, ohne ihm die Cremigkeit zu nehmen, die den Stil des Schattentabaks ausmacht. Dieses Deckblatt, von denselben Plantagen, die mehrere Davidoff-Linien beliefern, umschließt eine nicaraguanische Einlage, die leichter ist als alles andere im Katalog von Oliva.', 'Das Deckblatt ist ein Connecticut aus Ecuador; Umblatt und Einlage stammen aus Nicaragua, sagt die Seite des Hauses (olivacigar.com), was Stogie Review 2009 bestätigt. Das Haus beschreibt eine Zigarre von mittlerem Körper, mild und weich, mit dezenten Holznoten; Stogie Review ordnet sie von mild bis mittel ein, im letzten Drittel am unteren Ende von mittel.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('结果证明这个判断并不完整。康涅狄格珍藏用的是厄瓜多尔的康涅狄格阴植茄衣，种在安第斯的高海拔处——这样的条件长出的叶子比美国康涅狄格更有性格，却不失阴植风格特有的顺滑。这张茄衣来自同时供应多条大卫杜夫产品线的种植园，包裹的是奥利瓦目录中最轻的一副尼加拉瓜茄芯。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '结果证明这个判断并不完整。康涅狄格珍藏用的是厄瓜多尔的康涅狄格阴植茄衣，种在安第斯的高海拔处——这样的条件长出的叶子比美国康涅狄格更有性格，却不失阴植风格特有的顺滑。这张茄衣来自同时供应多条大卫杜夫产品线的种植园，包裹的是奥利瓦目录中最轻的一副尼加拉瓜茄芯。', '茄衣是厄瓜多尔的 Connecticut；茄套叶和茄芯来自尼加拉瓜，厂方页面（olivacigar.com）如此写道，Stogie Review 在2009年也予以证实。厂方描述这是一支中等浓度、柔和顺滑、带含蓄木质气息的雪茄；Stogie Review 将它归为柔和至中度，在后段三分之一处位于中度的偏低一端。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أظهرت النتيجة أن هذا الحكم كان ناقصًا. تحمل «كونيتيكت ريزيرف» غلاف كونيتيكت شيد من الإكوادور، مزروعًا على ارتفاع في الأنديز — ظروف تعطي ورقة أكثر شخصية من الكونيتيكت الأمريكية، دون أن تسلبها النعومة الدسمة التي تحدّد أسلوب التبغ المزروع تحت الظلّ. وهذا الغلاف، الآتي من المزارع نفسها التي تزوّد عدة تشكيلات لدى دافيدوف، يغلّف حشوة نيكاراغوية أخفّ من كل ما في كتالوغ أوليفا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أظهرت النتيجة أن هذا الحكم كان ناقصًا. تحمل «كونيتيكت ريزيرف» غلاف كونيتيكت شيد من الإكوادور، مزروعًا على ارتفاع في الأنديز — ظروف تعطي ورقة أكثر شخصية من الكونيتيكت الأمريكية، دون أن تسلبها النعومة الدسمة التي تحدّد أسلوب التبغ المزروع تحت الظلّ. وهذا الغلاف، الآتي من المزارع نفسها التي تزوّد عدة تشكيلات لدى دافيدوف، يغلّف حشوة نيكاراغوية أخفّ من كل ما في كتالوغ أوليفا.', 'الغلاف من نوع Connecticut إكوادوري؛ أما الغلاف الداخلي والحشوة فمن نيكاراغوا، كما تقول صفحة الدار (olivacigar.com)، وهو ما تؤكده Stogie Review عام 2009. وتصف الدار سيجارًا متوسط الجسم، لطيفًا وسلسًا، بنكهات خشبية خفيفة؛ وتضعه Stogie Review ضمن نطاق من لطيف إلى متوسط، عند الطرف المنخفض من المتوسط في الثلث الأخير.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Connecticut Reserve';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Ce qu''Oliva apporte à cette formule tient à la précision de son approvisionnement. La maison possède ses plantations nicaraguayennes en propre — les parcelles de Jalapa et d''Estelí qui alimentent tout le catalogue. Elle peut donc prélever, dans son propre stock, des feuilles plus légères et récoltées plus tôt, inutilisables pour la Serie V mais exactement calibrées pour un assemblage moyen-léger. Il en sort un cigare qui offre une vraie complexité — crème, céréales grillées, vanille, cèdre léger — sans le poids qui écraserait un cigare du matin ou le premier de la soirée.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Ce qu''Oliva apporte à cette formule tient à la précision de son approvisionnement. La maison possède ses plantations nicaraguayennes en propre — les parcelles de Jalapa et d''Estelí qui alimentent tout le catalogue. Elle peut donc prélever, dans son propre stock, des feuilles plus légères et récoltées plus tôt, inutilisables pour la Serie V mais exactement calibrées pour un assemblage moyen-léger. Il en sort un cigare qui offre une vraie complexité — crème, céréales grillées, vanille, cèdre léger — sans le poids qui écraserait un cigare du matin ou le premier de la soirée.', 'Oliva roule ses cigares premium à Estelí, à Tabolisa I, fabrique principale de la maison selon la presse du métier en 2023. Selon Wikipédia, la maison cultive son propre tabac à Estelí, Condega, Jalapa et Somoto. La maison appartient depuis l''été 2016 à J. Cortès, société belge devenue Vandermarliere Family of Cigars ; la famille Oliva reste active dans l''entreprise.'), `history`),
  `history_en` = IF(LOCATE(CAST('What Oliva brings to this formula that other Connecticut-style cigars cannot match is its sourcing precision. The company owns its Nicaraguan farms outright — the Jalapa and Estelí plots that supply the entire Oliva catalog. This allows them to select, from within their own inventory, lighter, earlier-harvested leaves that would be unsuitable for the Serie V but are perfectly calibrated for a medium-light blend. The result is a cigar that delivers genuine complexity — cream, toasted grain, vanilla, light cedar — without the weight that would overwhelm a morning smoke or a first cigar of the evening.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'What Oliva brings to this formula that other Connecticut-style cigars cannot match is its sourcing precision. The company owns its Nicaraguan farms outright — the Jalapa and Estelí plots that supply the entire Oliva catalog. This allows them to select, from within their own inventory, lighter, earlier-harvested leaves that would be unsuitable for the Serie V but are perfectly calibrated for a medium-light blend. The result is a cigar that delivers genuine complexity — cream, toasted grain, vanilla, light cedar — without the weight that would overwhelm a morning smoke or a first cigar of the evening.', 'Oliva rolls its premium cigars in Estelí, at Tabolisa I, the house''s main factory according to the trade press in 2023. According to Wikipedia, the house grows its own tobacco in Estelí, Condega, Jalapa and Somoto. Since summer 2016 the house has belonged to J. Cortès, a Belgian company that became Vandermarliere Family of Cigars; the Oliva family remains active in the business.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Lo que Oliva aporta a esta fórmula está en la precisión de su abastecimiento. La casa posee sus propias plantaciones nicaragüenses —las parcelas de Jalapa y de Estelí que alimentan todo el catálogo. Puede por tanto tomar, de su propio stock, hojas más ligeras y recogidas antes, inservibles para la Serie V pero exactamente calibradas para una ligada media-ligera. Sale de ahí un puro que ofrece verdadera complejidad —crema, cereales tostados, vainilla, cedro ligero— sin el peso que aplastaría un puro de la mañana o el primero de la noche.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Lo que Oliva aporta a esta fórmula está en la precisión de su abastecimiento. La casa posee sus propias plantaciones nicaragüenses —las parcelas de Jalapa y de Estelí que alimentan todo el catálogo. Puede por tanto tomar, de su propio stock, hojas más ligeras y recogidas antes, inservibles para la Serie V pero exactamente calibradas para una ligada media-ligera. Sale de ahí un puro que ofrece verdadera complejidad —crema, cereales tostados, vainilla, cedro ligero— sin el peso que aplastaría un puro de la mañana o el primero de la noche.', 'Oliva tuerce sus puros premium en Estelí, en Tabolisa I, fábrica principal de la casa según la prensa del sector en 2023. Según Wikipedia, la casa cultiva su propio tabaco en Estelí, Condega, Jalapa y Somoto. La casa pertenece desde el verano de 2016 a J. Cortès, sociedad belga convertida en Vandermarliere Family of Cigars; la familia Oliva sigue activa en la empresa.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Was Oliva dieser Formel hinzufügt, liegt in der Genauigkeit seiner Beschaffung. Das Haus besitzt seine nicaraguanischen Plantagen selbst — die Parzellen in Jalapa und Estelí, die den ganzen Katalog versorgen. Es kann also aus dem eigenen Bestand leichtere, früher geerntete Blätter nehmen, für die Serie V unbrauchbar, für eine mittelleichte Mischung aber genau berechnet. Daraus entsteht eine Zigarre mit wirklicher Vielschichtigkeit — Sahne, geröstetes Getreide, Vanille, leichte Zeder — ohne das Gewicht, das eine Morgenzigarre oder die erste des Abends erdrücken würde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Was Oliva dieser Formel hinzufügt, liegt in der Genauigkeit seiner Beschaffung. Das Haus besitzt seine nicaraguanischen Plantagen selbst — die Parzellen in Jalapa und Estelí, die den ganzen Katalog versorgen. Es kann also aus dem eigenen Bestand leichtere, früher geerntete Blätter nehmen, für die Serie V unbrauchbar, für eine mittelleichte Mischung aber genau berechnet. Daraus entsteht eine Zigarre mit wirklicher Vielschichtigkeit — Sahne, geröstetes Getreide, Vanille, leichte Zeder — ohne das Gewicht, das eine Morgenzigarre oder die erste des Abends erdrücken würde.', 'Oliva rollt seine Premium-Zigarren in Estelí, in der Tabolisa I, laut Fachpresse 2023 die Hauptfabrik des Hauses. Laut Wikipedia baut das Haus seinen eigenen Tabak in Estelí, Condega, Jalapa und Somoto an. Seit dem Sommer 2016 gehört das Haus J. Cortès, einem belgischen Unternehmen, das zu Vandermarliere Family of Cigars geworden ist; die Familie Oliva bleibt im Unternehmen aktiv.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('奥利瓦为这一配方带来的，是采购上的精准。厂里自有尼加拉瓜的种植园——哈拉帕与埃斯特利的地块供应整个目录。因此它可以从自家库存里挑出更轻、采得更早的叶子：这些叶子做不了V系列，却正好合乎中轻度配方的分寸。做出来的雪茄有真正的层次——奶油、烤谷物、香草、淡雪松——却没有那份会压垮晨间一支或夜里第一支的重量。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '奥利瓦为这一配方带来的，是采购上的精准。厂里自有尼加拉瓜的种植园——哈拉帕与埃斯特利的地块供应整个目录。因此它可以从自家库存里挑出更轻、采得更早的叶子：这些叶子做不了V系列，却正好合乎中轻度配方的分寸。做出来的雪茄有真正的层次——奶油、烤谷物、香草、淡雪松——却没有那份会压垮晨间一支或夜里第一支的重量。', 'Oliva 在埃斯特利的 Tabolisa I 卷制高端雪茄；据业内媒体2023年报道，这是该厂的主工厂。据 Wikipedia 所述，该厂在埃斯特利、孔德加、哈拉帕和索莫托自种烟草。自2016年夏天起，该厂隶属比利时公司 J. Cortès，该公司后来成为 Vandermarliere Family of Cigars；Oliva 家族仍在公司中活跃。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ما تضيفه أوليفا إلى هذه الوصفة يكمن في دقّة تدبير موادها. فالدار تملك مزارعها النيكاراغوية — قطع خالابا وإستيلي التي تغذّي الكتالوغ كلّه. وبإمكانها من ثمّ أن تنتقي من مخزونها الخاص أوراقًا أخفّ وأبكر جنيًا، لا تصلح للسلسلة V لكنها معايَرة تمامًا لخلطة متوسطة خفيفة. ويخرج من ذلك سيجار يقدّم تركيبًا حقيقيًا — قشدة، وحبوب محمّصة، وفانيليا، وأرز خفيف — دون الثقل الذي يسحق سيجار الصباح أو أوّل سيجار المساء.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ما تضيفه أوليفا إلى هذه الوصفة يكمن في دقّة تدبير موادها. فالدار تملك مزارعها النيكاراغوية — قطع خالابا وإستيلي التي تغذّي الكتالوغ كلّه. وبإمكانها من ثمّ أن تنتقي من مخزونها الخاص أوراقًا أخفّ وأبكر جنيًا، لا تصلح للسلسلة V لكنها معايَرة تمامًا لخلطة متوسطة خفيفة. ويخرج من ذلك سيجار يقدّم تركيبًا حقيقيًا — قشدة، وحبوب محمّصة، وفانيليا، وأرز خفيف — دون الثقل الذي يسحق سيجار الصباح أو أوّل سيجار المساء.', 'تلفّ Oliva سيجارها الفاخر في إستيلي، في Tabolisa I، وهي مصنع الدار الرئيسي بحسب صحافة المهنة عام 2023. وبحسب Wikipedia، تزرع الدار تبغها الخاص في إستيلي وكوندغا وخالابا وسوموتو. وتعود ملكية الدار منذ صيف 2016 إلى J. Cortès، شركة بلجيكية صارت Vandermarliere Family of Cigars؛ وما زالت عائلة Oliva فاعلة في الشركة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Connecticut Reserve';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La Connecticut Reserve a mis à mal l''idée qu''une maison nicaraguayenne ne saurait produire que de l''intensité. Elle a aussi fait connaître le nom d''Oliva à des fumeurs qui évitaient le catalogue entier sur la foi de sa réputation. La gamme a tenu sa ligne d''une boîte à l''autre, ce qui était précisément le pari.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La Connecticut Reserve a mis à mal l''idée qu''une maison nicaraguayenne ne saurait produire que de l''intensité. Elle a aussi fait connaître le nom d''Oliva à des fumeurs qui évitaient le catalogue entier sur la foi de sa réputation. La gamme a tenu sa ligne d''une boîte à l''autre, ce qui était précisément le pari.', 'Dans la famille Oliva, la ligne se distingue de la marque mère (fiche Oliva) et d''autres lignes de la maison comme Serie V ou Serie G, qui ont chacune leur propre blend.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Connecticut Reserve challenged the assumption that premium Nicaraguan houses could only produce intensity. It also introduced the Oliva name to a segment of smokers who had avoided the catalog entirely on the basis of its reputation. The range held its line from one box to the next, which is what the strategy was betting on.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Connecticut Reserve challenged the assumption that premium Nicaraguan houses could only produce intensity. It also introduced the Oliva name to a segment of smokers who had avoided the catalog entirely on the basis of its reputation. The range held its line from one box to the next, which is what the strategy was betting on.', 'Within the Oliva family, the line stands apart from the parent brand (see the Oliva entry) and from other lines of the house such as Serie V or Serie G, each of which has its own blend.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La Connecticut Reserve puso en apuros la idea de que una casa nicaragüense solo sabe producir intensidad. También dio a conocer el nombre de Oliva a fumadores que evitaban el catálogo entero por su reputación. La gama ha mantenido su línea de una caja a otra, que era precisamente la apuesta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La Connecticut Reserve puso en apuros la idea de que una casa nicaragüense solo sabe producir intensidad. También dio a conocer el nombre de Oliva a fumadores que evitaban el catálogo entero por su reputación. La gama ha mantenido su línea de una caja a otra, que era precisamente la apuesta.', 'Dentro de la familia Oliva, la línea se distingue de la marca madre (ficha Oliva) y de otras líneas de la casa como Serie V o Serie G, que tienen cada una su propia ligada.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Connecticut Reserve hat der Vorstellung zugesetzt, ein nicaraguanisches Haus könne nur Intensität hervorbringen. Sie hat den Namen Oliva auch Rauchern nahegebracht, die den ganzen Katalog wegen seines Rufs mieden. Die Linie hat ihre Handschrift von Kiste zu Kiste gehalten, und genau darum ging die Wette.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Connecticut Reserve hat der Vorstellung zugesetzt, ein nicaraguanisches Haus könne nur Intensität hervorbringen. Sie hat den Namen Oliva auch Rauchern nahegebracht, die den ganzen Katalog wegen seines Rufs mieden. Die Linie hat ihre Handschrift von Kiste zu Kiste gehalten, und genau darum ging die Wette.', 'Innerhalb der Familie Oliva unterscheidet sich die Linie von der Muttermarke (Eintrag Oliva) und von anderen Linien des Hauses wie Serie V oder Serie G, die jeweils eine eigene Mischung haben.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('康涅狄格珍藏动摇了「尼加拉瓜字号只会做浓烈」的成见，也让一些因这份名声而绕开整份目录的烟客记住了奥利瓦这个名字。这条线一箱接一箱地守住了自己的调性，而这正是当初下的赌注。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '康涅狄格珍藏动摇了「尼加拉瓜字号只会做浓烈」的成见，也让一些因这份名声而绕开整份目录的烟客记住了奥利瓦这个名字。这条线一箱接一箱地守住了自己的调性，而这正是当初下的赌注。', '在 Oliva 家族之中，这条线有别于母品牌（见 Oliva 条目）以及该厂的其他产品线，如 Serie V 或 Serie G，它们各有自己的配方。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('لقد زعزعت «كونيتيكت ريزيرف» الفكرة القائلة إنّ دارًا نيكاراغوية لا تُحسن سوى الشدّة. كما عرّفت باسم أوليفا مدخّنين كانوا يتجنّبون الكتالوغ كلّه بناءً على سمعته. وقد حافظت التشكيلة على خطّها من علبة إلى أخرى، وهو تحديدًا ما كان الرهان عليه.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'لقد زعزعت «كونيتيكت ريزيرف» الفكرة القائلة إنّ دارًا نيكاراغوية لا تُحسن سوى الشدّة. كما عرّفت باسم أوليفا مدخّنين كانوا يتجنّبون الكتالوغ كلّه بناءً على سمعته. وقد حافظت التشكيلة على خطّها من علبة إلى أخرى، وهو تحديدًا ما كان الرهان عليه.', 'ضمن عائلة Oliva، يتميّز هذا الخط عن العلامة الأم (انظر صفحة Oliva) وعن خطوط أخرى للدار مثل Serie V أو Serie G، ولكلٍّ منها خلطته الخاصة.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Connecticut Reserve';

UPDATE `brands` SET
  `country_id` = 'nicaragua',
  `factory` = 'Tabolisa I (Tabacalera Oliva), Estelí, Nicaragua (Oliva Cigar Co., groupe J. Cortès / Vandermarliere depuis 2016)',
  `gamme` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"Cape Connecticut d''Équateur, liant et tripe du Nicaragua, selon la page de la maison. Corps moyen selon la maison ; de doux à moyen selon Stogie Review (2009). Formats cités par Stogie Review en 2009 : Lonsdale, Robusto, Toro, Torpedo, Churchill ; la page de la maison montre aussi un Toro Tubo 6 x 50.","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"Connecticut d''Équateur"}]',
  `gamme_en` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"Ecuadorian Connecticut wrapper, Nicaraguan binder and filler, according to the house''s page. Medium body according to the house; mild to medium according to Stogie Review (2009). Formats cited by Stogie Review in 2009: Lonsdale, Robusto, Toro, Torpedo, Churchill; the house''s page also shows a Toro Tubo 6 x 50.","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"Ecuadorian Connecticut"}]',
  `gamme_es` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"Capa Connecticut de Ecuador, capote y tripa de Nicaragua, según la página de la casa. Cuerpo medio según la casa; de suave a medio según Stogie Review (2009). Formatos citados por Stogie Review en 2009: Lonsdale, Robusto, Toro, Torpedo, Churchill; la página de la casa muestra además un Toro Tubo 6 x 50.","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"Connecticut de Ecuador"}]',
  `gamme_de` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"Connecticut-Deckblatt aus Ecuador, Umblatt und Einlage aus Nicaragua, laut Seite des Hauses. Mittlerer Körper laut Haus; mild bis mittel laut Stogie Review (2009). Von Stogie Review 2009 genannte Formate: Lonsdale, Robusto, Toro, Torpedo, Churchill; die Seite des Hauses zeigt außerdem einen Toro Tubo 6 x 50.","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"Connecticut aus Ecuador"}]',
  `gamme_zh` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"厄瓜多尔 Connecticut 茄衣，茄套叶与茄芯来自尼加拉瓜，依据厂方页面。厂方称中等浓度；据 Stogie Review（2009年）为柔和至中度。Stogie Review 在2009年提到的规格：Lonsdale、Robusto、Toro、Torpedo、Churchill；厂方页面另展示一款 Toro Tubo 6 x 50。","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"厄瓜多尔 Connecticut"}]',
  `gamme_ar` = '[{"name":"Connecticut Reserve","color":"#C9A96E","force":"Medium","story":"غلاف Connecticut إكوادوري، وغلاف داخلي وحشوة من نيكاراغوا، بحسب صفحة الدار. جسم متوسط بحسب الدار؛ ومن لطيف إلى متوسط بحسب Stogie Review (2009). الأحجام التي ذكرتها Stogie Review عام 2009: Lonsdale وRobusto وToro وTorpedo وChurchill؛ وتعرض صفحة الدار أيضًا Toro Tubo 6 x 50.","vitolas":["Robusto","Toro","Churchill","Torpedo","Corona"],"wrapper":"Connecticut من الإكوادور"}]',
  `source` = IF(LOCATE(CAST('olivacigar.com et cigaraficionado.com — FICHE DE CAPE : Connecticut d''Équateur sur un cigare roulé par Oliva' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'olivacigar.com et cigaraficionado.com — FICHE DE CAPE : Connecticut d''Équateur sur un cigare roulé par Oliva', 'olivacigar.com « Connecticut Reserve - Mellow Anytime Cigar » (cape Équateur, liant et filler Nicaragua, corps moyen) ; stogiereview.com « Oliva Connecticut Reserve » (2009-02-28, mis à jour 2015-08-17 : nouvelle sortie, cape Connecticut équatorienne, Estelí, formats) ; cigaraficionado.com « A New Era of Oliva » (juillet/août 2023 : Tabolisa I, fabrique principale d''Estelí ; J. Cortès 2016 devenue Vandermarliere Family of Cigars) ; en.wikipedia.org « Oliva Cigar Co. » (fabrique d''Estelí, rachat J. Cortès à l''été 2016, fermes d''Estelí, Condega, Jalapa, Somoto)'), `source`),
  `updated_at` = NOW()
 WHERE `name` = 'Oliva Connecticut Reserve';

-- ── Perdomo Ecuador ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('L''histoire du Connecticut Shade compte deux chapitres. Le premier se déroule dans la vallée du Connecticut, où un sol sableux et une lumière diffuse produisent depuis plus de deux siècles la cape qui a fait la réputation du tabac américain. Le second — moins connu, et à certains égards plus intéressant — se joue en Équateur, où les planteurs ont compris dans les années 1990 que l''altitude quasi équatoriale et une couverture nuageuse constante pouvaient reproduire les conditions qui font la singularité du Connecticut Shade.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'L''histoire du Connecticut Shade compte deux chapitres. Le premier se déroule dans la vallée du Connecticut, où un sol sableux et une lumière diffuse produisent depuis plus de deux siècles la cape qui a fait la réputation du tabac américain. Le second — moins connu, et à certains égards plus intéressant — se joue en Équateur, où les planteurs ont compris dans les années 1990 que l''altitude quasi équatoriale et une couverture nuageuse constante pouvaient reproduire les conditions qui font la singularité du Connecticut Shade.', 'Perdomo est une maison familiale lancée en août 1992 à Miami par Nick Perdomo Jr. ; ses cigares sont roulés à Estelí, au Nicaragua, où une première installation date de 1997 et une usine sur mesure de 1999 (Wikipédia). Dès ses débuts, selon Wikipédia, elle associait des capes d''Équateur à des tripes d''Amérique centrale.'), `history`),
  `history_en` = IF(LOCATE(CAST('The Connecticut shade tobacco story has two chapters. The first is set in the Connecticut River Valley, where sandy soil and diffuse light have produced the wrapper leaf that made American tobacco''s reputation, for over two centuries. The second chapter — less familiar, and in some respects more interesting — is set in Ecuador, where farmers recognized in the 1990s that the country''s near-equatorial altitude and constant cloud cover could replicate the conditions that make Connecticut shade distinctive, and potentially improve on them.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Connecticut shade tobacco story has two chapters. The first is set in the Connecticut River Valley, where sandy soil and diffuse light have produced the wrapper leaf that made American tobacco''s reputation, for over two centuries. The second chapter — less familiar, and in some respects more interesting — is set in Ecuador, where farmers recognized in the 1990s that the country''s near-equatorial altitude and constant cloud cover could replicate the conditions that make Connecticut shade distinctive, and potentially improve on them.', 'Perdomo is a family house launched in August 1992 in Miami by Nick Perdomo Jr.; its cigars are rolled in Estelí, Nicaragua, where a first facility dates from 1997 and a purpose-built factory from 1999 (Wikipedia). From its beginnings, according to Wikipedia, it paired Ecuadorian wrappers with Central American fillers.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La historia del Connecticut Shade tiene dos capítulos. El primero transcurre en el valle del Connecticut, donde un suelo arenoso y una luz difusa producen desde hace más de dos siglos la capa que hizo la reputación del tabaco estadounidense. El segundo —menos conocido, y en ciertos aspectos más interesante— se juega en Ecuador, donde los plantadores comprendieron en los años noventa que la altitud casi ecuatorial y una cobertura de nubes constante podían reproducir las condiciones que hacen la singularidad del Connecticut Shade.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La historia del Connecticut Shade tiene dos capítulos. El primero transcurre en el valle del Connecticut, donde un suelo arenoso y una luz difusa producen desde hace más de dos siglos la capa que hizo la reputación del tabaco estadounidense. El segundo —menos conocido, y en ciertos aspectos más interesante— se juega en Ecuador, donde los plantadores comprendieron en los años noventa que la altitud casi ecuatorial y una cobertura de nubes constante podían reproducir las condiciones que hacen la singularidad del Connecticut Shade.', 'Perdomo es una casa familiar lanzada en agosto de 1992 en Miami por Nick Perdomo Jr.; sus puros se tuercen en Estelí, Nicaragua, donde una primera instalación data de 1997 y una fábrica a medida de 1999 (Wikipedia). Desde sus comienzos, según Wikipedia, combinaba capas de Ecuador con tripas de Centroamérica.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Geschichte des Connecticut Shade hat zwei Kapitel. Das erste spielt im Connecticut-Tal, wo ein sandiger Boden und ein gestreutes Licht seit mehr als zwei Jahrhunderten das Deckblatt hervorbringen, das den Ruf des amerikanischen Tabaks begründet hat. Das zweite — weniger bekannt und in mancher Hinsicht interessanter — spielt in Ecuador, wo die Pflanzer in den neunziger Jahren begriffen, dass die fast äquatoriale Höhenlage und eine gleichbleibende Wolkendecke jene Bedingungen nachbilden können, die das Connecticut Shade einzigartig machen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Geschichte des Connecticut Shade hat zwei Kapitel. Das erste spielt im Connecticut-Tal, wo ein sandiger Boden und ein gestreutes Licht seit mehr als zwei Jahrhunderten das Deckblatt hervorbringen, das den Ruf des amerikanischen Tabaks begründet hat. Das zweite — weniger bekannt und in mancher Hinsicht interessanter — spielt in Ecuador, wo die Pflanzer in den neunziger Jahren begriffen, dass die fast äquatoriale Höhenlage und eine gleichbleibende Wolkendecke jene Bedingungen nachbilden können, die das Connecticut Shade einzigartig machen.', 'Perdomo ist ein Familienhaus, das im August 1992 in Miami von Nick Perdomo Jr. ins Leben gerufen wurde; seine Zigarren werden in Estelí, Nicaragua, gerollt, wo eine erste Anlage aus dem Jahr 1997 und eine eigens errichtete Fabrik aus dem Jahr 1999 stammen (Wikipedia). Von Anfang an verband es laut Wikipedia Deckblätter aus Ecuador mit Einlagen aus Mittelamerika.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('康涅狄格阴植叶的历史有两章。第一章发生在康涅狄格河谷：那里的砂质土壤与散射光，两个多世纪以来出产着成就美国烟草声誉的茄衣。第二章鲜为人知，某种意义上却更有意思——它发生在厄瓜多尔。九十年代，那里的种植者发现，近赤道的高海拔与恒常的云层，能够复现出使康涅狄格阴植叶与众不同的那些条件。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '康涅狄格阴植叶的历史有两章。第一章发生在康涅狄格河谷：那里的砂质土壤与散射光，两个多世纪以来出产着成就美国烟草声誉的茄衣。第二章鲜为人知，某种意义上却更有意思——它发生在厄瓜多尔。九十年代，那里的种植者发现，近赤道的高海拔与恒常的云层，能够复现出使康涅狄格阴植叶与众不同的那些条件。', 'Perdomo 是一家家族字号，1992年8月由 Nick Perdomo Jr. 在迈阿密创办；其雪茄在尼加拉瓜的埃斯特利卷制，那里1997年有了初期设施，1999年有了量身定制的工厂（Wikipedia）。据 Wikipedia，它从创办之初就把厄瓜多尔茄衣与中美洲茄芯搭配在一起。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('لتاريخ كونيتيكت شيد فصلان. يجري الأول في وادي كونيتيكت، حيث تنتج تربة رملية وضوء منتشر، منذ أكثر من قرنين، الغلاف الذي صنع سمعة التبغ الأمريكي. أما الثاني — وهو أقلّ شهرة، وأطرف من بعض الوجوه — فيجري في الإكوادور، حيث أدرك المزارعون في التسعينيات أنّ الارتفاع شبه الاستوائي وغطاءً سحابيًّا ثابتًا يمكن أن يعيدا إنتاج الظروف التي تصنع تفرّد كونيتيكت شيد.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'لتاريخ كونيتيكت شيد فصلان. يجري الأول في وادي كونيتيكت، حيث تنتج تربة رملية وضوء منتشر، منذ أكثر من قرنين، الغلاف الذي صنع سمعة التبغ الأمريكي. أما الثاني — وهو أقلّ شهرة، وأطرف من بعض الوجوه — فيجري في الإكوادور، حيث أدرك المزارعون في التسعينيات أنّ الارتفاع شبه الاستوائي وغطاءً سحابيًّا ثابتًا يمكن أن يعيدا إنتاج الظروف التي تصنع تفرّد كونيتيكت شيد.', 'Perdomo دار عائلية أُطلقت في أغسطس 1992 في ميامي على يد Nick Perdomo Jr.؛ وتُلفّ سيجارها في إستيلي بنيكاراغوا، حيث يعود تاريخ منشأة أولى إلى عام 1997 ومصنع مصمَّم خصيصًا إلى عام 1999 (Wikipedia). ومنذ بداياتها، بحسب Wikipedia، كانت تجمع أغلفة من الإكوادور بحشوات من أمريكا الوسطى.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo Ecuador';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le Connecticut Shade équatorien pousse à des altitudes où l''air plus rare et la diffusion régulière des nuages créent naturellement ce que les planteurs du Connecticut doivent obtenir à l''aide d''ombrières. Il en sort une feuille qui garde l''onctuosité propre au Connecticut, avec une complexité supplémentaire tirée des sols volcaniques et du microclimat des Andes. Plusieurs grandes maisons — Davidoff au premier rang — s''approvisionnent aujourd''hui en Équateur plutôt que dans le Connecticut.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le Connecticut Shade équatorien pousse à des altitudes où l''air plus rare et la diffusion régulière des nuages créent naturellement ce que les planteurs du Connecticut doivent obtenir à l''aide d''ombrières. Il en sort une feuille qui garde l''onctuosité propre au Connecticut, avec une complexité supplémentaire tirée des sols volcaniques et du microclimat des Andes. Plusieurs grandes maisons — Davidoff au premier rang — s''approvisionnent aujourd''hui en Équateur plutôt que dans le Connecticut.', 'Le classement suit le pays de roulage, le Nicaragua. La cape, elle, vient d''Équateur : une graine du Connecticut cultivée sans ombrière dans le climat côtier, surtout dans la région de Los Ríos, puis expédiée au Nicaragua pour l''assemblage (eldiario.ec, 9 juillet 2025). Sur la page de la maison (perdomocigars.com, octobre 2026), la ligne Legacy Ecuadorian Connecticut associe une cape Ecuadorian Connecticut, un liant Nicaraguan Shade Grown et une tripe nicaraguayenne de graine cubaine, avec des tabacs cultivés à Estelí, Condega et dans la vallée de Jalapa. Aucune ligne nommée « Ecuador » ne figure sur le site de la maison en octobre 2026.'), `history`),
  `history_en` = IF(LOCATE(CAST('Ecuadorian Connecticut shade grows at elevations where thinner air and consistent cloud diffusion create natural growing conditions analogous to the shade tents that Connecticut farmers must construct artificially. The result is a leaf with the signature Connecticut creaminess, but with additional complexity derived from volcanic soils and the specific microclimate of the Ecuadorian Andes. Several major manufacturers — Davidoff prominently among them — now source their Connecticut-style wrappers from Ecuador rather than Connecticut itself.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Ecuadorian Connecticut shade grows at elevations where thinner air and consistent cloud diffusion create natural growing conditions analogous to the shade tents that Connecticut farmers must construct artificially. The result is a leaf with the signature Connecticut creaminess, but with additional complexity derived from volcanic soils and the specific microclimate of the Ecuadorian Andes. Several major manufacturers — Davidoff prominently among them — now source their Connecticut-style wrappers from Ecuador rather than Connecticut itself.', 'The classification follows the country of rolling, Nicaragua. The wrapper, for its part, comes from Ecuador: Connecticut seed grown without shade cloth in the coastal climate, chiefly in the Los Ríos region, then shipped to Nicaragua for blending (eldiario.ec, 9 July 2025). On the house''s page (perdomocigars.com, October 2026), the Legacy Ecuadorian Connecticut line pairs an Ecuadorian Connecticut wrapper, a Nicaraguan Shade Grown binder and a Nicaraguan filler of Cuban seed, with tobaccos grown in Estelí, Condega and the Jalapa valley. No line named "Ecuador" appears on the house''s website in October 2026.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El Connecticut Shade ecuatoriano crece a altitudes donde el aire más ligero y la difusión regular de las nubes crean de forma natural lo que los plantadores del Connecticut deben obtener con toldos de sombra. De ahí sale una hoja que conserva la untuosidad propia del Connecticut, con una complejidad añadida que le dan los suelos volcánicos y el microclima de los Andes. Varias casas grandes —Davidoff en primer lugar— se abastecen hoy en Ecuador antes que en el Connecticut.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Connecticut Shade ecuatoriano crece a altitudes donde el aire más ligero y la difusión regular de las nubes crean de forma natural lo que los plantadores del Connecticut deben obtener con toldos de sombra. De ahí sale una hoja que conserva la untuosidad propia del Connecticut, con una complejidad añadida que le dan los suelos volcánicos y el microclima de los Andes. Varias casas grandes —Davidoff en primer lugar— se abastecen hoy en Ecuador antes que en el Connecticut.', 'La clasificación sigue el país de torcido, Nicaragua. La capa, en cambio, viene de Ecuador: una semilla del Connecticut cultivada sin toldo en el clima costero, sobre todo en la región de Los Ríos, y luego enviada a Nicaragua para la ligada (eldiario.ec, 9 de julio de 2025). En la página de la casa (perdomocigars.com, octubre de 2026), la línea Legacy Ecuadorian Connecticut combina una capa Ecuadorian Connecticut, un capote Nicaraguan Shade Grown y una tripa nicaragüense de semilla cubana, con tabacos cultivados en Estelí, Condega y el valle de Jalapa. Ninguna línea llamada «Ecuador» figura en el sitio de la casa en octubre de 2026.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das ecuadorianische Connecticut Shade wächst in Höhen, in denen die dünnere Luft und die gleichmäßige Streuung der Wolken von selbst schaffen, was die Pflanzer in Connecticut mit Schattentüchern herstellen müssen. Daraus entsteht ein Blatt, das die für Connecticut typische Cremigkeit behält, mit einer zusätzlichen Vielschichtigkeit aus den vulkanischen Böden und dem Kleinklima der Anden. Mehrere große Häuser — Davidoff an erster Stelle — beziehen ihre Blätter heute eher aus Ecuador als aus Connecticut.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das ecuadorianische Connecticut Shade wächst in Höhen, in denen die dünnere Luft und die gleichmäßige Streuung der Wolken von selbst schaffen, was die Pflanzer in Connecticut mit Schattentüchern herstellen müssen. Daraus entsteht ein Blatt, das die für Connecticut typische Cremigkeit behält, mit einer zusätzlichen Vielschichtigkeit aus den vulkanischen Böden und dem Kleinklima der Anden. Mehrere große Häuser — Davidoff an erster Stelle — beziehen ihre Blätter heute eher aus Ecuador als aus Connecticut.', 'Die Einordnung folgt dem Land des Rollens, Nicaragua. Das Deckblatt dagegen stammt aus Ecuador: Connecticut-Saatgut, ohne Schattentuch im Küstenklima angebaut, vor allem in der Region Los Ríos, dann zur Mischung nach Nicaragua verschifft (eldiario.ec, 9. Juli 2025). Auf der Seite des Hauses (perdomocigars.com, Oktober 2026) verbindet die Linie Legacy Ecuadorian Connecticut ein Deckblatt Ecuadorian Connecticut, ein Umblatt Nicaraguan Shade Grown und eine nicaraguanische Einlage aus kubanischem Saatgut, mit Tabaken aus Estelí, Condega und dem Jalapa-Tal. Eine Linie namens „Ecuador“ steht im Oktober 2026 nicht auf der Seite des Hauses.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('厄瓜多尔的康涅狄格阴植叶长在高处：稀薄的空气与云层均匀的散射，天然造就了康涅狄格种植者必须靠遮阴布才能得到的环境。由此长出的叶子保留了康涅狄格特有的顺滑，又从火山土壤与安第斯的小气候里多得一层复杂。如今好几家大字号——大卫杜夫居首——的进货地已是厄瓜多尔而非康涅狄格。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '厄瓜多尔的康涅狄格阴植叶长在高处：稀薄的空气与云层均匀的散射，天然造就了康涅狄格种植者必须靠遮阴布才能得到的环境。由此长出的叶子保留了康涅狄格特有的顺滑，又从火山土壤与安第斯的小气候里多得一层复杂。如今好几家大字号——大卫杜夫居首——的进货地已是厄瓜多尔而非康涅狄格。', '归类依据卷制国家，即尼加拉瓜。而茄衣来自厄瓜多尔：康涅狄格种子，在沿海气候中不搭遮阴棚栽种，主要集中在 Los Ríos 地区，随后运往尼加拉瓜进行配方（eldiario.ec，2025年7月9日）。在厂方页面（perdomocigars.com，2026年10月）上，Legacy Ecuadorian Connecticut 系列将 Ecuadorian Connecticut 茄衣、Nicaraguan Shade Grown 茄套叶与古巴种子的尼加拉瓜茄芯搭配，烟草种于埃斯特利、孔德加和哈拉帕山谷。2026年10月，厂方网站上没有名为「Ecuador」的产品线。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ينمو كونيتيكت شيد الإكوادوري على ارتفاعات يخلق فيها الهواء الأرقّ وانتشار السحب المنتظم، بشكل طبيعي، ما على مزارعي كونيتيكت أن يحصّلوه بأقمشة التظليل. ومن ذلك تخرج ورقة تحتفظ بالنعومة الدسمة الخاصة بكونيتيكت، مع تركيب إضافي تمنحه التربة البركانية ومناخ الأنديز الصغير. وعدة دور كبرى — دافيدوف في مقدّمتها — تتزوّد اليوم من الإكوادور لا من كونيتيكت.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ينمو كونيتيكت شيد الإكوادوري على ارتفاعات يخلق فيها الهواء الأرقّ وانتشار السحب المنتظم، بشكل طبيعي، ما على مزارعي كونيتيكت أن يحصّلوه بأقمشة التظليل. ومن ذلك تخرج ورقة تحتفظ بالنعومة الدسمة الخاصة بكونيتيكت، مع تركيب إضافي تمنحه التربة البركانية ومناخ الأنديز الصغير. وعدة دور كبرى — دافيدوف في مقدّمتها — تتزوّد اليوم من الإكوادور لا من كونيتيكت.', 'يتبع التصنيف بلد اللفّ، أي نيكاراغوا. أما الغلاف فمن الإكوادور: بذرة كونيتيكت تُزرع بلا مظلّات تظليل في المناخ الساحلي، ولا سيما في منطقة Los Ríos، ثم تُشحن إلى نيكاراغوا للخلط (eldiario.ec، 9 يوليو 2025). وفي صفحة الدار (perdomocigars.com، أكتوبر 2026) يجمع خط Legacy Ecuadorian Connecticut غلافًا Ecuadorian Connecticut وغلافًا داخليًا Nicaraguan Shade Grown وحشوة نيكاراغوية من بذرة كوبية، مع تبغ مزروع في إستيلي وكوندغا ووادي خالابا. ولا يظهر أي خط باسم «Ecuador» على موقع الدار في أكتوبر 2026.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Perdomo Ecuador';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La gamme Ecuador de Perdomo bâtit toute sa proposition sur ce choix d''approvisionnement. La cape, issue de cette culture d''altitude, apporte à l''assemblage une texture plus soyeuse et une teneur en huiles plus marquée que le Connecticut Shade courant. Dessous, une tripe nicaraguayenne de Jalapa — plus légère que celle du Perdomo 20th Anniversary, calibrée pour laisser la cape mener — donne des notes de crème, de vanille douce et de céréales grillées, sans le poids qui écraserait la délicatesse de l''Ecuador.

' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La gamme Ecuador de Perdomo bâtit toute sa proposition sur ce choix d''approvisionnement. La cape, issue de cette culture d''altitude, apporte à l''assemblage une texture plus soyeuse et une teneur en huiles plus marquée que le Connecticut Shade courant. Dessous, une tripe nicaraguayenne de Jalapa — plus légère que celle du Perdomo 20th Anniversary, calibrée pour laisser la cape mener — donne des notes de crème, de vanille douce et de céréales grillées, sans le poids qui écraserait la délicatesse de l''Ecuador.

