  `gamme` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"Ligne de la maison (perdomocigars.com, octobre 2026) : cape Ecuadorian Connecticut vieillie dix ans et passée au moins huit mois en barrique de bourbon, liant Nicaraguan Shade Grown, tripe nicaraguayenne de graine cubaine ; force Medium selon la maison. Formats : Robusto 5x54, Epicure 6x54, Gran Belicoso 6x60, Gordo 6x60, Churchill 7x54.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut d''Équateur"}]',
  `gamme_en` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"The house''s line (perdomocigars.com, October 2026): Ecuadorian Connecticut wrapper aged ten years and spent at least eight months in a bourbon barrel, Nicaraguan Shade Grown binder, Nicaraguan filler of Cuban seed; Medium strength according to the house. Formats: Robusto 5x54, Epicure 6x54, Gran Belicoso 6x60, Gordo 6x60, Churchill 7x54.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Ecuadorian Connecticut"}]',
  `gamme_es` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"Línea de la casa (perdomocigars.com, octubre de 2026): capa Ecuadorian Connecticut envejecida diez años y pasada al menos ocho meses en barrica de bourbon, capote Nicaraguan Shade Grown, tripa nicaragüense de semilla cubana; fuerza Medium según la casa. Formatos: Robusto 5x54, Epicure 6x54, Gran Belicoso 6x60, Gordo 6x60, Churchill 7x54.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut de Ecuador"}]',
  `gamme_de` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"Linie des Hauses (perdomocigars.com, Oktober 2026): Deckblatt Ecuadorian Connecticut, zehn Jahre gereift und mindestens acht Monate im Bourbonfass verbracht, Umblatt Nicaraguan Shade Grown, nicaraguanische Einlage aus kubanischem Saatgut; Stärke Medium laut Haus. Formate: Robusto 5x54, Epicure 6x54, Gran Belicoso 6x60, Gordo 6x60, Churchill 7x54.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut aus Ecuador"}]',
  `gamme_zh` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"厂方产品线（perdomocigars.com，2026年10月）：Ecuadorian Connecticut 茄衣陈放十年，并在波本桶中至少放置八个月，茄套叶为 Nicaraguan Shade Grown，茄芯为古巴种子的尼加拉瓜烟草；据厂方，劲道为 Medium。规格：Robusto 5x54、Epicure 6x54、Gran Belicoso 6x60、Gordo 6x60、Churchill 7x54。","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"厄瓜多尔 Connecticut"}]',
  `gamme_ar` = '[{"name":"Perdomo Legacy Ecuadorian Connecticut","color":"#C9A96E","force":"Medium","story":"خط الدار (perdomocigars.com، أكتوبر 2026): غلاف Ecuadorian Connecticut معتّق عشر سنوات ومرّ ثمانية شهور على الأقل في برميل بوربون، وغلاف داخلي Nicaraguan Shade Grown، وحشوة نيكاراغوية من بذرة كوبية؛ والقوة Medium بحسب الدار. الأحجام: Robusto 5x54 وEpicure 6x54 وGran Belicoso 6x60 وGordo 6x60 وChurchill 7x54.","vitolas":["Robusto","Toro","Churchill","Torpedo"],"wrapper":"Connecticut من الإكوادور"}]',
