-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Arturo Fuente Hemingway' AS hote, 'fr' AS lang, 'pays' AS quoi, (CAST(`country_id` AS BINARY) = CAST('dominican' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'founded', (CAST(`founded` AS BINARY) = CAST('1981 (frise) ; 1983 (dossier de presse)' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabacalera A. Fuente y Cía, Santiago, République dominicaine (ouverte en 1980 selon arturofuente.com)' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Hemingway est une ligne d''Arturo Fuente roulée à la main à la Tabacalera A. Fuente y Cía, à Santiago, en République dominicaine, usine que la maison dit ouverte en 1980. Sa date de sortie diverge : 1981 selon la frise de la maison (arturofuente.com), 1983 selon le dossier de presse de la maison et la presse du métier.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ernest Hemingway et le tabac cubain ont occupé le même monde pendant l''essentiel de la vie adulte de l''écrivain. Il a vécu à Cuba de 1939 à 1960 — la plus longue période qu''il ait passée au même endroit — et sa finca, aux portes de La Havane, fut le centre de son travail littéraire et de ses expéditions de pêche. L''homme qui écrivit Le Vieil Homme et la Mer le fit dans un pays où le tabac était à la fois une industrie et un rituel, et où les plantations se trouvaient à une heure de route de son bureau.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The Hemingway is an Arturo Fuente line hand-rolled at the Tabacalera A. Fuente y Cía, in Santiago, in the Dominican Republic, a factory the house says opened in 1980. Its release date is given differently: 1981 according to the house timeline (arturofuente.com), 1983 according to the house press kit and the trade press.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ernest Hemingway and Cuban tobacco occupied the same world for most of the writer''s adult life. He lived in Cuba from 1939 to 1960 — the longest continuous period he spent anywhere — and his finca outside Havana became the center of his literary production, his fishing expeditions, and his cigar habit. The man who wrote The Old Man and the Sea did so in a country where tobacco was both industry and ritual, where the best cigars on earth were grown an hour''s drive from his desk.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Hemingway es una línea de Arturo Fuente liada a mano en la Tabacalera A. Fuente y Cía, en Santiago, en República Dominicana, fábrica que la casa dice abierta en 1980. Su fecha de salida diverge: 1981 según la cronología de la casa (arturofuente.com), 1983 según el dossier de prensa de la casa y la prensa del sector.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ernest Hemingway y el tabaco cubano ocuparon el mismo mundo durante la mayor parte de la vida adulta del escritor. Vivió en Cuba de 1939 a 1960 —el periodo más largo que pasó en un mismo sitio— y su finca, a las puertas de La Habana, fue el centro de su trabajo literario y de sus expediciones de pesca. El hombre que escribió El viejo y el mar lo hizo en un país donde el tabaco era a la vez una industria y un rito, y donde las plantaciones quedaban a una hora de coche de su despacho.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Hemingway ist eine von Hand gerollte Linie von Arturo Fuente, hergestellt in der Tabacalera A. Fuente y Cía in Santiago in der Dominikanischen Republik, einer Fabrik, die nach Angabe des Hauses 1980 eröffnet wurde. Ihr Erscheinungsdatum weicht ab: 1981 laut der Zeittafel des Hauses (arturofuente.com), 1983 laut dem Pressedossier des Hauses und der Fachpresse.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Ernest Hemingway und der kubanische Tabak bewohnten dieselbe Welt, den größten Teil des Erwachsenenlebens des Schriftstellers hindurch. Er lebte von 1939 bis 1960 auf Kuba — die längste Zeit, die er an einem Ort verbrachte — und seine Finca vor den Toren Havannas war das Zentrum seiner literarischen Arbeit und seiner Fischzüge. Der Mann, der Der alte Mann und das Meer schrieb, tat es in einem Land, in dem Tabak zugleich Industrie und Ritual war und die Plantagen eine Autostunde von seinem Schreibtisch entfernt lagen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Hemingway 是 Arturo Fuente 旗下的一条手工卷制产品线，在多米尼加共和国圣地亚哥的 Tabacalera A. Fuente y Cía 卷制，该厂据厂家称于1980年开业。其推出年份说法不一：厂家年表（arturofuente.com）称1981年，厂家新闻资料和行业媒体称1983年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('在这位作家成年后的大半生里，欧内斯特·海明威与古巴烟草共处同一个世界。他1939年至1960年住在古巴——那是他在同一个地方待得最久的一段——哈瓦那城外的农庄是他文学工作与出海捕鱼的中心。写下《老人与海》的人，是在一个烟草既是产业又是仪式的国家里写的，而烟田离他的书桌只有一小时车程。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('خط Hemingway هو خط من Arturo Fuente يُلفّ يدويًا في Tabacalera A. Fuente y Cía في سانتياغو بالجمهورية الدومينيكية، وهو مصنع تقول الدار إنه افتُتح عام 1980. وتاريخ صدوره مختلف عليه: 1981 بحسب الجدول الزمني للدار (arturofuente.com)، و1983 بحسب الملف الصحفي للدار والصحافة المتخصصة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('عاش إرنست همنغواي والتبغ الكوبي في العالم نفسه طوال معظم حياة الكاتب الراشدة. أقام في كوبا من 1939 إلى 1960 — أطول مدة قضاها في مكان واحد — وكانت مزرعته على مشارف هافانا مركز عمله الأدبي ورحلات صيده. فالرجل الذي كتب «الشيخ والبحر» كتبه في بلد كان التبغ فيه صناعة وطقسًا معًا، وكانت المزارع على بُعد ساعة بالسيارة من مكتبه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La ligne se reconnaît à ses figurados (formats effilés), un art que le dossier de presse de la maison dit perdu depuis Cuba. Selon son dossier de presse, Carlito Fuente retrouva les moules dans l''entrepôt de Ybor City et Carlos Fuente forma un maître rouleur, qui transmit le geste au reste de l''équipe.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''hommage d''Arturo Fuente à cette relation repose sur un format que Hemingway n''a jamais fumé, mais qui incarne le métier qu''il aurait su reconnaître : le Perfecto. Effilé aux deux bouts — tête et pied —, c''est un format que peu de manufactures roulent en série. Rouler un parejo classique est déjà difficile ; un Perfecto demande au torcedor de tenir une symétrie parfaite sur deux extrémités qui s''affinent, tout en maintenant une densité constante d''un bout à l''autre. Le tirage doit rester facile malgré le diamètre variable, la combustion régulière malgré la complexité de la structure. Celle d''Arturo Fuente, en République dominicaine, le fait couramment.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The line is recognised by its figurados (tapered shapes), an art that the house press kit says was lost since Cuba. According to its press kit, Carlito Fuente found the moulds again in the Ybor City warehouse and Carlos Fuente trained a master roller, who passed the skill on to the rest of the team.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Arturo Fuente''s tribute to this relationship is built around a format that Hemingway never actually smoked but that embodies the craftsmanship he would have appreciated: the Perfecto. A cigar tapered at both ends — head and foot — the Perfecto is the most technically demanding format in cigar production. Rolling a conventional parejo is difficult enough; rolling a Perfecto requires the torcedor to maintain perfect symmetry across two tapering ends while achieving consistent density throughout. The draw must remain effortless despite the varying ring gauge. The burn must be even despite the structural complexity. Most factories do not attempt it at scale. The Arturo Fuente factory in the Dominican Republic does it routinely.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La línea se reconoce por sus figurados (formatos afilados), un arte que el dossier de prensa de la casa da por perdido desde Cuba. Según su dossier de prensa, Carlito Fuente encontró de nuevo los moldes en el almacén de Ybor City y Carlos Fuente formó a un torcedor maestro, que transmitió el gesto al resto del equipo.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El homenaje de Arturo Fuente a esa relación descansa en un formato que Hemingway nunca fumó, pero que encarna el oficio que habría sabido reconocer: el Perfecto. Afilado por los dos extremos —cabeza y pie—, es un formato que pocas manufacturas lían en serie. Liar un parejo clásico ya es difícil; un Perfecto exige al torcedor sostener una simetría perfecta en dos extremos que se afinan, manteniendo a la vez una densidad constante de punta a punta. El tiro debe seguir siendo fácil pese al diámetro variable, la combustión regular pese a la complejidad de la estructura. La de Arturo Fuente, en República Dominicana, lo hace de forma corriente.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Linie erkennt man an ihren Figurados (zugespitzten Formaten), einer Kunst, die laut Pressedossier des Hauses seit Kuba verloren war. Laut seinem Pressedossier fand Carlito Fuente die Formen im Lager von Ybor City wieder, und Carlos Fuente bildete einen Meisterroller aus, der den Handgriff an das übrige Team weitergab.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Die Hommage von Arturo Fuente an diese Beziehung ruht auf einem Format, das Hemingway nie geraucht hat, das aber das Handwerk verkörpert, das er erkannt hätte: das Perfecto. An beiden Enden zulaufend — Kopf und Fuß —, ist es ein Format, das wenige Manufakturen in Serie rollen. Ein klassisches Parejo zu rollen ist schon schwer; ein Perfecto verlangt vom Torcedor, an zwei sich verjüngenden Enden vollkommene Symmetrie zu halten und zugleich die Dichte von einem Ende zum anderen gleich zu führen. Der Zug muss trotz wechselnden Durchmessers leicht bleiben, der Abbrand trotz der aufwendigen Bauweise gleichmäßig. Die Manufaktur von Arturo Fuente in der Dominikanischen Republik tut das regelmäßig.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('这条线以 figurados（锥形规格）著称，厂家的新闻资料称这门手艺自古巴之后便已失传。据其新闻资料，Carlito Fuente 在 Ybor City 的仓库里重新找到了模具，Carlos Fuente 培养了一位卷制大师，由他把这手艺传给团队其他人。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('阿图罗·富恩特向这段关系致敬的方式，落在一个海明威从未抽过、却体现了他会认得的手艺的规格上：Perfecto。两端都收尖——头与脚——这是很少有工厂成批卷制的形状。卷一支普通的直筒已经不易；Perfecto 要求卷制师在两个渐收的端头上保持完全对称，同时让密度从头到尾一致。口径在变，通气却要始终顺畅；结构复杂，燃烧却要均匀。阿图罗·富恩特在多米尼加共和国的厂子，日常就做到这一点。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يُعرف الخط بطرازاته المدبّبة (figurados)، وهي حرفة يقول الملف الصحفي للدار إنها ضاعت منذ كوبا. وبحسب ملفه الصحفي، وجد Carlito Fuente القوالب من جديد في مستودع Ybor City، ودرّب Carlos Fuente لافًّا ماهرًا نقل الحرفة إلى بقية الفريق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('تقوم تحية أرتورو فوينتي لهذه العلاقة على قياس لم يدخّنه همنغواي قط، لكنه يجسّد الحرفة التي كان سيعرفها: البِرفكتو. مدبَّب من طرفيه — الرأس والقدم — وهو قياس قلّما تلفّه المصانع في سلاسل. لفّ سيجار مستقيم كلاسيكي صعب أصلًا؛ أما البِرفكتو فيطلب من اللافّ تناظرًا تامًّا على طرفين يدقّان، مع كثافة ثابتة من أوله إلى آخره. يجب أن يبقى السحب سهلًا رغم تغيّر القطر، والاحتراق منتظمًا رغم تعقيد البناء. ومصنع أرتورو فوينتي في الجمهورية الدومينيكية يفعل ذلك بانتظام.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Pour la Work of Art, la Short Story et la Classic, la presse du métier donne une cape du Cameroun sur une liaison et une tripe dominicaines, en force moyenne à moyenne-forte selon la taille (état lu en octobre 2026). Le classement du site suit le pays de roulage, la République dominicaine ; le Cameroun est l''origine de la cape.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La cape est camerounaise — un choix cohérent avec les ambitions de complexité de la gamme. La feuille du Cameroun sur un assemblage dominicain donne un profil d''une finesse inhabituelle : noix de cajou et crème sur le premier tiers, puis café léger et cèdre, vers une finale de poivre doux et de miel. La force moyenne rend la gamme abordable sans sacrifier la complexité qui justifie le nom de Hemingway.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('For the Work of Art, the Short Story and the Classic, the trade press gives a Cameroon wrapper over a Dominican binder and filler, in medium to medium-full strength depending on the size (as read in October 2026). The site''s classification follows the country of rolling, the Dominican Republic; Cameroon is the origin of the wrapper.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The wrapper is Cameroon — a natural choice given the range''s complexity ambitions. Cameroonian leaf over a Dominican blend creates a profile of unusual refinement: cashew and cream on the first third, developing through light coffee and cedar toward a finish of mild pepper and honey. The medium-body strength makes the range accessible without sacrificing the complexity that justifies the Hemingway name.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Para la Work of Art, la Short Story y la Classic, la prensa del sector da una capa de Camerún sobre un capote y una tripa dominicanos, de fuerza media a media-fuerte según la vitola (estado leído en octubre de 2026). La clasificación del sitio sigue el país de liado, República Dominicana; Camerún es el origen de la capa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La capa es camerunesa —una elección coherente con las ambiciones de complejidad de la gama. La hoja de Camerún sobre una ligada dominicana da un perfil de una finura inhabitual: anacardo y crema en el primer tercio, después café ligero y cedro, hacia un final de pimienta suave y miel. La fuerza media hace la gama asequible sin sacrificar la complejidad que justifica el nombre de Hemingway.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Für die Work of Art, die Short Story und die Classic nennt die Fachpresse ein Deckblatt aus Kamerun auf dominikanischem Umblatt und dominikanischer Einlage, in mittlerer bis mittelkräftiger Stärke je nach Format (Stand: Oktober 2026). Die Einordnung der Seite folgt dem Land der Fertigung, der Dominikanischen Republik; Kamerun ist die Herkunft des Deckblatts.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
UNION ALL SELECT 'Arturo Fuente Hemingway', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Das Deckblatt ist kamerunisch — eine Wahl, die zu den Ansprüchen der Linie an Vielschichtigkeit passt. Das Blatt aus Kamerun auf einer dominikanischen Mischung ergibt ein ungewöhnlich feines Profil: Cashew und Sahne im ersten Drittel, dann leichter Kaffee und Zeder, hin zu einem Abgang aus milder Pfefferschärfe und Honig. Die mittlere Stärke macht die Linie zugänglich, ohne die Vielschichtigkeit zu opfern, die den Namen Hemingway rechtfertigt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Hemingway'
