UNION ALL SELECT 'Arturo Fuente Maduro', 'fr', 'pays', (CAST(`country_id` AS BINARY) = CAST('dominican' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabacalera A. Fuente, République dominicaine' AS BINARY)) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro est la déclinaison à cape maduro de la gamme principale d''Arturo Fuente, roulée en République dominicaine. Selon la presse du métier (fiche du Churchill Maduro, octobre 2017), la cape est du Connecticut broadleaf des États-Unis, sur liaison et tripe dominicaines ; un détaillant (Neptune Cigar, octobre 2026) décrit le même assemblage. La cape maduro Fuente n''a pas toujours eu cette origine : une fiche de la même presse de 2001 donne une cape du Cameroun pour le Rothschild Maduro. Le récit antérieur d''une cape brésilienne (Bahia, Arapiraca) n''a pas de page derrière lui et est retiré. Le Churchill Maduro mesure 7 ¼ pouces pour 48 de cordage (même fiche). La force est donnée comme medium par un détaillant et comme medium-full par d''autres (octobre 2026). La page de la maison sur ses cigares à tripe courte (Medium Filler) montre des minis en natural et en maduro, sans cape brésilienne (octobre 2026). Aucune page de la maison lue n''établit les autres formats de la ligne.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La cape maduro est la transformation la plus radicale que subisse le tabac. Une feuille déjà retenue pour sa finesse, sa couleur régulière et sa tenue passe par une fermentation prolongée — des mois, parfois des années — qui convertit ses sucres naturels, sous chaleur et humidité contrôlées, en composés complexes. La feuille fonce du brun au presque noir. Sa surface devient huileuse. Et elle acquiert une douceur naturelle — ni ajoutée ni artificielle, mais produite par cette transformation cellulaire prolongée — qui change en profondeur le caractère de tout cigare qu''elle enveloppe.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro is the maduro-wrapper version of Arturo Fuente''s main range, rolled in the Dominican Republic. According to the trade press (Churchill Maduro entry, October 2017), the wrapper is Connecticut broadleaf from the United States, over a Dominican binder and filler; a retailer (Neptune Cigar, October 2026) describes the same blend. The Fuente maduro wrapper has not always had this origin: an entry from the same press in 2001 gives a Cameroon wrapper for the Rothschild Maduro. The earlier account of a Brazilian wrapper (Bahia, Arapiraca) has no page behind it and is withdrawn. The Churchill Maduro measures 7 ¼ inches with a ring gauge of 48 (same entry). The strength is given as medium by one retailer and as medium-full by others (October 2026). The house page on its cigars with a short filler (Medium Filler) shows minis in natural and in maduro, with no Brazilian wrapper (October 2026). None of the house pages read establishes the other sizes in the line.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Maduro wrapper is tobacco''s most radical transformation. A wrapper leaf already selected for thinness, even color, and structural integrity is then subjected to extended fermentation — sometimes months, sometimes years — that converts its natural sugars through controlled heat and humidity into a range of complex compounds. The leaf darkens from brown to near-black. It develops an oily surface texture. And it acquires a natural sweetness — not added, not artificial, but the biochemical product of prolonged cellular transformation — that fundamentally changes the character of any cigar it wraps.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro es la versión con capa maduro de la gama principal de Arturo Fuente, liada en República Dominicana. Según la prensa del sector (ficha del Churchill Maduro, octubre de 2017), la capa es Connecticut broadleaf de Estados Unidos, sobre capote y tripa dominicanos; un minorista (Neptune Cigar, octubre de 2026) describe la misma ligada. La capa maduro de Fuente no siempre tuvo este origen: una ficha de la misma prensa de 2001 da una capa de Camerún para el Rothschild Maduro. El relato anterior de una capa brasileña (Bahía, Arapiraca) no tiene ninguna página que lo respalde y se retira. El Churchill Maduro mide 7 ¼ pulgadas con cepo 48 (misma ficha). La fuerza se da como media por un minorista y como media-plena por otros (octubre de 2026). La página de la casa sobre sus puros de tripa corta (Medium Filler) muestra minis en natural y en maduro, sin capa brasileña (octubre de 2026). Ninguna página de la casa leída establece los demás formatos de la línea.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La capa maduro es la transformación más radical que sufre el tabaco. Una hoja ya retenida por su finura, su color regular y su tenida pasa por una fermentación prolongada —meses, a veces años— que convierte sus azúcares naturales, bajo calor y humedad controlados, en compuestos complejos. La hoja oscurece del marrón al casi negro. Su superficie se vuelve aceitosa. Y adquiere una dulzura natural —ni añadida ni artificial, sino producida por esa transformación celular prolongada— que cambia en profundidad el carácter de todo puro que envuelve.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro ist die Ausführung mit Maduro-Deckblatt der Hauptlinie von Arturo Fuente, gerollt in der Dominikanischen Republik. Laut der Fachpresse (Eintrag zur Churchill Maduro, Oktober 2017) ist das Deckblatt Connecticut Broadleaf aus den Vereinigten Staaten, auf dominikanischem Umblatt und dominikanischer Einlage; ein Einzelhändler (Neptune Cigar, Oktober 2026) beschreibt dieselbe Zusammenstellung. Das Maduro-Deckblatt von Fuente hatte nicht immer diese Herkunft: Ein Eintrag derselben Fachpresse von 2001 nennt für die Rothschild Maduro ein Deckblatt aus Kamerun. Die frühere Darstellung eines brasilianischen Deckblatts (Bahia, Arapiraca) hat keine Seite hinter sich und wird zurückgenommen. Die Churchill Maduro misst 7 ¼ Zoll bei Ringmaß 48 (derselbe Eintrag). Die Stärke wird von einem Einzelhändler als mittel und von anderen als mittelkräftig bis kräftig angegeben (Oktober 2026). Die Seite des Hauses zu seinen Zigarren mit kurzer Einlage (Medium Filler) zeigt Minis in Natural und in Maduro, ohne brasilianisches Deckblatt (Oktober 2026). Keine der gelesenen Seiten des Hauses belegt die übrigen Formate der Linie.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Das Maduro-Deckblatt ist die einschneidendste Verwandlung, die Tabak durchläuft. Ein Blatt, das schon wegen seiner Feinheit, seiner gleichmäßigen Farbe und seiner Haltung ausgewählt wurde, durchläuft eine verlängerte Fermentation — Monate, mitunter Jahre —, die seinen natürlichen Zucker unter geregelter Wärme und Feuchte in vielschichtige Verbindungen umwandelt. Das Blatt dunkelt vom Braun ins beinahe Schwarze. Seine Oberfläche wird ölig. Und es gewinnt eine natürliche Süße — weder zugesetzt noch künstlich, sondern von dieser langen zellulären Umwandlung hervorgebracht —, die den Charakter jeder Zigarre, die es umschließt, von Grund auf ändert.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro 是 Arturo Fuente 主力系列的马杜罗茄衣版本，在多米尼加共和国卷制。据行业媒体（Churchill Maduro 的条目，2017年10月），茄衣为来自美国的 Connecticut broadleaf，配多米尼加茄套和茄芯；一家零售商（Neptune Cigar，2026年10月）描述的是同样的组合。Fuente 的马杜罗茄衣并非一直是这个产地：同一家行业媒体2001年的一则条目，给 Rothschild Maduro 标的是喀麦隆茄衣。此前关于巴西茄衣（Bahia、Arapiraca）的说法没有页面依据，现予撤回。Churchill Maduro 长 7 ¼ 英寸，环径 48（同一条目）。力度方面，一家零售商称中等，其他商家称中强（2026年10月）。厂家关于短茄芯雪茄（Medium Filler）的页面展示的是原色茄衣和马杜罗茄衣两种迷你雪茄，没有巴西茄衣（2026年10月）。所读的厂家页面均未确立该产品线的其他规格。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('马杜罗茄衣是烟草所经历的最彻底的一次转变。一片本已因细腻、色泽匀整与骨架而被选中的叶子，要经过长时间发酵——数月，有时数年——在受控的温度与湿度下，把天然糖分转化成复杂的化合物。叶子由褐转向近乎全黑，表面变得油润。它由此获得一种天然的甜——不是外加的，也不是人工的，而是这场漫长的细胞转化所产生的——并从根本上改变它所包裹的任何一支雪茄的性格。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Arturo Fuente Maduro هو النسخة ذات غلاف المادورو من الخط الرئيسي لـ Arturo Fuente، ويُلفّ في الجمهورية الدومينيكية. وبحسب الصحافة المتخصصة (بطاقة Churchill Maduro، أكتوبر 2017)، الغلاف من Connecticut broadleaf القادم من الولايات المتحدة، فوق غلاف داخلي وحشوة دومينيكيين؛ ويصف أحد تجار التجزئة (Neptune Cigar، أكتوبر 2026) التركيبة نفسها. ولم يكن غلاف المادورو من Fuente دائمًا بهذا المصدر: فبطاقة من الصحافة نفسها تعود إلى 2001 تذكر غلافًا من الكاميرون لـ Rothschild Maduro. أما الرواية السابقة عن غلاف برازيلي (Bahia وArapiraca) فلا صفحة تسندها، وهي مسحوبة. ويبلغ طول Churchill Maduro ‏7 ¼ بوصات بقياس حلقة 48 (البطاقة نفسها). وتُذكر القوة متوسطة لدى أحد تجار التجزئة، ومتوسطة إلى كاملة لدى آخرين (أكتوبر 2026). وتعرض صفحة الدار عن سيجارها ذي الحشوة القصيرة (Medium Filler) سيجارات صغيرة بغلاف طبيعي وبغلاف مادورو، دون غلاف برازيلي (أكتوبر 2026). ولا تثبت أي من صفحات الدار المقروءة بقية طرازات الخط.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('غلاف المادورو هو أشدّ تحوّل يمرّ به التبغ. فالورقة التي اختيرت أصلًا لرهافتها ولونها المتساوي وتماسكها تمرّ بتخمير مطوَّل — شهور، وأحيانًا سنوات — يحوّل سكّرياتها الطبيعية، تحت حرارة ورطوبة مضبوطتين، إلى مركّبات معقّدة. تدكن الورقة من البنّي إلى ما يقارب الأسود، ويصير سطحها زيتيًّا. وتكتسب حلاوة طبيعية — غير مضافة وغير اصطناعية، بل ناتجة عن هذا التحوّل الخلوي الطويل — تغيّر في العمق طابع أي سيجار تغلّفه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''approche d''Arturo Fuente en la matière fut délibérée, et géographiquement précise. Plutôt que le Connecticut broadleaf, source américaine habituelle du maduro, la famille a choisi des tabacs brésiliens de Bahia et d''Arapiraca — des régions où les sols rouges profonds, l''humidité équatoriale et des siècles de culture donnent des feuilles naturellement sombres, un peu épaisses, qui fermentent avec une régularité inhabituelle. La cape maduro brésilienne est reconnue pour un caractère chocolaté particulier, quelque part entre le cacao en poudre et la ganache noire, que le Connecticut broadleaf atteint rarement.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST(CONCAT('Arturo Fuente''s approach to Maduro was deliberate and geographically specific. Rather than using Connecticut broadleaf — the standard American Maduro source — the family chose Brazilian tobacco from Bahia and Arapiraca, regions where the combination of deep red soils, equatorial humidity, and centuries of cultivation expertise produces naturally dark, slightly thick leaves that ferment with unusual reliability. Brazilian Maduro wrapper is known for a specific chocolate character — somewhere between cocoa powder and dark ganache — that Connecticut broadleaf rarely achieves.', CHAR(13), '
', CHAR(13), '
') AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El enfoque de Arturo Fuente en la materia fue deliberado, y geográficamente preciso. Antes que el Connecticut broadleaf, fuente estadounidense habitual del maduro, la familia eligió tabacos brasileños de Bahía y de Arapiraca —regiones donde los suelos rojos profundos, la humedad ecuatorial y siglos de cultivo dan hojas naturalmente oscuras, algo gruesas, que fermentan con una regularidad inhabitual. La capa maduro brasileña es reconocida por un carácter achocolatado particular, en algún punto entre el cacao en polvo y la ganache negra, que el Connecticut broadleaf alcanza rara vez.

' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
UNION ALL SELECT 'Arturo Fuente Maduro', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das Vorgehen von Arturo Fuente war hier bewusst und geografisch genau. Statt des Connecticut Broadleaf, der üblichen amerikanischen Quelle des Maduro, wählte die Familie brasilianische Tabake aus Bahia und Arapiraca — Gegenden, in denen tiefrote Böden, äquatoriale Feuchte und Jahrhunderte des Anbaus von Natur aus dunkle, etwas dickere Blätter ergeben, die ungewöhnlich gleichmäßig fermentieren. Das brasilianische Maduro-Deckblatt ist für einen eigenen schokoladigen Charakter bekannt, irgendwo zwischen Kakaopulver und dunkler Ganache, den das Connecticut Broadleaf selten erreicht.

' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Arturo Fuente Maduro'
