UNION ALL SELECT 'CAO Cameroon', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon, que la maison et les détaillants appellent aussi Cameroon L''Anniversaire, est une ligne de la marque CAO lancée en 1998 pour les 30 ans de la maison, que ce détaillant (cigarsdirect.com) date de 1968. Les détaillants la décrivent avec une cape camerounaise, un liant et une tripe nicaraguayens, et une force moyenne.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire du tabac camerounais dans le cigare premium est d''abord celle d''une découverte retardée par la géographie. La province du Centre — sols équatoriaux, humidité constante, températures qui varient à peine d''un mois à l''autre — produit une cape que rien de ce qui pousse aux Amériques ne reproduit. Elle est plus sombre que le Connecticut Shade, plus complexe de structure, et porte une teneur naturelle en huiles qui la rend reconnaissable à l''œil et puissante au nez dès la coupe.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon, which the house and retailers also call Cameroon L''Anniversaire, is a line from the CAO brand launched in 1998 for the house''s 30th anniversary, which this retailer (cigarsdirect.com) dates to 1968. Retailers describe it with a Cameroonian wrapper, a Nicaraguan binder and filler, and medium strength.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The story of Cameroonian tobacco in premium cigars is largely a story of discovery delayed by geography. The Centre province of Cameroon — a region of equatorial soils, consistent humidity, and temperatures that barely vary month to month — produces a wrapper leaf unlike anything grown in the Americas. It is darker in color than Connecticut shade, more complex in structure, and carries a natural oil content that makes it visually distinctive and aromatically potent from the moment the cigar is cut.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon, que la casa y los comerciantes llaman también Cameroon L''Anniversaire, es una línea de la marca CAO lanzada en 1998 para los 30 años de la casa, que este comerciante (cigarsdirect.com) fecha en 1968. Los comerciantes la describen con una capa camerunesa, un capote y una tripa nicaragüenses, y una fuerza media.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia del tabaco camerunés en el puro premium es ante todo la de un descubrimiento retrasado por la geografía. La provincia del Centro —suelos ecuatoriales, humedad constante, temperaturas que apenas varían de un mes a otro— produce una capa que nada de cuanto crece en América reproduce. Es más oscura que el Connecticut Shade, de estructura más compleja, y lleva un contenido natural en aceites que la hace reconocible a la vista y potente en nariz desde el corte.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon, das das Haus und Händler auch Cameroon L''Anniversaire nennen, ist eine Linie der Marke CAO, die 1998 zum 30-jährigen Bestehen des Hauses eingeführt wurde, dessen Gründung dieser Händler (cigarsdirect.com) auf 1968 datiert. Händler beschreiben sie mit einem kamerunischen Deckblatt, einem nicaraguanischen Umblatt und einer nicaraguanischen Einlage und mittlerer Stärke.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte des kamerunischen Tabaks in der Premiumzigarre ist zuerst die einer Entdeckung, die von der Geografie aufgehalten wurde. Die Zentralprovinz — äquatoriale Böden, gleichbleibende Feuchte, Temperaturen, die von Monat zu Monat kaum schwanken — bringt ein Deckblatt hervor, das nichts von dem, was in Amerika wächst, nachbildet. Es ist dunkler als das Connecticut Shade, im Bau vielschichtiger, und trägt einen natürlichen Ölgehalt, der es mit dem Auge erkennbar und ab dem Schnitt in der Nase kräftig macht.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon，字号与零售商也称其为 Cameroon L''Anniversaire，是 CAO 品牌的一条产品线，于1998年为字号成立30周年而推出，该零售商（cigarsdirect.com）将这一时间定在1968年。零售商描述其为喀麦隆茄衣，配尼加拉瓜茄套与茄芯，浓度中等。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('喀麦隆烟叶在高端雪茄中的故事，首先是一段被地理耽误的发现。中部省——赤道土壤、恒定湿度、月与月之间几乎不变的气温——出产的茄衣，是美洲任何产地都复制不出来的。它比康涅狄格阴植叶更深，结构更复杂，天然含油量让它一眼可辨，切开即在鼻端显出力量。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Cameroon، التي تسمّيها الدار والتجّار أيضًا Cameroon L''Anniversaire، خطّ من علامة CAO أُطلق عام 1998 بمناسبة مرور 30 عامًا على الدار، وهو ما يؤرّخه هذا التاجر (cigarsdirect.com) بعام 1968. يصفها التجّار بغلاف كاميروني وغلاف داخلي وحشوة نيكاراغويّين، وبقوة متوسطة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تاريخ التبغ الكاميروني في السيجار الفاخر هو أوّلًا تاريخ اكتشاف أخّرته الجغرافيا. فالمقاطعة الوسطى — تربة استوائية، ورطوبة ثابتة، وحرارة لا تكاد تتغيّر من شهر إلى آخر — تنتج غلافًا لا يعيد إنتاجه شيء مما ينبت في الأمريكتين. إنه أدكن من كونيتيكت شيد، وأعقد بنيةً، ويحمل نسبة زيوت طبيعية تجعله معروفًا بالعين وقويًّا في الأنف منذ القطع.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Elle est roulée au Nicaragua : la fiche d''une revue à l''aveugle de Blind Man''s Puff (28 février 2024, vitola Robusto) donne la fabrique STG Estelí et le Nicaragua pour origine ; d''autres détaillants donnent aussi le Nicaragua, sans nommer la fabrique. Aucune page lue ne place cette ligne au Honduras. Quant à l''appellation de cape « AVO XO », aucune page lue ne la porte.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('CAO fut l''une des premières maisons américaines à bâtir une gamme entière sur ce terroir. La gamme Cameroon emploie la cape AVO XO — une sélection précise de la province du Centre, qui représente le haut du panier de la feuille camerounaise arrivant sur le marché américain. Sa complexité s''impose d''emblée : un caractère cacaoté prononcé, entre chocolat au lait et chocolat noir, doublé d''une douceur naturelle qui contredit l''épice de l''assemblage au lieu de l''amplifier.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('It is rolled in Nicaragua: the listing for a Blind Man''s Puff blind review (28 February 2024, Robusto vitola) gives the STG Estelí factory and Nicaragua as the origin; other retailers also give Nicaragua, without naming the factory. No page read places this line in Honduras. As for the "AVO XO" wrapper designation, no page read carries it.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('CAO was among the first American manufacturers to build an entire range around this terroir. The CAO Cameroon line uses the AVO XO wrapper — a specific selection from the Centre province that represents the top tier of Cameroonian leaf reaching the American market. The wrapper''s complexity is immediately evident: a pronounced cocoa character that sits between milk chocolate and dark, combined with a natural sweetness that counters rather than amplifies the blend''s spice. The effect is a profile of unusual sophistication for a mid-priced range.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Se tuerce en Nicaragua: la ficha de una cata a ciegas de Blind Man''s Puff (28 de febrero de 2024, vitola Robusto) da la fábrica STG Estelí y Nicaragua como origen; otros comerciantes dan también Nicaragua, sin nombrar la fábrica. Ninguna página leída sitúa esta línea en Honduras. En cuanto a la denominación de capa «AVO XO», ninguna página leída la lleva.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('CAO fue una de las primeras casas estadounidenses en levantar una gama entera sobre este terruño. La gama Cameroon emplea la capa AVO XO —una selección precisa de la provincia del Centro, que representa lo más alto de la hoja camerunesa que llega al mercado estadounidense. Su complejidad se impone de entrada: un carácter cacaotado pronunciado, entre chocolate con leche y chocolate negro, doblado de una dulzura natural que contradice la especia de la ligada en lugar de amplificarla.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Sie wird in Nicaragua gerollt: Der Eintrag zu einer Blindverkostung von Blind Man''s Puff (28. Februar 2024, Vitola Robusto) nennt die Fabrik STG Estelí und Nicaragua als Herkunft; andere Händler nennen ebenfalls Nicaragua, ohne die Fabrik zu nennen. Keine gelesene Seite verortet diese Linie in Honduras. Die Deckblattbezeichnung „AVO XO“ trägt keine gelesene Seite.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('CAO war eines der ersten amerikanischen Häuser, das eine ganze Linie auf diesen Boden stellte. Die Linie Cameroon verwendet das AVO-XO-Deckblatt — eine genaue Auslese aus der Zentralprovinz, die das Beste des kamerunischen Blattes darstellt, das auf den amerikanischen Markt gelangt. Ihre Vielschichtigkeit setzt sich sofort durch: ein ausgeprägter Kakaocharakter, zwischen Milchschokolade und Zartbitterschokolade, verdoppelt von einer natürlichen Süße, die der Würze der Mischung widerspricht, statt sie zu verstärken.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('它在尼加拉瓜手工卷制：Blind Man''s Puff 一次盲测的资料页（2024年2月28日，Robusto 规格）给出的工厂是 STG Estelí，产地为尼加拉瓜；其他零售商也给出尼加拉瓜，但未点出工厂。所读页面均未把这条产品线置于洪都拉斯。至于“AVO XO”这一茄衣名称，所读页面均未出现。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('CAO 是最早把整条产品线建立在这片风土上的美国字号之一。喀麦隆系列用的是 AVO XO 茄衣——来自中部省的精确选料，代表进入美国市场的喀麦隆叶中最好的一档。它的复杂度一上来就压得住：可可感鲜明，介于牛奶巧克力与黑巧克力之间，又叠着一层天然的甜，与配方里的香料相抵而非相加。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تُلفّ في نيكاراغوا: صفحة تذوّق أعمى لدى Blind Man''s Puff (28 فبراير 2024، قياس Robusto) تذكر مصنع STG Estelí ونيكاراغوا منشأً؛ ويذكر تجّار آخرون نيكاراغوا أيضًا دون تسمية المصنع. ولا تضع أيّ صفحة مقروءة هذا الخطّ في هندوراس. أما تسمية الغلاف «AVO XO» فلا تحملها أيّ صفحة مقروءة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('كانت CAO من أوائل الدور الأمريكية التي بنت تشكيلة كاملة على هذه الأرض. تستعمل تشكيلة الكاميرون غلاف AVO XO — انتقاء دقيق من المقاطعة الوسطى، يمثّل أعلى ما يصل من الورقة الكاميرونية إلى السوق الأمريكية. يفرض تركيبها نفسه من البداية: طابع كاكاوي واضح، بين الشوكولاتة بالحليب والشوكولاتة الداكنة، تضاعفه حلاوة طبيعية تناقض توابل الخلطة بدل أن تضخّمها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
UNION ALL SELECT 'CAO Cameroon', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Sous cette cape, la tripe associe des tabacs dominicains et brésiliens choisis pour accompagner la feuille plutôt que lui disputer la place. Il en résulte un cigare qui ouvre sur le chocolat et un poivre doux, évolue vers le café et la cerise séchée, et s''achève sur une longue note de cèdre légèrement sucrée — une démonstration de ce qu''une cape bien choisie peut faire d''un assemblage par ailleurs classique.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Cameroon'
