UNION ALL SELECT 'CAO Black', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La vallée mexicaine de San Andrés s''étend dans l''État de Veracruz, entre la côte du golfe du Mexique et les volcans de l''Orizaba, à des altitudes de 800 à 1 200 mètres. Sols volcaniques, humidité constante apportée par les masses d''air du golfe, températures tempérées par l''altitude : ces conditions donnent un tabac qui ne ressemble à aucun autre sur le continent américain. La feuille de San Andrés est sombre — naturellement, sans la fermentation prolongée qui produit les maduros du Connecticut ou du Brésil — et porte une amertume particulière, que les assembleurs recherchent pour sa capacité à tenir un assemblage face à la douceur des tripes plus légères.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Black is a line from the house of CAO, presented by a retailer (cigarworld.com, October 2026) as CAO''s first regular line, without a date. It has an Ecuadorian Connecticut wrapper and a Nicaraguan binder, over a longfiller of Nicaragua, Honduras and Mexico (cigarplace.biz, cigarworld.com, October 2026).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Mexican San Andrés valley sits in the state of Veracruz, between the Gulf of Mexico coast and the Orizaba volcanic range, at elevations between 800 and 1,200 meters. The combination of volcanic soil, consistent humidity from Gulf air masses, and altitude-modulated temperatures creates conditions that produce tobacco unlike any other in the Americas. San Andrés leaf is dark — naturally, without the extended fermentation that produces Connecticut or Brazilian Maduro — and carries a specific bitterness that blenders prize for its ability to anchor a blend against the sweetness of lighter fillers.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
