UNION ALL SELECT 'CAO Black', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('El valle mexicano de San Andrés se extiende en el estado de Veracruz, entre la costa del golfo de México y los volcanes del Orizaba, a altitudes de 800 a 1.200 metros. Suelos volcánicos, humedad constante traída por las masas de aire del golfo, temperaturas templadas por la altitud: esas condiciones dan un tabaco que no se parece a ningún otro del continente americano. La hoja de San Andrés es oscura —de forma natural, sin la fermentación prolongada que produce los maduros del Connecticut o de Brasil— y lleva un amargor particular, que los ligadores buscan por su capacidad de sostener una ligada frente a la suavidad de las tripas más ligeras.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Black ist eine Linie des Hauses CAO, von einem Händler (cigarworld.com, Oktober 2026) als erste reguläre Linie von CAO vorgestellt, ohne Datum. Sie trägt ein Connecticut-Deckblatt aus Ecuador und ein nicaraguanisches Umblatt, über einer Longfiller-Einlage aus Nicaragua, Honduras und Mexiko (cigarplace.biz, cigarworld.com, Oktober 2026).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Das mexikanische Tal von San Andrés liegt im Bundesstaat Veracruz, zwischen der Golfküste und den Vulkanen des Orizaba, in Höhen von 800 bis 1.200 Metern. Vulkanische Böden, gleichbleibende Feuchte, die die Luftmassen des Golfs heranführen, von der Höhe gemäßigte Temperaturen: Diese Bedingungen ergeben einen Tabak, der keinem anderen auf dem amerikanischen Kontinent gleicht. Das Blatt aus San Andrés ist dunkel — von Natur aus, ohne die verlängerte Fermentation, die die Maduros aus Connecticut oder Brasilien hervorbringt — und trägt eine eigentümliche Bitterkeit, die Mischer suchen, weil sie eine Mischung gegen die Milde leichterer Einlagen zu tragen vermag.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO Black 是 CAO 字号的一条产品线，一家零售商（cigarworld.com，2026年10月）称其为 CAO 的首条常规产品线，未给日期。它用厄瓜多尔康涅狄格茄衣与尼加拉瓜茄套，茄芯为长叶烟丝，产自尼加拉瓜、洪都拉斯与墨西哥（cigarplace.biz，cigarworld.com，2026年10月）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('墨西哥的圣安德烈斯河谷位于韦拉克鲁斯州，夹在墨西哥湾海岸与奥里萨巴的火山之间，海拔在800到1200米。火山土壤、由海湾气团带来的恒定湿度、被海拔调低的气温：这些条件长出的烟草，在美洲大陆上没有第二处相似。圣安德烈斯的叶子天生就深——不需要康涅狄格或巴西马杜罗所依赖的长时间发酵——并带着一种特别的苦，调配师看重的正是它在更轻茄芯的柔顺面前撑住整副配方的能力。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
