UNION ALL SELECT 'CAO Black', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يمتدّ وادي سان أندريس المكسيكي في ولاية فيراكروس، بين ساحل خليج المكسيك وبراكين أوريسابا، على ارتفاعات تتراوح بين 800 و1200 متر. تربة بركانية، ورطوبة ثابتة تحملها كتل هواء الخليج، وحرارة يلطّفها الارتفاع: هذه الشروط تعطي تبغًا لا يشبه سواه في القارة الأمريكية. فورقة سان أندريس داكنة — بطبيعتها، دون التخمير المطوَّل الذي ينتج مادورو كونيتيكت أو البرازيل — وتحمل مرارة خاصة يقصدها الخلّاطون لقدرتها على حمل الخلطة في مواجهة لطف الحشوات الأخفّ.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Un détaillant (cigarplace.biz, octobre 2026) la dit d''abord fabriquée au Honduras ; aucune page lue ne nomme la fabrique actuelle. À ne pas confondre avec CAO Black VR, ligne distincte à cape brésilienne (Stogie Review, 5 mars 2008).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
