UNION ALL SELECT 'CAO Black', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('A retailer (cigarplace.biz, October 2026) says it was first made in Honduras; no page read names the current factory. Not to be confused with CAO Black VR, a separate line with a Brazilian wrapper (Stogie Review, 5 March 2008).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
