UNION ALL SELECT 'CAO Black', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das San-Andrés-Maduro-Deckblatt der Linie Black führt diesen Boden zu Ende. Das schon im Naturzustand dunkle Blatt durchläuft eine verlängerte Fermentation, die es bis fast ins Schwarze führt und seine Bitterkeit in einen vielschichtigen würzigen Charakter verwandelt. Das Ergebnis ist keine aufgesetzte Farbe, sondern ein Blatt, das mit äußerster Intensität fermentiert hat, ohne im Aufbau nachzugeben.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
