UNION ALL SELECT 'CAO Black', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Les détaillants la décrivent de force moyenne à medium-full, avec des notes de crème, de cèdre et de poivre ; les avis divergent d''un détaillant à l''autre. Les tailles listées par cigarworld.com portent des noms propres : Frontier, Gothic, Bengal, Mosaic, Storm.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
