UNION ALL SELECT 'CAO Black', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Retailers describe it as medium to medium-full in strength, with notes of cream, cedar and pepper; opinions differ from one retailer to another. The sizes listed by cigarworld.com have proper names: Frontier, Gothic, Bengal, Mosaic, Storm.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO Black'
UNION ALL SELECT 'CAO Black', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Over the Nicaraguan-Honduran filler blend that CAO uses throughout its premium catalog, this wrapper creates a profile of exceptional distinctiveness. The first third delivers pure cocoa — not sweetened, not diluted, but the aggressive bitterness of unsweetened baking chocolate. The middle third introduces licorice and Cayenne pepper in a combination that recalls the flavor profile of Mexican mole sauce, which is not coincidental: the same San Andrés pepper-growing tradition that produces the region''s famous chiles exists alongside its tobacco cultivation. The final third resolves toward a long, warming finish of dark spice and espresso.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
