UNION ALL SELECT 'CAO Black', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Sobre la tripa nicaragüense y hondureña que CAO emplea en todo su catálogo premium, esa capa crea un perfil sin equivalente en la gama. El primer tercio da cacao puro —ni azucarado ni diluido, el amargor franco del chocolate de cobertura. El segundo introduce regaliz y pimienta de Cayena, en una combinación que recuerda el mole mexicano —y no es casualidad: la tradición de los chiles de San Andrés convive con la del tabaco. El último tercio acaba en un final largo y cálido de especias oscuras y de espresso.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO Black'
