UNION ALL SELECT 'CAO America', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America est une ligne de la maison CAO, présentée en 2007 au salon des détaillants (RTDA) de Houston. Selon la presse du métier (septembre 2007), elle était roulée à la fabrique C.A.O. du Honduras, avec deux capes cultivées aux États-Unis : un Connecticut Shade brun doré et un broadleaf brun chocolat.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO America est une déclaration d''indépendance — non pas politique, mais agricole. Lancée en 2004, elle arrive à un moment où le cigare premium ne parlait plus que de puissance nicaraguayenne et de terre hondurienne. La conversation portait sur l''Amérique centrale. CAO répondit en regardant vers le nord, vers les champs qui avaient approvisionné les fumeurs américains pendant trois siècles, avant que la révolution cubaine et l''essor nicaraguayen ne redessinent le marché.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America is a line from the house of CAO, presented in 2007 at the retailers’ trade show (RTDA) in Houston. According to the trade press (September 2007), it was rolled at the C.A.O. factory in Honduras, with two wrappers grown in the United States: a golden-brown Connecticut Shade and a chocolate-brown broadleaf.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO America is a declaration of independence — not political, but agricultural. Launched in 2004, it arrived at a moment when the premium cigar world had become entirely preoccupied with Nicaraguan power and Honduran earthiness. The conversation was always about Central American terroir. CAO''s response was to look north, to the tobacco fields that had supplied American smokers for three centuries before the Cuban revolution and the Nicaraguan boom reshaped the market.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America es una línea de la casa CAO, presentada en 2007 en el salón de los detallistas (RTDA) de Houston. Según la prensa del sector (septiembre de 2007), se torcía en la fábrica C.A.O. de Honduras, con dos capas cultivadas en Estados Unidos: un Connecticut Shade marrón dorado y un broadleaf marrón chocolate.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO America es una declaración de independencia —no política, sino agrícola. Lanzada en 2004, llega en un momento en que el puro premium solo hablaba de potencia nicaragüense y de tierra hondureña. La conversación giraba en torno a Centroamérica. CAO respondió mirando al norte, hacia los campos que habían abastecido a los fumadores estadounidenses durante tres siglos, antes de que la revolución cubana y el auge nicaragüense redibujaran el mercado.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America ist eine Linie des Hauses CAO, 2007 auf der Händlermesse (RTDA) in Houston vorgestellt. Laut der Fachpresse (September 2007) wurde sie in der Fabrik C.A.O. in Honduras gerollt, mit zwei in den Vereinigten Staaten angebauten Deckblättern: einem goldbraunen Connecticut Shade und einem schokoladenbraunen Broadleaf.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO America ist eine Unabhängigkeitserklärung — keine politische, eine landwirtschaftliche. 2004 herausgebracht, kommt sie in einem Augenblick, in dem die Premiumzigarre nur noch von nicaraguanischer Kraft und honduranischer Erde sprach. Das Gespräch drehte sich um Mittelamerika. CAO antwortete mit einem Blick nach Norden, auf die Felder, die amerikanische Raucher drei Jahrhunderte lang beliefert hatten, bevor die kubanische Revolution und der Aufstieg Nicaraguas den Markt neu zeichneten.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America 是 CAO 公司旗下的一个系列，2007年在休斯敦举行的零售商展会（RTDA）上推出。据行业媒体（2007年9月）报道，它在洪都拉斯的 C.A.O. 工厂卷制，使用两种美国种植的茄衣：金褐色的 Connecticut Shade 和巧克力褐色的 broadleaf。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('CAO America 是一份独立宣言——不是政治上的，而是农业上的。它于2004年推出，正赶上高端雪茄言必称尼加拉瓜的力量与洪都拉斯的土地的时候。话题都围着中美洲转。CAO 的回应是往北看，看向那些在古巴革命与尼加拉瓜崛起重画市场之前，为美国烟客供货三百年的田地。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('CAO America خط من دار CAO، قُدِّم عام 2007 في معرض تجّار التجزئة (RTDA) في هيوستن. وبحسب الصحافة المتخصصة في القطاع (سبتمبر 2007)، كان يُلَفّ في مصنع C.A.O. في هندوراس، بغلافين مزروعين في الولايات المتحدة: Connecticut Shade بني ذهبي وbroadleaf بني شوكولاتي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('«كاو أمريكا» إعلان استقلال — لا سياسي بل زراعي. صدرت عام 2004، في لحظة لم يكن السيجار الفاخر يتحدّث فيها إلا عن القوة النيكاراغوية والأرض الهندوراسية. كان الحديث كله عن أمريكا الوسطى. فردّت CAO بأن نظرت شمالًا، إلى الحقول التي زوّدت المدخّنين الأمريكيين ثلاثة قرون، قبل أن تعيد الثورة الكوبية وصعود نيكاراغوا رسم السوق.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le mélange n''est pas entièrement américain : le liant est brésilien et la tripe associe du tabac américain à des feuilles du Nicaragua, d''Italie et de République dominicaine (même source, 2007). Une fiche de notation de 2021-2022 donne la même construction, avec le Nicaragua comme pays d''origine ; la fiche garde les deux versions. L''effet pinstripe vient de la cape Shade laissée apparente sous les feuilles broadleaf (détaillant cigarsdirect.com, octobre 2026).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le principe est simple, et presque provocant de précision : du tabac américain à 100 %, dans chaque composant. Les capes viennent de la vallée du Connecticut, dont le sol sablo-limoneux donne la feuille d''ombre qui a fait la réputation du style. Les sous-capes viennent du comté de Lancaster, en Pennsylvanie, où l''on cultive le broadleaf depuis le XVIIe siècle. Les tripes mêlent des feuilles de Virginie — où la culture du tabac est antérieure aux États-Unis eux-mêmes — et à nouveau du Connecticut.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The blend is not entirely American: the binder is Brazilian and the filler combines American tobacco with leaves from Nicaragua, Italy and the Dominican Republic (same source, 2007). A tasting sheet from 2021-2022 gives the same construction, with Nicaragua as the country of origin; the entry keeps both versions. The pinstripe effect comes from the Shade wrapper left visible beneath the broadleaf leaves (retailer cigarsdirect.com, October 2026).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The concept is straightforward and almost defiantly specific: 100% American tobacco in every component. The wrappers come from Connecticut''s river valley, where the famously sandy loam soil produces the shade-grown leaf that made the style''s reputation. The binders draw from Pennsylvania''s Lancaster County, where broadleaf tobacco has been grown since the 17th century. The fillers blend leaf from Virginia, where tobacco cultivation predates the United States itself, and from Connecticut once more.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La mezcla no es enteramente estadounidense: el capote es brasileño y la tripa combina tabaco estadounidense con hojas de Nicaragua, Italia y República Dominicana (misma fuente, 2007). Una ficha de cata de 2021-2022 da la misma construcción, con Nicaragua como país de origen; esta ficha conserva las dos versiones. El efecto pinstripe viene de la capa Shade dejada a la vista bajo las hojas broadleaf (detallista cigarsdirect.com, octubre de 2026).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El principio es simple, y casi provocador de tan preciso: tabaco estadounidense al 100 %, en cada componente. Las capas vienen del valle del Connecticut, cuyo suelo areno-limoso da la hoja de sombra que hizo la reputación del estilo. Los capotes vienen del condado de Lancaster, en Pensilvania, donde se cultiva broadleaf desde el siglo XVII. Las tripas mezclan hojas de Virginia —donde el cultivo del tabaco es anterior a los propios Estados Unidos— y de nuevo del Connecticut.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Mischung ist nicht ganz amerikanisch: Das Umblatt ist brasilianisch, und die Einlage verbindet amerikanischen Tabak mit Blättern aus Nicaragua, Italien und der Dominikanischen Republik (gleiche Quelle, 2007). Ein Verkostungsbogen von 2021-2022 nennt denselben Aufbau, mit Nicaragua als Herkunftsland; der Eintrag führt beide Versionen. Der Pinstripe-Effekt entsteht, weil das Shade-Deckblatt unter den Broadleaf-Blättern sichtbar bleibt (Händler cigarsdirect.com, Oktober 2026).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das Prinzip ist einfach und in seiner Genauigkeit fast herausfordernd: amerikanischer Tabak zu 100 %, in jedem Bestandteil. Die Deckblätter kommen aus dem Connecticut-Tal, dessen sandig-lehmiger Boden das Schattenblatt hervorbringt, das den Ruf des Stils begründet hat. Die Umblätter stammen aus Lancaster County in Pennsylvania, wo seit dem 17. Jahrhundert Broadleaf angebaut wird. Die Einlagen mischen Blätter aus Virginia — wo der Tabakanbau älter ist als die Vereinigten Staaten selbst — und wiederum aus Connecticut.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('这款混合并非全部来自美国：茄套为巴西产，茄芯把美国烟草与来自尼加拉瓜、意大利和多米尼加共和国的叶片结合起来（同一来源，2007年）。一份2021-2022年的品鉴表给出相同的构成，原产国写作尼加拉瓜；本条目保留两个版本。pinstripe 效果来自露在 broadleaf 叶片之下的 Shade 茄衣（零售商 cigarsdirect.com，2026年10月）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('原则简单，精确到近乎挑衅：每一个部分都用百分之百的美国烟草。茄衣来自康涅狄格河谷，那里的砂壤土长出成就了这一风格声誉的阴植叶。茄套来自宾夕法尼亚的兰开斯特县，17世纪起就在那里种植宽叶烟。茄芯则把弗吉尼亚的叶子——那里的烟草种植比美国本身还要早——与康涅狄格的叶子混在一起。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('التركيبة ليست أمريكية بالكامل: الغلاف الداخلي برازيلي، والحشوة تجمع تبغًا أمريكيًا مع أوراق من نيكاراغوا وإيطاليا والجمهورية الدومينيكية (المصدر نفسه، 2007). وتعطي بطاقة تذوّق من 2021-2022 البنية نفسها، مع نيكاراغوا بلدًا للمنشأ؛ وتحتفظ هذه الصفحة بالنسختين. ويأتي أثر pinstripe من غلاف Shade المتروك ظاهرًا تحت أوراق broadleaf (التاجر cigarsdirect.com، أكتوبر 2026).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('المبدأ بسيط، ودقيق إلى حدّ يكاد يكون استفزازًا: تبغ أمريكي مئة في المئة، في كل مكوّن. تأتي الأغلفة من وادي كونيتيكت، حيث تعطي التربة الرملية الطميية ورقة الظل التي صنعت سمعة هذا الأسلوب. وتأتي الأغلفة الداخلية من مقاطعة لانكستر في بنسلفانيا، حيث يُزرع التبغ العريض منذ القرن السابع عشر. أما الحشوات فتمزج أوراقًا من فرجينيا — حيث زراعة التبغ أقدم من الولايات المتحدة نفسها — وأوراقًا أخرى من كونيتيكت.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Les détaillants la disent de force moyenne à corsée (cigarsdirect.com, octobre 2026). Les vitolas d''origine sont le Potomac (5 × 56), le Landmark (6 × 60) et le Monument, un torpedo de 6 ¼ pouces.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Techniquement, cela produit un cigare entièrement hors du profil centraméricain qui domine le secteur. Les America sont plus ronds, plus doux, plus herbacés que les nicaraguayens. Ils ont l''onctuosité que donne naturellement un bon Connecticut Shade, avec des notes de foin sec, de cèdre chaud et la légère note de noisette d''une feuille de Pennsylvanie bien séchée. La force moyenne laisse le tabac s''exprimer sans le poivre et la terre qui marquent le style nicaraguayen.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Retailers describe it as medium to full in strength (cigarsdirect.com, October 2026). The original vitolas are the Potomac (5 × 56), the Landmark (6 × 60) and the Monument, a torpedo of 6 ¼ inches.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
UNION ALL SELECT 'CAO America', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('What this creates, technically, is a cigar entirely outside the Central American flavor profile that dominates the premium sector. CAO America profiles are rounder, gentler, and more herbaceous than Nicaraguan cigars. They share the creamy texture that good Connecticut shade naturally produces, with underlying notes of dried grass, warm cedar, and the mild nuttiness of well-cured Pennsylvania leaf. The medium-body strength allows the tobacco''s character to express itself without the aggressive pepper and earth notes that mark the Nicaraguan style.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
