UNION ALL SELECT 'CAO America', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Técnicamente, eso produce un puro enteramente fuera del perfil centroamericano que domina el sector. Los America son más redondos, más suaves, más herbáceos que los nicaragüenses. Tienen la untuosidad que da naturalmente un buen Connecticut Shade, con notas de heno seco, de cedro cálido y la ligera nota de avellana de una hoja de Pensilvania bien secada. La fuerza media deja al tabaco expresarse sin la pimienta y la tierra que marcan el estilo nicaragüense.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
