UNION ALL SELECT 'CAO America', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Technisch ergibt das eine Zigarre, die ganz außerhalb des mittelamerikanischen Profils steht, das die Branche beherrscht. Die America sind runder, milder, krautiger als die Nicaraguaner. Sie haben die Cremigkeit, die ein gutes Connecticut Shade von selbst gibt, mit Noten von trockenem Heu, warmer Zeder und der leichten Haselnussnote eines gut getrockneten Pennsylvania-Blattes. Die mittlere Stärke lässt den Tabak sprechen, ohne die Pfefferschärfe und die Erde, die den nicaraguanischen Stil prägen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
