UNION ALL SELECT 'CAO America', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('在工艺上，这做出了一支完全跳出行业主流中美洲调性的雪茄。America 比尼加拉瓜作品更圆润、更柔和、更带草本气。它有好的康涅狄格阴植叶天然给出的顺滑，佐以干草、温热雪松，以及一片干燥得当的宾夕法尼亚叶子所带的淡淡榛子气。中等力度让烟草自己说话，没有尼加拉瓜风格里那股胡椒与泥土。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
