UNION ALL SELECT 'CAO America', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La gama chocó primero con el escepticismo de detallistas acostumbrados a vender intensidad. El tabaco estadounidense se asociaba, algo injustamente, al mercado de masas mecanizado más que al premium artesanal. CAO America tomó ese prejuicio de frente, presentándose como el producto de una elección de terruño deliberada y no de un cálculo comercial. El éxito que siguió —sobre todo en los mercados donde la elegancia prima sobre la potencia— validó la apuesta.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'CAO America'
