UNION ALL SELECT 'CAO America', 'fr', 'source (correction)', (LOCATE(CAST('cigaraficionado.com « C.A.O. America » (10 septembre 2007 : fabrique C.A.O. au Honduras, deux capes américaines, liant brésilien, tripe américaine/Nicaragua/Italie/Rép. dominicaine) ; cigaraficionado.com « CAO America Monument » (fiche de notation, 2021-2022 : origine Nicaragua) ; cigarsdirect.com « CAO America » (octobre 2026 : pinstripe, vitolas) ; cigaraficionado.com « The new look of CAO » (30 mai 2011 : fabriques de Danlí et d''Estelí)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'CAO America'
