UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La Serie G occupe une position précise dans le catalogue Oliva : c''est la gamme qui répond à la question de ce qu''une cape camerounaise fait au tabac nicaraguayen, quand l''une et l''autre sont choisies avec la précision que la maison réserve à ses lignes hautes.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The Serie G is a line from Oliva Cigar Co., a Nicaraguan house whose cigars are rolled in Estelí. Its wrapper comes from Cameroon; the binder and filler come from Nicaragua. According to the house’s page, it is a medium-bodied blend.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Serie G occupies a specific and important position in the Oliva catalog: it is the range that answers the question of what a Cameroon wrapper does to Nicaraguan tobacco when both are selected with the precision the company brings to its premium lines.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La Serie G es una línea de Oliva Cigar Co., casa nicaragüense cuyos puros se tuercen en Estelí. Su capa viene de Camerún; el capote y la tripa vienen de Nicaragua. Según la página de la casa, es una mezcla de cuerpo medio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La Serie G ocupa un lugar preciso en el catálogo de Oliva: es la gama que responde a la pregunta de qué le hace una capa camerunesa al tabaco nicaragüense, cuando una y otro se eligen con la precisión que la casa reserva a sus líneas altas.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Serie G ist eine Linie von Oliva Cigar Co., einem nicaraguanischen Haus, dessen Zigarren in Estelí gerollt werden. Ihr Deckblatt stammt aus Kamerun; Umblatt und Einlage stammen aus Nicaragua. Laut der Seite des Hauses ist sie eine Mischung von mittlerem Körper.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Serie G nimmt im Katalog von Oliva eine genaue Stelle ein: Sie ist die Linie, die beantwortet, was ein Kameruner Deckblatt mit nicaraguanischem Tabak macht, wenn beide mit der Genauigkeit gewählt werden, die das Haus seinen hohen Linien vorbehält.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Serie G 是 Oliva Cigar Co. 旗下的一个系列，这是一家尼加拉瓜公司，其雪茄在埃斯特利卷制。茄衣来自喀麦隆；茄套与茄芯来自尼加拉瓜。据该公司的页面介绍，这是一款中等醇厚度的混合。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('G系列在奥利瓦的产品目录里位置很明确：它回答的是，当喀麦隆茄衣与尼加拉瓜烟叶都以本厂高端线的精度来挑选时，前者会给后者带来什么。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Serie G خط من Oliva Cigar Co.، دار نيكاراغوية يُلَفّ سيجارها في إستيلي. غلافها من الكاميرون، أما الغلاف الداخلي والحشوة فمن نيكاراغوا. وبحسب صفحة الدار، هي خلطة متوسطة الجسم.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تحتلّ السلسلة G موقعًا محدّدًا في كتالوغ أوليفا: فهي التشكيلة التي تجيب عن سؤال ما الذي يفعله غلاف كاميروني بالتبغ النيكاراغوي، حين يُنتقى الاثنان بالدقة التي تحفظها الدار لخطوطها العليا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La page de la maison (olivacigar.com, consultée en octobre 2026) parle d''une cape africaine du Cameroun et de fillers nicaraguayens « Sun Grown ». La presse du métier, en 2007, décrit le Robusto box-pressed comme un cigare à cape du Cameroun, liant et filler du Nicaragua, ce dernier de graine cubaine. Aucune page lue ne dit de quelle zone du Cameroun viennent les feuilles, ni de quelle zone du Nicaragua vient la tripe.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Cape du Cameroun sur tripe nicaraguayenne de Jalapa n''est pas une combinaison rare — on la trouve partout sur le marché premium — mais l''exécution change tout. Les feuilles retenues par Oliva pour la Serie G viennent du milieu de gamme de la province du Centre : plus sombres et plus complexes que ce qui entre dans les camerounais courants, sans la structure de coût des sélections AVO XO réservées aux gammes plus chères. Il en résulte une cape qui donne chocolat et épice douce à un prix qui autorise le cigare quotidien.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The house’s page (olivacigar.com, consulted in October 2026) speaks of an African wrapper from Cameroon and of Nicaraguan fillers described as ‘Sun Grown’. The trade press, in 2007, describes the box-pressed Robusto as a cigar with a Cameroon wrapper and a Nicaraguan binder and filler, the latter of Cuban seed. No page read says which area of Cameroon the leaves come from, nor which area of Nicaragua the filler comes from.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Cameroonian wrapper over Nicaraguan Jalapa filler is not an unusual combination — it appears across the premium market — but the specific execution matters enormously. The leaves sourced by Oliva for the Serie G represent the Centre province''s mid-tier production: darker and more complex than what goes into standard market Cameroon cigars, but without the cost structure of the AVO XO selections that appear in more expensive ranges. The result is a wrapper that delivers chocolate and mild spice at a price point that justifies daily smoking.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La página de la casa (olivacigar.com, consultada en octubre de 2026) habla de una capa africana de Camerún y de tripas nicaragüenses «Sun Grown». La prensa del sector, en 2007, describe el Robusto prensado en caja como un puro con capa de Camerún, capote y tripa de Nicaragua, esta última de semilla cubana. Ninguna página leída dice de qué zona de Camerún vienen las hojas, ni de qué zona de Nicaragua viene la tripa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Capa de Camerún sobre tripa nicaragüense de Jalapa no es una combinación rara —se encuentra por todo el mercado premium—, pero la ejecución lo cambia todo. Las hojas que Oliva retiene para la Serie G vienen de la parte media de la provincia del Centro: más oscuras y más complejas que las que entran en los cameruneses corrientes, sin la estructura de coste de las selecciones AVO XO reservadas a gamas más caras. El resultado es una capa que da chocolate y especia suave a un precio que permite el puro de todos los días.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Seite des Hauses (olivacigar.com, abgerufen im Oktober 2026) spricht von einem afrikanischen Deckblatt aus Kamerun und von nicaraguanischen Einlagen „Sun Grown“. Die Fachpresse beschreibt 2007 den Robusto in Kastenpressung als Zigarre mit Deckblatt aus Kamerun, Umblatt und Einlage aus Nicaragua, Letztere aus kubanischem Saatgut. Keine gelesene Seite sagt, aus welcher Gegend Kameruns die Blätter stammen und aus welcher Gegend Nicaraguas die Einlage kommt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Kamerun-Deckblatt auf nicaraguanischer Einlage aus Jalapa ist keine seltene Verbindung — man findet sie überall im Premiumsegment —, doch die Ausführung macht den Unterschied. Die Blätter, die Oliva für die Serie G zurückhält, stammen aus der mittleren Lage der Zentralprovinz: dunkler und vielschichtiger als das, was in gewöhnliche Kameruner eingeht, ohne die Kostenstruktur der AVO-XO-Auslesen, die teureren Linien vorbehalten bleiben. Daraus entsteht ein Deckblatt, das Schokolade und milde Würze gibt, zu einem Preis, der die Zigarre für jeden Tag erlaubt.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('该公司页面（olivacigar.com，2026年10月查阅）提到来自喀麦隆的非洲茄衣，以及尼加拉瓜的“Sun Grown”茄芯。行业媒体在2007年把方形压制的 Robusto 描述为喀麦隆茄衣、尼加拉瓜茄套与茄芯的雪茄，其中茄芯为古巴种子。所查阅的页面均未说明叶片来自喀麦隆的哪个产区，也未说明茄芯来自尼加拉瓜的哪个产区。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('喀麦隆茄衣配哈拉帕的尼加拉瓜茄芯并不稀奇——高端市场上到处都是——但做法决定一切。奥利瓦为G系列留下的叶子来自中部省的中段：比普通喀麦隆用叶更深、更复杂，却没有留给更贵产品线的 AVO XO 选料那样的成本结构。于是就有了这样一张茄衣：给出巧克力与柔和香料，价格却容得下每天一支。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('تتحدث صفحة الدار (olivacigar.com، اطُّلع عليها في أكتوبر 2026) عن غلاف أفريقي من الكاميرون وحشوات نيكاراغوية «Sun Grown». وتصف الصحافة المتخصصة عام 2007 سيجار Robusto المضغوط في علبة بأنه سيجار بغلاف من الكاميرون وغلاف داخلي وحشوة من نيكاراغوا، والأخيرة من بذرة كوبية. ولا تذكر أي صفحة مقروءة من أي منطقة في الكاميرون جاءت الأوراق، ولا من أي منطقة في نيكاراغوا جاءت الحشوة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('غلاف من الكاميرون فوق حشوة نيكاراغوية من خالابا ليس تركيبًا نادرًا — تجده في كل مكان في السوق الفاخرة — غير أنّ التنفيذ هو ما يغيّر كل شيء. الأوراق التي تحتفظ بها أوليفا للسلسلة G تأتي من الطبقة الوسطى في المقاطعة الوسطى: أدكن وأكثر تركيبًا مما يدخل في الكاميروني المعتاد، دون بنية كلفة منتقيات AVO XO المحفوظة لتشكيلات أغلى. والنتيجة غلاف يعطي الشوكولاتة والتوابل اللطيفة بسعر يسمح بسيجار كل يوم.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La maison annonce des notes de cèdre et de café. Elle propose en octobre 2026 neuf formats, du Special G (3,75 x 48) au Churchill (7 x 50), dont un Figurado, un Torpedo, un Belicoso et un Tubo, ainsi qu''une Serie G Maduro.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La tripe de Jalapa — récoltée sur les plantations d''Oliva — ajoute sous cette douceur la profondeur terreuse propre à la maison. L''ensemble se tient en mi-corsé à corsé, sans la puissance frontale de la Serie V : noisette et chocolat au lait d''abord, puis café et cèdre, vers une finale de poivre doux et de fruits secs. C''est un cigare qui tient sa complexité sur toute sa longueur, sans à-coups d''intensité.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('The house announces notes of cedar and coffee. In October 2026 it offers nine formats, from the Special G (3.75 x 48) to the Churchill (7 x 50), including a Figurado, a Torpedo, a Belicoso and a Tubo, as well as a Serie G Maduro.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('The Nicaraguan filler from Jalapa — harvested from Oliva''s own farms — adds the house''s characteristic earthy depth beneath the Cameroon sweetness. The combination produces a profile that sits at Medium-Full without the aggressive power of the Serie V: hazelnut and milk chocolate lead, transitioning through coffee and cedar toward a finish of mild pepper and dried fruit. It is a cigar that holds complexity across its entire length without sudden intensity spikes.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('La casa anuncia notas de cedro y de café. En octubre de 2026 ofrece nueve formatos, del Special G (3,75 x 48) al Churchill (7 x 50), entre ellos un Figurado, un Torpedo, un Belicoso y un Tubo, además de una Serie G Maduro.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La tripa de Jalapa —cosechada en las plantaciones de Oliva— añade bajo esa dulzura la profundidad terrosa propia de la casa. El conjunto se sostiene en medio a fuerte, sin la potencia frontal de la Serie V: avellana y chocolate con leche primero, luego café y cedro, hacia un final de pimienta suave y frutos secos. Es un puro que mantiene su complejidad de punta a punta, sin sobresaltos de intensidad.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Das Haus gibt Noten von Zeder und Kaffee an. Im Oktober 2026 bietet es neun Formate an, vom Special G (3,75 x 48) bis zum Churchill (7 x 50), darunter ein Figurado, ein Torpedo, ein Belicoso und ein Tubo, dazu eine Serie G Maduro.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Die Einlage aus Jalapa — auf Olivas eigenen Plantagen geerntet — legt unter diese Milde die erdige Tiefe des Hauses. Das Ganze hält sich im mittelkräftigen bis kräftigen Bereich, ohne die frontale Wucht der Serie V: zuerst Haselnuss und Milchschokolade, dann Kaffee und Zeder, hin zu einem Abgang aus milder Pfefferschärfe und Trockenfrüchten. Eine Zigarre, die ihre Vielschichtigkeit über die ganze Länge hält, ohne Sprünge in der Intensität.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('该公司标示有雪松与咖啡的气息。2026年10月提供九种规格，从 Special G（3.75 x 48）到 Churchill（7 x 50），其中包括一款 Figurado、一款 Torpedo、一款 Belicoso 和一款 Tubo，此外还有 Serie G Maduro。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('来自哈拉帕的茄芯——采自奥利瓦自有的种植园——在这份甜润之下垫上本厂特有的泥土般的厚度。整体停在中浓到浓之间，没有V系列那种正面的力道：先是榛子与牛奶巧克力，接着是咖啡与雪松，走向柔和胡椒与坚果干的收尾。这是一支从头到尾把复杂度端稳的雪茄，没有忽强忽弱。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تعلن الدار عن نفحات من خشب الأرز والقهوة. وتعرض في أكتوبر 2026 تسعة أحجام، من Special G (3.75 x 48) إلى Churchill (7 x 50)، منها Figurado وTorpedo وBelicoso وTubo، إضافة إلى Serie G Maduro.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('أما حشوة خالابا — المجنيّة من مزارع أوليفا نفسها — فتضع تحت هذه الحلاوة العمق الترابي الذي تُعرف به الدار. يستقرّ المجموع بين المتوسط والقوي، دون الاندفاع الأمامي للسلسلة V: بندق وشوكولاتة بالحليب أولًا، ثم قهوة وخشب الأرز، نحو نهاية من فلفل لطيف وفواكه مجفّفة. سيجار يحمل تركيبه من أوله إلى آخره، بلا قفزات في الشدّة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Oliva a été fondée en 1995 sous le nom de Gilberto Oliva, devenu Oliva en 1996 (Wikipédia) ; la maison est passée à J. Cortès Cigars N.V. (Belgique) en juillet 2016. L''année de lancement de la Serie G n''est donnée par aucune page de la maison. Wikipédia signale aussi une petite fabrique à Danlí (Honduras) pour des produits d''entrée de gamme de la maison, sans nommer la Serie G.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La Serie G a été conçue comme la porte d''entrée du catalogue — celle qui fait découvrir ce que le tabac de Jalapa sait faire, avant la Serie V et le Melanio. Dans les faits, elle est aussi devenue la gamme vers laquelle les fumeurs expérimentés reviennent quand ils veulent la qualité sans l''exigence physique d''un corsé. Ce double rôle, seuil et destination, compte autant que sa position de ligne la plus accessible du catalogue.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Oliva was founded in 1995 under the name Gilberto Oliva, which became Oliva in 1996 (Wikipedia); the house passed to J. Cortès Cigars N.V. (Belgium) in July 2016. The launch year of the Serie G is not given by any page of the house. Wikipedia also mentions a small factory in Danlí (Honduras) for entry-level products of the house, without naming the Serie G.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The Serie G was designed as the entry point to the Oliva experience — the range that introduces new smokers to what Nicaraguan tobacco from Jalapa can do before they graduate to the fuller expressions of the Serie V and Melanio. In practice, it has also become the range that experienced smokers return to when they want premium quality without the physical demand of a full-body smoke. This dual role — gateway and destination — is what makes the Serie G commercially important beyond its position as the catalog''s most accessible line.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Oliva se fundó en 1995 con el nombre de Gilberto Oliva, que pasó a ser Oliva en 1996 (Wikipedia); la casa pasó a manos de J. Cortès Cigars N.V. (Bélgica) en julio de 2016. Ninguna página de la casa da el año de lanzamiento de la Serie G. Wikipedia señala también una pequeña fábrica en Danlí (Honduras) para productos de entrada de gama de la casa, sin nombrar la Serie G.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La Serie G se concibió como la puerta de entrada del catálogo —la que da a conocer lo que sabe hacer el tabaco de Jalapa, antes de la Serie V y el Melanio. En los hechos, se ha convertido también en la gama a la que vuelven los fumadores experimentados cuando quieren la calidad sin la exigencia física de un fuerte. Ese doble papel, umbral y destino, cuenta tanto como su posición de línea más accesible del catálogo.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Oliva wurde 1995 unter dem Namen Gilberto Oliva gegründet, der 1996 zu Oliva wurde (Wikipedia); das Haus ging im Juli 2016 an J. Cortès Cigars N.V. (Belgien) über. Das Einführungsjahr der Serie G nennt keine Seite des Hauses. Wikipedia erwähnt außerdem eine kleine Fabrik in Danlí (Honduras) für Einstiegsprodukte des Hauses, ohne die Serie G zu nennen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die Serie G war als Eingangstür des Katalogs gedacht — jene, die zeigt, was der Tabak aus Jalapa kann, vor der Serie V und dem Melanio. Tatsächlich ist sie auch zu der Linie geworden, zu der erfahrene Raucher zurückkehren, wenn sie die Qualität ohne die körperliche Forderung einer kräftigen Zigarre wollen. Diese Doppelrolle, Schwelle und Ziel, wiegt so schwer wie ihr Rang als zugänglichste Linie des Katalogs.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Oliva 创立于1995年，当时名为 Gilberto Oliva，1996年改称 Oliva（维基百科）；该公司于2016年7月转归 J. Cortès Cigars N.V.（比利时）。该公司的页面均未给出 Serie G 的推出年份。维基百科还提到该公司在丹利（洪都拉斯）有一家小型工厂，生产入门级产品，但未点名 Serie G。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('G系列本是作为目录的入门而设计的——在V系列与梅拉尼奥之前，先让人见识哈拉帕烟叶的本事。而实际上，它也成了老烟客回头的那条线：想要品质，又不愿承受浓味雪茄对身体的要求。这种既是门槛又是归处的双重角色，与它作为目录中最易入手一线的位置同样要紧。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('تأسست Oliva عام 1995 باسم Gilberto Oliva، ثم صار الاسم Oliva عام 1996 (ويكيبيديا)؛ وانتقلت الدار إلى J. Cortès Cigars N.V. (بلجيكا) في يوليو 2016. ولا تذكر أي صفحة من صفحات الدار سنة إطلاق Serie G. وتشير ويكيبيديا أيضًا إلى مصنع صغير في دانلي (هندوراس) لمنتجات الدار من فئة الدخول، من دون ذكر Serie G.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
UNION ALL SELECT 'Oliva Serie G', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('صُمِّمت السلسلة G لتكون باب الدخول إلى الكتالوغ — تلك التي تعرّف بما يستطيعه تبغ خالابا، قبل السلسلة V وميلانيو. وقد صارت في الواقع أيضًا التشكيلة التي يعود إليها المدخّنون المتمرّسون حين يريدون الجودة دون المطلب الجسدي لسيجار قوي. هذا الدور المزدوج، عتبةً ومقصدًا، لا يقلّ أهمية عن موقعها بوصفها أيسر خطوط الكتالوغ تناولًا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Serie G'
