UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabolisa I (Tabacalera Oliva), Estelí, Nicaragua (Oliva Cigar Co., groupe J. Cortès / Vandermarliere depuis 2016)' AS BINARY)) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve est une ligne de la maison Oliva, roulée à Estelí, au Nicaragua. Stogie Review la présente en février 2009 comme tout juste sortie ; un résultat de recherche (Cigar Inspector, non lu en page) parle de 2008.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('On tient d''ordinaire Oliva pour une maison de puissance. La Serie V, les Master Blends, le Melanio : des cigares construits sur l''intensité nicaraguayenne, ce profil terreux et poivré qui a fait la réputation de la vallée de Jalapa. En lançant une Connecticut Reserve, la maison entrait sur un terrain que beaucoup jugeaient étranger à son savoir-faire.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve is a line from the house of Oliva, rolled in Estelí, Nicaragua. Stogie Review presents it in February 2009 as just released; a search result (Cigar Inspector, not read on the page) mentions 2008.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The conventional wisdom about Oliva is that it means power. The Serie V, the Master Blends, the Melanio — these are cigars built around Nicaraguan intensity, the earthy pepper-driven profile that made the Jalapa Valley''s reputation. When Oliva decided to build a Connecticut Reserve line, it was entering territory many assumed was foreign to the house''s competence and identity.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve es una línea de la casa Oliva, torcida en Estelí, Nicaragua. Stogie Review la presenta en febrero de 2009 como recién salida; un resultado de búsqueda (Cigar Inspector, no leído en la página) habla de 2008.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('A Oliva se la tiene de ordinario por una casa de potencia. La Serie V, los Master Blends, el Melanio: puros construidos sobre la intensidad nicaragüense, ese perfil terroso y apimentado que hizo la reputación del valle de Jalapa. Al lanzar una Connecticut Reserve, la casa entraba en un terreno que muchos juzgaban ajeno a su oficio.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve ist eine Linie des Hauses Oliva, gerollt in Estelí, Nicaragua. Stogie Review stellt sie im Februar 2009 als gerade erschienen vor; ein Suchergebnis (Cigar Inspector, auf der Seite nicht gelesen) spricht von 2008.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Oliva gilt gemeinhin als ein Haus der Kraft. Die Serie V, die Master Blends, der Melanio: Zigarren, die auf nicaraguanischer Intensität gebaut sind, auf jenem erdigen, pfeffrigen Profil, das den Ruf des Jalapa-Tals begründet hat. Mit einer Connecticut Reserve betrat das Haus ein Feld, das viele seinem Können für fremd hielten.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve 是 Oliva 厂的一条产品线，在尼加拉瓜的埃斯特利卷制。Stogie Review 在2009年2月把它介绍为刚刚推出；一条搜索结果（Cigar Inspector，未在页面上读到）则提到2008年。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('人们通常把奥利瓦看作一家做力度的字号。V系列、大师调配、梅拉尼奥：这些雪茄都建立在尼加拉瓜式的浓烈之上，那种让哈拉帕山谷成名的泥土与胡椒气息。推出康涅狄格珍藏时，这家厂踏进了许多人认为与它的手艺无关的地界。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Oliva Connecticut Reserve خطّ إنتاج من دار Oliva، يُلفّ في إستيلي بنيكاراغوا. تقدّمه Stogie Review في فبراير 2009 على أنه صدر للتوّ؛ أما نتيجة بحث (Cigar Inspector، لم تُقرأ في صفحتها) فتذكر عام 2008.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('يُنظر إلى أوليفا عادةً بوصفها دار قوة. السلسلة V، وخلطات المعلّم، وميلانيو: سيجار مبنيّ على الشدّة النيكاراغوية، ذلك الطابع الترابي الفلفلي الذي صنع سمعة وادي خالابا. وبإطلاق «كونيتيكت ريزيرف» دخلت الدار أرضًا رآها كثيرون غريبة عن حرفتها.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La cape est un Connecticut d''Équateur ; le liant et la tripe viennent du Nicaragua, dit la page de la maison (olivacigar.com), ce que confirme Stogie Review en 2009. La maison décrit un cigare de corps moyen, doux et suave, aux notes de bois discrètes ; Stogie Review le range de doux à moyen, au bas du moyen dans le dernier tiers.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le résultat a montré que ce jugement était incomplet. La Connecticut Reserve porte une cape Connecticut Shade d''Équateur, cultivée en altitude dans les Andes — des conditions qui donnent une feuille de plus de caractère que le Connecticut américain, sans lui retirer l''onctuosité qui définit le style de l''ombrière. Cette cape, issue des mêmes plantations qui approvisionnent plusieurs gammes Davidoff, recouvre une tripe nicaraguayenne plus légère que tout ce que compte le catalogue Oliva.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The wrapper is an Ecuadorian Connecticut; the binder and filler come from Nicaragua, says the house''s page (olivacigar.com), which Stogie Review confirms in 2009. The house describes a medium-bodied cigar, mellow and smooth, with discreet notes of wood; Stogie Review places it from mild to medium, at the lower end of medium in the final third.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The result demonstrated that the conventional wisdom was incomplete. The Connecticut Reserve uses an Ecuadorian Connecticut shade wrapper grown at high altitude in the Ecuadorian Andes — conditions that produce a leaf with more character than American Connecticut while preserving the shade-grown creaminess that defines the style. This wrapper, sourced from the same farms that supply several premium Davidoff lines, goes over a Nicaraguan filler blend lighter than anything in the core Oliva catalog.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La capa es un Connecticut de Ecuador; el capote y la tripa vienen de Nicaragua, dice la página de la casa (olivacigar.com), lo que confirma Stogie Review en 2009. La casa describe un puro de cuerpo medio, suave y sedoso, con notas de madera discretas; Stogie Review lo sitúa de suave a medio, en la parte baja del medio en el último tercio.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El resultado mostró que ese juicio era incompleto. La Connecticut Reserve lleva una capa Connecticut Shade de Ecuador, cultivada en altura en los Andes —condiciones que dan una hoja de más carácter que la Connecticut americana, sin quitarle la untuosidad que define el estilo de la sombra. Esa capa, procedente de las mismas plantaciones que abastecen varias gamas Davidoff, recubre una tripa nicaragüense más ligera que todo cuanto contiene el catálogo Oliva.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Das Deckblatt ist ein Connecticut aus Ecuador; Umblatt und Einlage stammen aus Nicaragua, sagt die Seite des Hauses (olivacigar.com), was Stogie Review 2009 bestätigt. Das Haus beschreibt eine Zigarre von mittlerem Körper, mild und weich, mit dezenten Holznoten; Stogie Review ordnet sie von mild bis mittel ein, im letzten Drittel am unteren Ende von mittel.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das Ergebnis hat gezeigt, dass dieses Urteil unvollständig war. Die Connecticut Reserve trägt ein Connecticut-Shade-Deckblatt aus Ecuador, in den Anden in Höhenlage gezogen — Bedingungen, die ein Blatt mit mehr Charakter ergeben als das amerikanische Connecticut, ohne ihm die Cremigkeit zu nehmen, die den Stil des Schattentabaks ausmacht. Dieses Deckblatt, von denselben Plantagen, die mehrere Davidoff-Linien beliefern, umschließt eine nicaraguanische Einlage, die leichter ist als alles andere im Katalog von Oliva.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('茄衣是厄瓜多尔的 Connecticut；茄套叶和茄芯来自尼加拉瓜，厂方页面（olivacigar.com）如此写道，Stogie Review 在2009年也予以证实。厂方描述这是一支中等浓度、柔和顺滑、带含蓄木质气息的雪茄；Stogie Review 将它归为柔和至中度，在后段三分之一处位于中度的偏低一端。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('结果证明这个判断并不完整。康涅狄格珍藏用的是厄瓜多尔的康涅狄格阴植茄衣，种在安第斯的高海拔处——这样的条件长出的叶子比美国康涅狄格更有性格，却不失阴植风格特有的顺滑。这张茄衣来自同时供应多条大卫杜夫产品线的种植园，包裹的是奥利瓦目录中最轻的一副尼加拉瓜茄芯。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('الغلاف من نوع Connecticut إكوادوري؛ أما الغلاف الداخلي والحشوة فمن نيكاراغوا، كما تقول صفحة الدار (olivacigar.com)، وهو ما تؤكده Stogie Review عام 2009. وتصف الدار سيجارًا متوسط الجسم، لطيفًا وسلسًا، بنكهات خشبية خفيفة؛ وتضعه Stogie Review ضمن نطاق من لطيف إلى متوسط، عند الطرف المنخفض من المتوسط في الثلث الأخير.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('أظهرت النتيجة أن هذا الحكم كان ناقصًا. تحمل «كونيتيكت ريزيرف» غلاف كونيتيكت شيد من الإكوادور، مزروعًا على ارتفاع في الأنديز — ظروف تعطي ورقة أكثر شخصية من الكونيتيكت الأمريكية، دون أن تسلبها النعومة الدسمة التي تحدّد أسلوب التبغ المزروع تحت الظلّ. وهذا الغلاف، الآتي من المزارع نفسها التي تزوّد عدة تشكيلات لدى دافيدوف، يغلّف حشوة نيكاراغوية أخفّ من كل ما في كتالوغ أوليفا.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Oliva roule ses cigares premium à Estelí, à Tabolisa I, fabrique principale de la maison selon la presse du métier en 2023. Selon Wikipédia, la maison cultive son propre tabac à Estelí, Condega, Jalapa et Somoto. La maison appartient depuis l''été 2016 à J. Cortès, société belge devenue Vandermarliere Family of Cigars ; la famille Oliva reste active dans l''entreprise.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Ce qu''Oliva apporte à cette formule tient à la précision de son approvisionnement. La maison possède ses plantations nicaraguayennes en propre — les parcelles de Jalapa et d''Estelí qui alimentent tout le catalogue. Elle peut donc prélever, dans son propre stock, des feuilles plus légères et récoltées plus tôt, inutilisables pour la Serie V mais exactement calibrées pour un assemblage moyen-léger. Il en sort un cigare qui offre une vraie complexité — crème, céréales grillées, vanille, cèdre léger — sans le poids qui écraserait un cigare du matin ou le premier de la soirée.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Oliva rolls its premium cigars in Estelí, at Tabolisa I, the house''s main factory according to the trade press in 2023. According to Wikipedia, the house grows its own tobacco in Estelí, Condega, Jalapa and Somoto. Since summer 2016 the house has belonged to J. Cortès, a Belgian company that became Vandermarliere Family of Cigars; the Oliva family remains active in the business.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('What Oliva brings to this formula that other Connecticut-style cigars cannot match is its sourcing precision. The company owns its Nicaraguan farms outright — the Jalapa and Estelí plots that supply the entire Oliva catalog. This allows them to select, from within their own inventory, lighter, earlier-harvested leaves that would be unsuitable for the Serie V but are perfectly calibrated for a medium-light blend. The result is a cigar that delivers genuine complexity — cream, toasted grain, vanilla, light cedar — without the weight that would overwhelm a morning smoke or a first cigar of the evening.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Oliva tuerce sus puros premium en Estelí, en Tabolisa I, fábrica principal de la casa según la prensa del sector en 2023. Según Wikipedia, la casa cultiva su propio tabaco en Estelí, Condega, Jalapa y Somoto. La casa pertenece desde el verano de 2016 a J. Cortès, sociedad belga convertida en Vandermarliere Family of Cigars; la familia Oliva sigue activa en la empresa.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Lo que Oliva aporta a esta fórmula está en la precisión de su abastecimiento. La casa posee sus propias plantaciones nicaragüenses —las parcelas de Jalapa y de Estelí que alimentan todo el catálogo. Puede por tanto tomar, de su propio stock, hojas más ligeras y recogidas antes, inservibles para la Serie V pero exactamente calibradas para una ligada media-ligera. Sale de ahí un puro que ofrece verdadera complejidad —crema, cereales tostados, vainilla, cedro ligero— sin el peso que aplastaría un puro de la mañana o el primero de la noche.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Oliva rollt seine Premium-Zigarren in Estelí, in der Tabolisa I, laut Fachpresse 2023 die Hauptfabrik des Hauses. Laut Wikipedia baut das Haus seinen eigenen Tabak in Estelí, Condega, Jalapa und Somoto an. Seit dem Sommer 2016 gehört das Haus J. Cortès, einem belgischen Unternehmen, das zu Vandermarliere Family of Cigars geworden ist; die Familie Oliva bleibt im Unternehmen aktiv.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Was Oliva dieser Formel hinzufügt, liegt in der Genauigkeit seiner Beschaffung. Das Haus besitzt seine nicaraguanischen Plantagen selbst — die Parzellen in Jalapa und Estelí, die den ganzen Katalog versorgen. Es kann also aus dem eigenen Bestand leichtere, früher geerntete Blätter nehmen, für die Serie V unbrauchbar, für eine mittelleichte Mischung aber genau berechnet. Daraus entsteht eine Zigarre mit wirklicher Vielschichtigkeit — Sahne, geröstetes Getreide, Vanille, leichte Zeder — ohne das Gewicht, das eine Morgenzigarre oder die erste des Abends erdrücken würde.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Oliva 在埃斯特利的 Tabolisa I 卷制高端雪茄；据业内媒体2023年报道，这是该厂的主工厂。据 Wikipedia 所述，该厂在埃斯特利、孔德加、哈拉帕和索莫托自种烟草。自2016年夏天起，该厂隶属比利时公司 J. Cortès，该公司后来成为 Vandermarliere Family of Cigars；Oliva 家族仍在公司中活跃。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('奥利瓦为这一配方带来的，是采购上的精准。厂里自有尼加拉瓜的种植园——哈拉帕与埃斯特利的地块供应整个目录。因此它可以从自家库存里挑出更轻、采得更早的叶子：这些叶子做不了V系列，却正好合乎中轻度配方的分寸。做出来的雪茄有真正的层次——奶油、烤谷物、香草、淡雪松——却没有那份会压垮晨间一支或夜里第一支的重量。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تلفّ Oliva سيجارها الفاخر في إستيلي، في Tabolisa I، وهي مصنع الدار الرئيسي بحسب صحافة المهنة عام 2023. وبحسب Wikipedia، تزرع الدار تبغها الخاص في إستيلي وكوندغا وخالابا وسوموتو. وتعود ملكية الدار منذ صيف 2016 إلى J. Cortès، شركة بلجيكية صارت Vandermarliere Family of Cigars؛ وما زالت عائلة Oliva فاعلة في الشركة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('ما تضيفه أوليفا إلى هذه الوصفة يكمن في دقّة تدبير موادها. فالدار تملك مزارعها النيكاراغوية — قطع خالابا وإستيلي التي تغذّي الكتالوغ كلّه. وبإمكانها من ثمّ أن تنتقي من مخزونها الخاص أوراقًا أخفّ وأبكر جنيًا، لا تصلح للسلسلة V لكنها معايَرة تمامًا لخلطة متوسطة خفيفة. ويخرج من ذلك سيجار يقدّم تركيبًا حقيقيًا — قشدة، وحبوب محمّصة، وفانيليا، وأرز خفيف — دون الثقل الذي يسحق سيجار الصباح أو أوّل سيجار المساء.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Dans la famille Oliva, la ligne se distingue de la marque mère (fiche Oliva) et d''autres lignes de la maison comme Serie V ou Serie G, qui ont chacune leur propre blend.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La Connecticut Reserve a mis à mal l''idée qu''une maison nicaraguayenne ne saurait produire que de l''intensité. Elle a aussi fait connaître le nom d''Oliva à des fumeurs qui évitaient le catalogue entier sur la foi de sa réputation. La gamme a tenu sa ligne d''une boîte à l''autre, ce qui était précisément le pari.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Within the Oliva family, the line stands apart from the parent brand (see the Oliva entry) and from other lines of the house such as Serie V or Serie G, each of which has its own blend.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The Connecticut Reserve challenged the assumption that premium Nicaraguan houses could only produce intensity. It also introduced the Oliva name to a segment of smokers who had avoided the catalog entirely on the basis of its reputation. The range held its line from one box to the next, which is what the strategy was betting on.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Dentro de la familia Oliva, la línea se distingue de la marca madre (ficha Oliva) y de otras líneas de la casa como Serie V o Serie G, que tienen cada una su propia ligada.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('La Connecticut Reserve puso en apuros la idea de que una casa nicaragüense solo sabe producir intensidad. También dio a conocer el nombre de Oliva a fumadores que evitaban el catálogo entero por su reputación. La gama ha mantenido su línea de una caja a otra, que era precisamente la apuesta.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Innerhalb der Familie Oliva unterscheidet sich die Linie von der Muttermarke (Eintrag Oliva) und von anderen Linien des Hauses wie Serie V oder Serie G, die jeweils eine eigene Mischung haben.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Die Connecticut Reserve hat der Vorstellung zugesetzt, ein nicaraguanisches Haus könne nur Intensität hervorbringen. Sie hat den Namen Oliva auch Rauchern nahegebracht, die den ganzen Katalog wegen seines Rufs mieden. Die Linie hat ihre Handschrift von Kiste zu Kiste gehalten, und genau darum ging die Wette.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('在 Oliva 家族之中，这条线有别于母品牌（见 Oliva 条目）以及该厂的其他产品线，如 Serie V 或 Serie G，它们各有自己的配方。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'zh', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('康涅狄格珍藏动摇了「尼加拉瓜字号只会做浓烈」的成见，也让一些因这份名声而绕开整份目录的烟客记住了奥利瓦这个名字。这条线一箱接一箱地守住了自己的调性，而这正是当初下的赌注。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 4 (nouveau texte)', (LOCATE(CAST('ضمن عائلة Oliva، يتميّز هذا الخط عن العلامة الأم (انظر صفحة Oliva) وعن خطوط أخرى للدار مثل Serie V أو Serie G، ولكلٍّ منها خلطته الخاصة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'ar', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('لقد زعزعت «كونيتيكت ريزيرف» الفكرة القائلة إنّ دارًا نيكاراغوية لا تُحسن سوى الشدّة. كما عرّفت باسم أوليفا مدخّنين كانوا يتجنّبون الكتالوغ كلّه بناءً على سمعته. وقد حافظت التشكيلة على خطّها من علبة إلى أخرى، وهو تحديدًا ما كان الرهان عليه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'gamme Connecticut Reserve', (JSON_CONTAINS(JSON_EXTRACT(`gamme`, '$[*].name'), '"Connecticut Reserve"')) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
