UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'gamme Connecticut Reserve (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme`, '$[0].story')) AS BINARY) = CAST('Cape Connecticut d''Équateur, liant et tripe du Nicaragua, selon la page de la maison. Corps moyen selon la maison ; de doux à moyen selon Stogie Review (2009). Formats cités par Stogie Review en 2009 : Lonsdale, Robusto, Toro, Torpedo, Churchill ; la page de la maison montre aussi un Toro Tubo 6 x 50.' AS BINARY)) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'gamme Connecticut Reserve', (JSON_CONTAINS(JSON_EXTRACT(`gamme_en`, '$[*].name'), '"Connecticut Reserve"')) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'gamme Connecticut Reserve (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_en`, '$[0].vitolas')) = 5) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
UNION ALL SELECT 'Oliva Connecticut Reserve', 'en', 'gamme Connecticut Reserve (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_en`, '$[0].story')) AS BINARY) = CAST('Ecuadorian Connecticut wrapper, Nicaraguan binder and filler, according to the house''s page. Medium body according to the house; mild to medium according to Stogie Review (2009). Formats cited by Stogie Review in 2009: Lonsdale, Robusto, Toro, Torpedo, Churchill; the house''s page also shows a Toro Tubo 6 x 50.' AS BINARY)) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
