UNION ALL SELECT 'Oliva Connecticut Reserve', 'fr', 'source (correction)', (LOCATE(CAST('olivacigar.com « Connecticut Reserve - Mellow Anytime Cigar » (cape Équateur, liant et filler Nicaragua, corps moyen) ; stogiereview.com « Oliva Connecticut Reserve » (2009-02-28, mis à jour 2015-08-17 : nouvelle sortie, cape Connecticut équatorienne, Estelí, formats) ; cigaraficionado.com « A New Era of Oliva » (juillet/août 2023 : Tabolisa I, fabrique principale d''Estelí ; J. Cortès 2016 devenue Vandermarliere Family of Cigars) ; en.wikipedia.org « Oliva Cigar Co. » (fabrique d''Estelí, rachat J. Cortès à l''été 2016, fermes d''Estelí, Condega, Jalapa, Somoto)' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Oliva Connecticut Reserve'
