UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabacalera Perdomo, Estelí, Nicaragua ; cape Connecticut cultivée en Équateur et expédiée au Nicaragua (eldiario.ec, 2025)' AS BINARY)) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo est une maison familiale lancée en août 1992 à Miami par Nick Perdomo Jr. ; ses cigares sont roulés à Estelí, au Nicaragua, où une première installation date de 1997 et une usine sur mesure de 1999 (Wikipédia). Dès ses débuts, selon Wikipédia, elle associait des capes d''Équateur à des tripes d''Amérique centrale.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('L''histoire du Connecticut Shade compte deux chapitres. Le premier se déroule dans la vallée du Connecticut, où un sol sableux et une lumière diffuse produisent depuis plus de deux siècles la cape qui a fait la réputation du tabac américain. Le second — moins connu, et à certains égards plus intéressant — se joue en Équateur, où les planteurs ont compris dans les années 1990 que l''altitude quasi équatoriale et une couverture nuageuse constante pouvaient reproduire les conditions qui font la singularité du Connecticut Shade.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo is a family house launched in August 1992 in Miami by Nick Perdomo Jr.; its cigars are rolled in Estelí, Nicaragua, where a first facility dates from 1997 and a purpose-built factory from 1999 (Wikipedia). From its beginnings, according to Wikipedia, it paired Ecuadorian wrappers with Central American fillers.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The Connecticut shade tobacco story has two chapters. The first is set in the Connecticut River Valley, where sandy soil and diffuse light have produced the wrapper leaf that made American tobacco''s reputation, for over two centuries. The second chapter — less familiar, and in some respects more interesting — is set in Ecuador, where farmers recognized in the 1990s that the country''s near-equatorial altitude and constant cloud cover could replicate the conditions that make Connecticut shade distinctive, and potentially improve on them.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo es una casa familiar lanzada en agosto de 1992 en Miami por Nick Perdomo Jr.; sus puros se tuercen en Estelí, Nicaragua, donde una primera instalación data de 1997 y una fábrica a medida de 1999 (Wikipedia). Desde sus comienzos, según Wikipedia, combinaba capas de Ecuador con tripas de Centroamérica.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La historia del Connecticut Shade tiene dos capítulos. El primero transcurre en el valle del Connecticut, donde un suelo arenoso y una luz difusa producen desde hace más de dos siglos la capa que hizo la reputación del tabaco estadounidense. El segundo —menos conocido, y en ciertos aspectos más interesante— se juega en Ecuador, donde los plantadores comprendieron en los años noventa que la altitud casi ecuatorial y una cobertura de nubes constante podían reproducir las condiciones que hacen la singularidad del Connecticut Shade.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo ist ein Familienhaus, das im August 1992 in Miami von Nick Perdomo Jr. ins Leben gerufen wurde; seine Zigarren werden in Estelí, Nicaragua, gerollt, wo eine erste Anlage aus dem Jahr 1997 und eine eigens errichtete Fabrik aus dem Jahr 1999 stammen (Wikipedia). Von Anfang an verband es laut Wikipedia Deckblätter aus Ecuador mit Einlagen aus Mittelamerika.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Geschichte des Connecticut Shade hat zwei Kapitel. Das erste spielt im Connecticut-Tal, wo ein sandiger Boden und ein gestreutes Licht seit mehr als zwei Jahrhunderten das Deckblatt hervorbringen, das den Ruf des amerikanischen Tabaks begründet hat. Das zweite — weniger bekannt und in mancher Hinsicht interessanter — spielt in Ecuador, wo die Pflanzer in den neunziger Jahren begriffen, dass die fast äquatoriale Höhenlage und eine gleichbleibende Wolkendecke jene Bedingungen nachbilden können, die das Connecticut Shade einzigartig machen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo 是一家家族字号，1992年8月由 Nick Perdomo Jr. 在迈阿密创办；其雪茄在尼加拉瓜的埃斯特利卷制，那里1997年有了初期设施，1999年有了量身定制的工厂（Wikipedia）。据 Wikipedia，它从创办之初就把厄瓜多尔茄衣与中美洲茄芯搭配在一起。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('康涅狄格阴植叶的历史有两章。第一章发生在康涅狄格河谷：那里的砂质土壤与散射光，两个多世纪以来出产着成就美国烟草声誉的茄衣。第二章鲜为人知，某种意义上却更有意思——它发生在厄瓜多尔。九十年代，那里的种植者发现，近赤道的高海拔与恒常的云层，能够复现出使康涅狄格阴植叶与众不同的那些条件。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Perdomo دار عائلية أُطلقت في أغسطس 1992 في ميامي على يد Nick Perdomo Jr.؛ وتُلفّ سيجارها في إستيلي بنيكاراغوا، حيث يعود تاريخ منشأة أولى إلى عام 1997 ومصنع مصمَّم خصيصًا إلى عام 1999 (Wikipedia). ومنذ بداياتها، بحسب Wikipedia، كانت تجمع أغلفة من الإكوادور بحشوات من أمريكا الوسطى.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('لتاريخ كونيتيكت شيد فصلان. يجري الأول في وادي كونيتيكت، حيث تنتج تربة رملية وضوء منتشر، منذ أكثر من قرنين، الغلاف الذي صنع سمعة التبغ الأمريكي. أما الثاني — وهو أقلّ شهرة، وأطرف من بعض الوجوه — فيجري في الإكوادور، حيث أدرك المزارعون في التسعينيات أنّ الارتفاع شبه الاستوائي وغطاءً سحابيًّا ثابتًا يمكن أن يعيدا إنتاج الظروف التي تصنع تفرّد كونيتيكت شيد.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Le classement suit le pays de roulage, le Nicaragua. La cape, elle, vient d''Équateur : une graine du Connecticut cultivée sans ombrière dans le climat côtier, surtout dans la région de Los Ríos, puis expédiée au Nicaragua pour l''assemblage (eldiario.ec, 9 juillet 2025). Sur la page de la maison (perdomocigars.com, octobre 2026), la ligne Legacy Ecuadorian Connecticut associe une cape Ecuadorian Connecticut, un liant Nicaraguan Shade Grown et une tripe nicaraguayenne de graine cubaine, avec des tabacs cultivés à Estelí, Condega et dans la vallée de Jalapa. Aucune ligne nommée « Ecuador » ne figure sur le site de la maison en octobre 2026.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Le Connecticut Shade équatorien pousse à des altitudes où l''air plus rare et la diffusion régulière des nuages créent naturellement ce que les planteurs du Connecticut doivent obtenir à l''aide d''ombrières. Il en sort une feuille qui garde l''onctuosité propre au Connecticut, avec une complexité supplémentaire tirée des sols volcaniques et du microclimat des Andes. Plusieurs grandes maisons — Davidoff au premier rang — s''approvisionnent aujourd''hui en Équateur plutôt que dans le Connecticut.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('The classification follows the country of rolling, Nicaragua. The wrapper, for its part, comes from Ecuador: Connecticut seed grown without shade cloth in the coastal climate, chiefly in the Los Ríos region, then shipped to Nicaragua for blending (eldiario.ec, 9 July 2025). On the house''s page (perdomocigars.com, October 2026), the Legacy Ecuadorian Connecticut line pairs an Ecuadorian Connecticut wrapper, a Nicaraguan Shade Grown binder and a Nicaraguan filler of Cuban seed, with tobaccos grown in Estelí, Condega and the Jalapa valley. No line named "Ecuador" appears on the house''s website in October 2026.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ecuadorian Connecticut shade grows at elevations where thinner air and consistent cloud diffusion create natural growing conditions analogous to the shade tents that Connecticut farmers must construct artificially. The result is a leaf with the signature Connecticut creaminess, but with additional complexity derived from volcanic soils and the specific microclimate of the Ecuadorian Andes. Several major manufacturers — Davidoff prominently among them — now source their Connecticut-style wrappers from Ecuador rather than Connecticut itself.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La clasificación sigue el país de torcido, Nicaragua. La capa, en cambio, viene de Ecuador: una semilla del Connecticut cultivada sin toldo en el clima costero, sobre todo en la región de Los Ríos, y luego enviada a Nicaragua para la ligada (eldiario.ec, 9 de julio de 2025). En la página de la casa (perdomocigars.com, octubre de 2026), la línea Legacy Ecuadorian Connecticut combina una capa Ecuadorian Connecticut, un capote Nicaraguan Shade Grown y una tripa nicaragüense de semilla cubana, con tabacos cultivados en Estelí, Condega y el valle de Jalapa. Ninguna línea llamada «Ecuador» figura en el sitio de la casa en octubre de 2026.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El Connecticut Shade ecuatoriano crece a altitudes donde el aire más ligero y la difusión regular de las nubes crean de forma natural lo que los plantadores del Connecticut deben obtener con toldos de sombra. De ahí sale una hoja que conserva la untuosidad propia del Connecticut, con una complejidad añadida que le dan los suelos volcánicos y el microclima de los Andes. Varias casas grandes —Davidoff en primer lugar— se abastecen hoy en Ecuador antes que en el Connecticut.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Einordnung folgt dem Land des Rollens, Nicaragua. Das Deckblatt dagegen stammt aus Ecuador: Connecticut-Saatgut, ohne Schattentuch im Küstenklima angebaut, vor allem in der Region Los Ríos, dann zur Mischung nach Nicaragua verschifft (eldiario.ec, 9. Juli 2025). Auf der Seite des Hauses (perdomocigars.com, Oktober 2026) verbindet die Linie Legacy Ecuadorian Connecticut ein Deckblatt Ecuadorian Connecticut, ein Umblatt Nicaraguan Shade Grown und eine nicaraguanische Einlage aus kubanischem Saatgut, mit Tabaken aus Estelí, Condega und dem Jalapa-Tal. Eine Linie namens „Ecuador“ steht im Oktober 2026 nicht auf der Seite des Hauses.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das ecuadorianische Connecticut Shade wächst in Höhen, in denen die dünnere Luft und die gleichmäßige Streuung der Wolken von selbst schaffen, was die Pflanzer in Connecticut mit Schattentüchern herstellen müssen. Daraus entsteht ein Blatt, das die für Connecticut typische Cremigkeit behält, mit einer zusätzlichen Vielschichtigkeit aus den vulkanischen Böden und dem Kleinklima der Anden. Mehrere große Häuser — Davidoff an erster Stelle — beziehen ihre Blätter heute eher aus Ecuador als aus Connecticut.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('归类依据卷制国家，即尼加拉瓜。而茄衣来自厄瓜多尔：康涅狄格种子，在沿海气候中不搭遮阴棚栽种，主要集中在 Los Ríos 地区，随后运往尼加拉瓜进行配方（eldiario.ec，2025年7月9日）。在厂方页面（perdomocigars.com，2026年10月）上，Legacy Ecuadorian Connecticut 系列将 Ecuadorian Connecticut 茄衣、Nicaraguan Shade Grown 茄套叶与古巴种子的尼加拉瓜茄芯搭配，烟草种于埃斯特利、孔德加和哈拉帕山谷。2026年10月，厂方网站上没有名为「Ecuador」的产品线。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('厄瓜多尔的康涅狄格阴植叶长在高处：稀薄的空气与云层均匀的散射，天然造就了康涅狄格种植者必须靠遮阴布才能得到的环境。由此长出的叶子保留了康涅狄格特有的顺滑，又从火山土壤与安第斯的小气候里多得一层复杂。如今好几家大字号——大卫杜夫居首——的进货地已是厄瓜多尔而非康涅狄格。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يتبع التصنيف بلد اللفّ، أي نيكاراغوا. أما الغلاف فمن الإكوادور: بذرة كونيتيكت تُزرع بلا مظلّات تظليل في المناخ الساحلي، ولا سيما في منطقة Los Ríos، ثم تُشحن إلى نيكاراغوا للخلط (eldiario.ec، 9 يوليو 2025). وفي صفحة الدار (perdomocigars.com، أكتوبر 2026) يجمع خط Legacy Ecuadorian Connecticut غلافًا Ecuadorian Connecticut وغلافًا داخليًا Nicaraguan Shade Grown وحشوة نيكاراغوية من بذرة كوبية، مع تبغ مزروع في إستيلي وكوندغا ووادي خالابا. ولا يظهر أي خط باسم «Ecuador» على موقع الدار في أكتوبر 2026.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('ينمو كونيتيكت شيد الإكوادوري على ارتفاعات يخلق فيها الهواء الأرقّ وانتشار السحب المنتظم، بشكل طبيعي، ما على مزارعي كونيتيكت أن يحصّلوه بأقمشة التظليل. ومن ذلك تخرج ورقة تحتفظ بالنعومة الدسمة الخاصة بكونيتيكت، مع تركيب إضافي تمنحه التربة البركانية ومناخ الأنديز الصغير. وعدة دور كبرى — دافيدوف في مقدّمتها — تتزوّد اليوم من الإكوادور لا من كونيتيكت.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('La gamme Ecuador de Perdomo bâtit toute sa proposition sur ce choix d''approvisionnement. La cape, issue de cette culture d''altitude, apporte à l''assemblage une texture plus soyeuse et une teneur en huiles plus marquée que le Connecticut Shade courant. Dessous, une tripe nicaraguayenne de Jalapa — plus légère que celle du Perdomo 20th Anniversary, calibrée pour laisser la cape mener — donne des notes de crème, de vanille douce et de céréales grillées, sans le poids qui écraserait la délicatesse de l''Ecuador.

' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Perdomo Ecuador'
UNION ALL SELECT 'Perdomo Ecuador', 'en', 'histoire 3 (ancien texte parti)', (LOCATE(CAST(CONCAT('Perdomo''s Ecuador range builds its entire proposition around this sourcing choice. The wrapper is the product of high-altitude Ecuadorian cultivation, bringing to the blend a silkier texture and more pronounced oil content than standard Connecticut shade. Beneath it, a Nicaraguan Jalapa filler blend — lighter than what appears in the Perdomo 20th Anniversary, calibrated specifically to allow the wrapper to lead — delivers notes of cream, mild vanilla, and toasted grain without the weight that would overwhelm the Ecuador''s inherent delicacy.', CHAR(13), '
', CHAR(13), '
